# The slugs written before the rename: a settings row, an appointment or an
# old jawnos-theme.txt may still say one of these, and it must paint the same
# room. Each is also kept in %theme_presets as an alias row so the save route,
# which refuses a preset's name, cannot let a saved theme take one - but
# theme_registry() skips alias rows, so the gallery and the appointment picker
# list only the new names.
our %theme_aliases = (
	windows  => 'jawndows',
	macos    => 'cuperjawno',
	cutefish => 'jawnfish',
	deepin   => 'deepjawn',
);
foreach my $old ( keys %theme_aliases ) {
	my $renamed = $theme_aliases{$old};
	$theme_presets{$old} = { %{ $theme_presets{$renamed} }, alias_to => $renamed };
}

# The slug whose bundle a name wears: a renamed preset's old slug resolves to
# the new one, and every other name (a current preset, a saved theme or a bare
# colour scheme) is returned untouched.
sub theme_canonical {
	my ($name) = @_;
	return '' unless defined $name && length $name;
	return $theme_aliases{$name} // $name;
}

# A saved theme lives as one settings row: app misc, setting
# appearance_theme_custom, subsetting <slug>, value a small JSON document. The
# row is house-wide (device 'all') because an appointment may name it on any
# machine. Memoised for a second: icon_set() and texture_name() ask on every
# render, and each read is a query.
my ($theme_registry_memo, $theme_registry_time);
sub theme_registry() {
	my $now = &rightNow();
	return $theme_registry_memo if $theme_registry_memo && $now - $theme_registry_time < 1000;
	my %registry;
	foreach my $slug ( keys %theme_presets ) {
		# an alias row is a compatibility key, not a card: a renamed preset is
		# offered once, under its new slug
		next if $theme_presets{$slug}->{'alias_to'};
		$registry{$slug} = { %{ $theme_presets{$slug} }, slug => $slug, builtin => 1 };
	}
	my $rows = eval {
		&db_query("select subsetting, value from settings where app = 'misc' and setting = 'appearance_theme_custom' and subsetting is not null and value is not null and value != ''")->hashes;
	} || [];
	foreach my $row ( @{$rows} ) {
		my $slug = $row->{'subsetting'} // '';
		next unless $slug =~ /^[a-z0-9][a-z0-9_-]{0,39}$/;
		# a stale custom row under a pre-rename slug must not shadow the preset
		# that slug now resolves to
		next if $theme_aliases{$slug};
		my $data = eval { decode_json($row->{'value'}) };
		next unless ref $data eq 'HASH';
		$registry{$slug} = { %{$data}, slug => $slug, builtin => 0 };
	}
	$theme_registry_memo = \%registry;
	$theme_registry_time = $now;
	return $theme_registry_memo;
}

# A name an appointment may store: a saved/preset theme or a bare colour scheme
# (the older values still in the table). A pre-rename preset slug is resolved to
# the renamed bundle first, so an old row keeps dressing the desk.
sub theme_known {
	my ($name) = @_;
	return 0 unless defined $name && length $name;
	$name = &theme_canonical($name);
	return 1 if $colour_schemes{$name};
	my $registry = &theme_registry();
	return $registry->{$name} ? 1 : 0;
}

sub theme_safe_font {
	my ($font) = @_;
	return '' unless defined $font && length $font;
	foreach my $f ( @gb::theme_fonts ) {
		return $f->{'value'} if $f->{'value'} eq $font;
	}
	return '';
}

sub theme_safe_corner {
	my ($corner) = @_;
	return '' unless defined $corner && $corner =~ /^\s*(\d{1,2})\s*(?:px)?\s*$/;
	my $n = $1 + 0;
	return '' if $n > 28;
	return $n . 'px';
}

# A name -> the whole bundle. Unknown names resolve to an empty bundle, which
# means "the Misc settings are in charge". A bare colour-scheme name resolves
# to that scheme and nothing else, so rows written before themes existed keep
# their meaning.
sub theme_bundle {
	my ($name) = @_;
	return {} unless defined $name && length $name;
	# an old slug is the renamed bundle: the returned slug (and so the name the
	# gallery, the push and the appointment label show) is the current one
	$name = &theme_canonical($name);
	my $registry = &theme_registry();
	my $theme = $registry->{$name};
	$theme = { scheme => $name } if !$theme && $colour_schemes{$name};
	return {} unless $theme;
	my $scheme = $theme->{'scheme'} // '';
	$scheme = '' unless $colour_schemes{$scheme};
	my $background = $theme->{'background'} // '';
	$background = '' unless $background =~ /^\#?[0-9a-fA-F]{6}$/;
	$background = '#' . $background if $background =~ /^[0-9a-fA-F]{6}$/;
	my $bg = $scheme ? &colour_scheme_manager_colour($scheme) : $background;
	my $icon_set = $theme->{'icon_set'} // '';
	$icon_set = '' unless grep { $_ eq $icon_set } @gb::icon_sets;
	my $texture = $theme->{'texture'} // '';
	$texture = '' unless grep { $_ eq $texture } @gb::textures;
	my $accent = $theme->{'accent'} // '';
	$accent = '' unless $accent =~ /^\#?[0-9a-fA-F]{6}$/;
	$accent = '#' . $accent if $accent =~ /^[0-9a-fA-F]{6}$/;
	# A theme that names no accent takes its scheme's own accent step, not a
	# colour derived from the manager surface: on a charcoal window the derived
	# hue is grey and the active tile loses the theme's colour entirely.
	if (!length $accent && $scheme && ref $colour_schemes{$scheme} eq 'ARRAY') {
		my $pal = $colour_schemes{$scheme};
		my $dark = 0;
		if (defined $bg && $bg =~ /^\#?([0-9a-fA-F]{6})$/) {
			my ($r, $g, $b) = map { hex } ($1 =~ /(..)(..)(..)/);
			$dark = ((0.2126 * $r + 0.7152 * $g + 0.0722 * $b) / 255) < 0.5 ? 1 : 0;
		}
		$accent = $pal->[ $dark ? 5 : 4 ] // $pal->[4] // '';
		$accent = '#' . $accent if $accent =~ /^[0-9a-fA-F]{6}$/;
	}
	return {
		slug       => $name,
		name       => $theme->{'name'} // $name,
		builtin    => $theme->{'builtin'} ? 1 : 0,
		scheme     => $scheme,
		background => $bg,
		icon_set   => $icon_set,
		texture    => $texture,
		font       => &theme_safe_font($theme->{'font'}),
		corner     => &theme_safe_corner($theme->{'corner'}),
		accent     => $accent,
	};
}

# The theme in charge: a running start/record appointment first, then the
# Misc Appearance choice. Blank means the Misc surfaces are in charge.
sub active_theme_name {
	my $theme = &running_appointment_theme();
	return &theme_canonical($theme) if defined $theme && length $theme;
	my $picked = &misc_setting('appearance_theme');
	return &theme_canonical($picked) if defined $picked && length $picked && &theme_known($picked);
	return '';
}
sub active_theme_bundle {
	# The running appointment's theme sits over the Misc theme: a field the
	# running theme does not name (a legacy colour-scheme row has no icons or
	# material) is taken from the Misc theme, so a start appointment never
	# undresses the desk by accident.
	my $running = &running_appointment_theme();
	my $picked = &misc_setting('appearance_theme');
	$picked = '' unless defined $picked && length $picked && &theme_known($picked);
	my $system = length $picked ? &theme_bundle($picked) : {};
	if (defined $running && length $running) {
		my $over = &theme_bundle($running);
		my %merged = %{$system};
		foreach my $key ( qw/scheme background icon_set texture font corner accent name/ ) {
			$merged{$key} = $over->{$key} if defined $over->{$key} && length $over->{$key};
		}
		$merged{'slug'} = &theme_canonical($running);
		$merged{'appointment'} = 1;
		return \%merged;
	}
	$system->{'appointment'} = 0 if ref $system eq 'HASH';
	return $system;
}

# A scheme's manager surface and its window surface. The palette is applied
# across @gb::misc_settings by index, so the manager is the same colour the Misc
# panel writes into manager_background_colour when the scheme is picked; the
# window is the next step of the same ramp, which keeps every theme's windows
# distinct from its desktop while staying in its motif.
sub colour_scheme_window_colour {
	my ($name) = @_;
	return undef unless defined $name && length $name;
	my $palette = $colour_schemes{$name};
	return undef unless ref $palette eq 'ARRAY' && scalar @{$palette} > 3;
	return $palette->[3];
}

# The scheme a manager colour came from, so a server-rendered desktop can pick
# its curated window colour. A hand-picked colour finds no scheme and gets a
# derived shade instead (theme_panel_css).
sub colour_scheme_for_manager_colour {
	my ($bg) = @_;
	return '' unless defined $bg && length $bg;
	my $target = lc $bg;
	$target = '#' . $target unless $target =~ /^#/;
	foreach my $name ( @colour_scheme_order ) {
		my $manager = $colour_schemes{$name}->[2];
		return $name if defined $manager && lc($manager) eq $target;
	}
	return '';
}

sub colour_scheme_manager_colour {
	my ($name) = @_;
	return undef unless defined $name && length $name;
	my $palette = $colour_schemes{$name};
	return undef unless ref $palette eq 'ARRAY' && scalar @{$palette};
	my $index = 0;
	my $found = 0;
	foreach my $key ( @gb::misc_settings ) {
		if ($key eq 'manager') { $found = 1; last; }
		$index++;
	}
	return undef unless $found;
	return $palette->[ $index % scalar @{$palette} ];
}

# The dark-theme counterpart of an appointment's colour. The named schemes ship
# a light and a dark cut with the same ramp, so a colour from a light scheme maps
# straight to the same step of its dark pair - the face the app would have been
# given had it been born on a dark desktop. A colour no scheme knows keeps its
# hue and its place on the lightness ramp, pulled into the dark desktop's range:
# the ramp's steps stay distinct instead of collapsing onto one tone.
sub dark_colour_for {
	my ($colour) = @_;
	return $colour unless defined $colour && $colour =~ /^\#?([0-9a-fA-F]{6})$/;
	my $hex = lc('#' . $1);
	foreach my $name ( @colour_scheme_order ) {
		next if $name =~ / Dark$/;
		my $palette = $colour_schemes{$name};
		next unless ref $palette eq 'ARRAY';
		my $index = 0;
		foreach my $step ( @{$palette} ) {
			if (lc($step) eq $hex) {
				my $dark = $colour_schemes{$name . ' Dark'};
				return $dark->[$index] if ref $dark eq 'ARRAY' && defined $dark->[$index];
				last;
			}
			$index++;
		}
	}
	# $hex still carries the leading '#'; strip it before reading the three
	# channels, or hex('#f') warns and the red channel becomes 0.
	my ($r, $g, $b) = map { hex } (substr($hex, 1) =~ /(..)(..)(..)/);
	my ($h, $s, $l) = &_rgb_to_hsl($r, $g, $b);
	$s = 0.62 if $s > 0.62;
	my $target = 0.18 + (0.34 * $l);
	return lc &_hsl_to_hex($h, $s, $target);
}

# Every app's chosen theme in one read, for the appointment list (one query
# rather than one per app block). A house-wide row wins, then this device's,
# then the person's.
sub app_theme_map {
	my %rank = ( 'all' => 3, &device_setter() => 2, &signatorial_designer() => 1 );
	my %map;
	my %best;
	my $rows = eval { &db_query("select app, device, value from settings where setting = ? and value is not null and value != ''", 'theme')->hashes } || [];
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'};
		my $rank = $rank{ $row->{'device'} // '' } || 0;
		next unless $app && $rank;
		next if defined $best{$app} && $best{$app} >= $rank;
		$best{$app} = $rank;
		$map{$app} = $row->{'value'};
	}
	return \%map;
}

# The theme an actively running start/record appointment asks for: the most
# recently started one that has a theme. One join rather than a settings read
# per open row - a stale run must not cost the desktop a query per appointment.
# Blank when none is running.
sub running_appointment_theme {
	my $now = &rightNow();
	my $device = &device_setter();
	my $signatorial = &signatorial_designer();
	my $rows = eval {
		&db_query(
			"select a.app as app, a.timestamp as timestamp, s.value as theme, s.device as theme_device "
			. "from appointments a join settings s on s.app = a.app and s.setting = ? "
			. "where (a.type = ? or a.type = ?) and a.stop_seen is null and a.timestamp is not null and a.timestamp <= ? "
			. "and s.value is not null and s.value != '' and s.device in (?, ?, ?) "
			. "order by a.timestamp desc, "
			. "(case s.device when 'all' then 3 when ? then 2 when ? then 1 else 0 end) desc "
			. "limit 200",
			'theme', 'start', 'record', $now, 'all', $device, $signatorial, $device, $signatorial
		)->hashes;
	} || [];
	foreach my $row ( @{$rows} ) {
		my $theme = $row->{'theme'};
		return $theme if defined $theme && length $theme && &theme_known($theme);
	}
	return '';
}

# The manager background the desktop should paint now, plus the appointment
# theme driving it (blank when the Misc system theme is in charge). Both come
# from theme_state(), so a render asks the running-appointment query once.
sub active_manager_background {
	my (undef, $theme, $bg) = &theme_state();
	return ($bg, $theme);
}

# Tell every open manager to re-paint its body for the current active theme.
# A theme is more than a colour: the message carries the whole bundle, so the
# icons, material, face and corner change with it and no reload is needed.
sub appointment_theme_push {
	# the running set may have just changed: a warm memo would send the room the
	# desk is leaving, so forget every theme cache before asking
	&icon_set_forget();
	my (undef, undef, $bg, $bundle, undef, $appointment) = &theme_state();
	return unless defined $bg && length $bg;
	# The effective values, not the bundle's defaults: an icon/texture/corner
	# override chosen on top of the theme is part of what the desk is wearing. The
	# signature lets the browser ignore a push that changes nothing - a start or
	# stop on the same theme must not reload every window.
	my $icon_set = &icon_set();
	my $texture = &texture_name();
	my $font = $bundle->{'font'} || &misc_setting('title_font') || 'system-ui, sans-serif';
	# the corner the desk is wearing: the theme's own, or the Misc override on
	# top of it. Empty with no theme, so the browser falls back to the Misc
	# slider's --corner_radius there.
	my $corner = $bundle->{'slug'} ? &corner_radius() . 'px' : '';
	my $accent = $bundle->{'accent'} || '';
	my $signature = &theme_signature();
	my %send = (
		background => $bg,
		appointment => $appointment ? 1 : 0,
		icon_set => $icon_set,
		texture => $texture,
		font => $font,
		corner => $corner,
		accent => $accent,
		signature => $signature,
	);
	&Websocket::send('server', { console => 'jawnosThemeBundleApply(' . encode_json(\%send) . ');' });
}

# What the desk currently wears, as one comparable string: paint, effective
# glyphs, material, face and corner. The appointment flag is deliberately left
# out - it changes who owns the desk, not how it is painted - so a start/stop on
# the same theme pushes nothing and reloads no window.
sub theme_signature {
	my $bundle = &active_theme_bundle();
	my $bg = $bundle->{'background'} // '';
	my $font = $bundle->{'font'} || &misc_setting('title_font') || 'system-ui, sans-serif';
	my $corner = $bundle->{'slug'} ? &corner_radius() . 'px' : '';
	my $accent = $bundle->{'accent'} || '';
	return join '|', map { defined $_ ? $_ : '' } ( $bg, &icon_set(), &texture_name(), $font, $corner, $accent );
}

# The colours the current theme is built from: the distinct *_background_colour
# swatches for a device (falling back through the other devices if unset).
sub theme_palette() {
	my $device = shift || &subs::device_setter();
	my $config = &subs::config_reader();
	my @devices = ( $device, @gb::device_types, &subs::signatorial_designer() );
	my %tried;
	foreach my $dt ( @devices ) {
		next if $tried{$dt}++;
		next unless $config->{$dt};
		my %seen;
		my @palette;
		foreach my $k ( @gb::misc_settings ) {
			my $c = $config->{$dt}->{$k}->{'background_colour'};
			next unless $c;
			$c = '#' . $c unless $c =~ /^#/;
			next unless $c =~ /^#[0-9a-fA-F]{6}$/;
			$c = lc $c;
			push @palette, $c unless $seen{$c}++;
		}
		return @palette if scalar @palette;
	}
	return ();
}

sub random_colour_grabber() {
	my @palette = &theme_palette();
	if (scalar @palette > 0) {
		my $pick = $palette[ int(rand(scalar @palette)) ];
		$pick =~ s/^#//;
		return $pick;
	}

	my $col = [ 0, 0, 0 ];
	foreach my $co ( @{$col} ) {
		until ($co > 130) {
			$co = rand(255);
		}
	}
	return join "", map { sprintf "%02x", $col->[$_] } (0..2);
}

# Snap an app's colour into the theme. If the existing colour is already one of
# the theme's colours it is left alone; otherwise a stable theme colour is chosen
# for that app and saved. With no theme colours configured, the value is returned
# unchanged.
sub theme_colour_grabber() {
	my $data = ( ref $_[0] eq 'HASH' ) ? $_[0] : { app => $_[0] };
	my $app = $data->{'app'};
	return $data->{'existing'} unless $app;
	my $device = $data->{'device'} || &subs::device_setter();

	my $existing = $data->{'existing'};
	unless (defined $existing) {
		my $q = &db_select('settings', ['value'], { app => $app, setting => 'colour', device => $device })->hashes;
		$q = &db_select('settings', ['value'], { app => $app, setting => 'colour' })->hashes unless scalar @{$q};
		$existing = $q->[-1]->{'value'} if scalar @{$q};
	}

	my @palette = &theme_palette($device);
	return $existing unless scalar @palette;

	my $normalized = defined $existing ? lc $existing : '';
	$normalized = '#' . $normalized if $normalized =~ /^[0-9a-f]{6}$/;
	if (grep { $_ eq $normalized } @palette) {
		return $existing;
	}

	my $sum = 1;
	$sum += ord for split //, $app;
	my $colour = $palette[ $sum % scalar @palette ];

	&setting_setter({ app => $app, setting => 'colour', value => $colour, device => $device, silent => 'yes' });
	return $colour;
}

# Wrapper used by the getters: skips the built-in apps and blank names.
sub theme_colour_for_app() {
	my ($app, $existing, $device) = @_;
	return $existing unless $app;
	foreach my $p ( @gb::protected ) {
		return $existing if lc($p) eq lc($app);
	}
	return &theme_colour_grabber({ app => $app, existing => $existing, device => $device });
}

# The currently selected pseudonym icon set ('' for the modern default). Memoised
# per process with a short TTL: icon_for() runs once per icon on every render and
# each miss costs a config read (a DB query plus Sereal decode).
my $icon_set_memo;
my $icon_set_memo_time = 0;

# Whether the active desktop theme is dark, and the scheme name driving it (blank
# when the Misc manager colour is in charge). Memoised on the same short TTL as
# icon_set() because a render asks it once per icon and once per surface.
my ($theme_state_memo, $theme_state_time);
sub theme_state() {
	my $now = &rightNow();
	return @{$theme_state_memo} if $theme_state_memo && $now - $theme_state_time < 1000;
	my $bundle = &active_theme_bundle();
	my $name = $bundle->{'slug'} // '';
	my $appointment = $bundle->{'appointment'} ? 1 : 0;
	my $bg = $bundle->{'background'} // '';
	unless (length $bg) {
		my $config = &config_reader();
		$bg = $config->{ &signatorial_designer() }->{'manager'}->{'background_colour'} // '';
	}
	my $dark = 0;
	if ($bg =~ /^\#?([0-9a-fA-F]{6})$/) {
		my ($r, $g, $b) = map { hex } ($1 =~ /(..)(..)(..)/);
		# keep in step with theme_panel_css(): the same 0.5 luminance line
		# decides whether the chrome is a light or a dark face
		$dark = ((0.2126 * $r + 0.7152 * $g + 0.0722 * $b) / 255) < 0.5 ? 1 : 0;
	}
	$theme_state_memo = [ $dark, ($appointment ? $name : ''), $bg, $bundle, $name, $appointment ];
	$theme_state_time = $now;
	return @{$theme_state_memo};
}
sub theme_is_dark() {
	my ($dark) = &theme_state();
	return $dark;
}

# A misc surface's background for the theme that is in charge. A running
# appointment theme paints its own ramp across every surface - the same ramp the
# scheme picker would write - and the Misc theme keeps each surface's configured
# colour, darkened when the desktop is dark and that colour is a light face.
sub theme_surface_colour() {
	my ($key, $device) = @_;
	return undef unless defined $key && length $key;
	my (undef, undef, undef, $bundle) = &theme_state();
	my $dark = &theme_is_dark();
	my $scheme = ref $bundle eq 'HASH' ? ($bundle->{'scheme'} // '') : '';
	if (length $scheme && $colour_schemes{$scheme}) {
		my $index = 0;
		foreach my $k ( @gb::misc_settings ) {
			last if $k eq $key;
			$index++;
		}
		my $ramp = $colour_schemes{$scheme};
		return $ramp->[ $index % scalar @{$ramp} ];
	}
	my $config = &config_reader();
	$device = &device_setter() unless defined $device && length $device;
	my $colour = $config->{$device}->{$key}->{'background_colour'};
	return $colour unless defined $colour && length $colour;
	return $colour unless $dark;
	return &dark_surface_colour($colour);
}

# Turn a light face into a dark one of the same hue. A colour already dark is
# left alone, so a dark scheme's curated ramp survives untouched.
sub dark_surface_colour() {
	my ($colour) = @_;
	return $colour unless defined $colour && length $colour;
	my $hex = $colour;
	$hex =~ s/^\s+//;
	$hex =~ s/\s+$//;
	$hex =~ s/^\#//;
	return $colour unless $hex =~ /^[0-9a-fA-F]{6}$/;
	my ($r, $g, $b) = map { hex } ($hex =~ /(..)(..)(..)/);
	my ($h, $s, $l) = &_rgb_to_hsl($r, $g, $b);
	return $colour if $l < 0.5;
	my $tint = $s > 0.32 ? 0.32 : $s;
	return &_hsl_to_hex($h, $tint, 0.22);
}

sub icon_set() {
	my $now = &rightNow();
	return $icon_set_memo if defined $icon_set_memo && $now - $icon_set_memo_time < 1000;
	my $config = &config_reader();
	my $set = '';
	# While a theme is in charge it names the glyphs; the Misc Icon Set is what a
	# desk with no theme wears. An explicit override (chosen from the Misc panel
	# while the theme is active) wins over the theme's own set, so a person can
	# keep Deepjawn's paint and still use another set of icons.
	my $bundle = &active_theme_bundle();
	if ($bundle->{'slug'}) {
		my $override = &misc_setting('icon_set_override');
		if (defined $override && length $override && grep { $_ eq $override } @gb::icon_sets) {
			$set = $override;
		}
		elsif (defined $bundle->{'icon_set'} && length $bundle->{'icon_set'}) {
			$set = $bundle->{'icon_set'};
		}
	}
	$set = $config->{'icon_set'} || '' unless length $set;
	# a dark desktop asks for the set's dark cut: the same glyphs on a plate
	# that does not glare. The light cut stays the fallback for a hand-drawn
	# set (which has no generated cut) and for any set without one.
	if ($set && $set ne 'handdrawn' && $set !~ /_dark$/ && &theme_is_dark()) {
		my $dark_set = $set . '_dark';
		$set = $dark_set if -d "public/icons/sets/$dark_set";
	}
	$icon_set_memo = $set;
	$icon_set_memo_time = $now;
	return $icon_set_memo;
}
# Called when the icon set is changed, so the very next render already uses it
# instead of waiting out the memo above. The theme memo goes with it: a scheme
# change can flip which cut of the set is wanted.
sub icon_set_forget {
	$icon_set_memo = undef;
	$icon_set_memo_time = 0;
	$theme_state_memo = undef;
	$theme_state_time = 0;
	$theme_registry_memo = undef;
	$theme_registry_time = 0;
}

# When the hand-drawn set is active, swap a public icon path for its original
# hand-drawn PNG (kept in public/icons/original/) if one exists.
sub icon_original() {
	my $path = shift;
	return $path unless defined $path && $path =~ m{^/};
	return $path unless &icon_set() eq 'handdrawn';
	my $candidate = "/icons/original" . $path;
	return -e "public" . $candidate ? $candidate : $path;
}

# The hand-drawn picture behind a public icon path, whatever icon set is
# selected - the gate's splash and the denial page wear it always. build.js
# renders generated tiles in at the old public paths, so the plain path no
# longer shows the hand.
sub icon_drawn() {
	my $path = shift;
	return $path unless defined $path && $path =~ m{^/};
	my $candidate = "/icons/original" . $path;
	return -e "public" . $candidate ? $candidate : $path;
}

# Resolve a button icon through the selected set, falling back to the given path.
sub icon_path() {
	my ($name, $fallback) = @_;
	my $set = &icon_set();
	if ($set eq 'handdrawn') {
		return &icon_original($fallback);
	}
	if ($set) {
		my $path = "/icons/sets/" . $set . "/" . $name . ".svg";
		return $path if -e "public" . $path;
	}
	return $fallback;
}

# Resolve an app icon given its normal public path: hand-drawn originals for the
# hand-drawn set, or the matching /icons/sets/<set>/<basename>.svg when present.
sub icon_for() {
	my ($path, $set) = @_;
	return $path unless defined $path && $path =~ m{^/};
	$set = &icon_set() unless defined $set;
	return &icon_original($path) if $set eq 'handdrawn';
	return $path unless $set;
	my ($base) = $path =~ m{([^/]+)$};
	$base =~ s/\.[A-Za-z0-9]+$//;
	my $candidate = "/icons/sets/$set/$base.svg";
	return $candidate if -e "public" . $candidate;
	return $path;
}

# The colours a text control wears to sit beside the icon set's tiles: every
# generated tile is filled from hsl() values (the loud sets build their
# gradients from the same ones, so the first hsl() in the file is still the
# tile's colour) and the lightness says whether dark or light ink reads on it.
# The tile is named for the state the control is about - the page button wears
# the "now" tile at home and the back/forward tiles once it has walked. Memoised
# per set and tile: the files only change when build.js runs, while the manager
# re-renders constantly.
my %icon_plate_memo;
sub icon_plate_colours() {
	my $icon = shift || 'now';
	my $set = &icon_set() || '';
	my $memo_key = $set . '/' . $icon;
	return $icon_plate_memo{$memo_key} if exists $icon_plate_memo{$memo_key};
	my $colours = { plate => '', ink => '' };
	if ($set && $set ne 'handdrawn') {
		my $file = 'public/icons/sets/' . $set . '/' . $icon . '.svg';
		my $svg = -e $file ? read_file($file) : undef;
		if (defined $svg && $svg =~ /(hsl\(\s*\d+\s*,\s*\d+%\s*,\s*(\d+)%\s*\))/) {
			$colours = { plate => $1, ink => ($2 > 65 ? '#111111' : '#ffffff') };
		}
	}
	return $icon_plate_memo{$memo_key} = $colours;
}

# A fingerprint of everything that gets baked into cached window/header HTML:
# the icon set, the active theme's dressing and the device's theme colours.
# Cached renders whose signature no longer matches are discarded, so closed
# windows don't come back looking stale.
sub render_signature() {
	my $device = &device_setter();
	my $config = &config_reader();
	# The active theme's own dressing belongs in the signature: two themes can
	# share an icon set and still paint their surfaces from different ramps, and
	# a window rendered under the old ramp must not come back from the cache.
	# theme_state() is memoised on the same short TTL as icon_set(), so this adds
	# no query to a warm render.
	my ( $theme_dark, undef, $theme_bg, $theme_bundle ) = &theme_state();
	my @theme_parts = ( $theme_dark, $theme_bg );
	if (ref $theme_bundle eq 'HASH') {
		push @theme_parts, map { $theme_bundle->{$_} } qw/scheme texture font corner accent/;
	}
	# the version is part of the signature so every release (each push bumps it)
	# discards cached appointment renders - without it a template change to an
	# appointment window would sit behind a cache row that matched forever
	my @parts = ( &icon_set() || '', &jawn_version(), join '|', map { defined $_ ? $_ : '' } @theme_parts );
	foreach my $k ( @gb::misc_settings ) {
		push @parts, $k . '=' . ($config->{$device}->{$k}->{'background_colour'} || '');
	}
	return join '|', @parts;
}


sub typesetter() {
	my $app = shift;
	my $save = shift;
	my $type = 'idea';
	my $movement = '';
	my $last_word = (split '_', $app)[-1];
	my $first_word = (split '_', $app)[0];
	my $type_saved = 0;
	$last_word =~ s/[0-9]$//gi;
	$first_word =~ s/[0-9]$//gi;
	if ($last_word !~ /^!/ && grep { lc $last_word eq $_ } keys %{$gb::pos}) {
		my @app = split '_', $app;
		pop @app unless scalar @app == 1;
		$app = join '_', @app;
		$type = $last_word;
		$type_saved = 1;
	}
	elsif ($last_word =~ /^!/) {
		my @app = split '_', $app;
		$last_word = pop @app;
		$last_word =~ s/^!//gi;
		push @app, $last_word;
		$app = join '_', @app;
	}
	elsif ( my $default_pos = &subs::setting_grabber({ app => 'me', setting => 'pos' }) ) {
		$type = $default_pos;
	}
	if ($first_word !~ /^!/ && grep { lc $first_word eq $_ } @gb::movements) {
		my @app = split '_', $app;
		shift @app unless scalar @app == 1;
		$app = join '_', @app;
		$movement = $first_word;
	}
	elsif ($first_word =~ /^!/) {
		my @app = split '_', $app;
		$first_word = shift @app;
		$first_word =~ s/^!//gi;
		unshift @app, $first_word;
		$app = join '_', @app;
	}
	if ($type_saved == 1 && $save ne 'no') {
		&subs::setting_setter({ app => $app, setting => 'pos', value => $type });
	}
	return ($app,$type,$movement);
}

sub setting_initializer() {
	my ($app,$timestamp) = @_;
	my $returner;
	$app = &unformat_name($app);
	my ($db,$database) = &database_grabber();
	my $server_time = &rightNow();
	my $type;
	($app,$type) = &typesetter($app);
	my $counter = &subs::db_query('select count(*) from appointments where app=?', $app);
	my $count = $counter->hash->{'count(*)'};
	my $res = &db_query('select * from settings where app=? and device = ? order by server_time desc',$app,$device);
	my $re = $res->hashes;

	my $aka = &db_query('select * from settings where setting = ? and value like ?', 'aka', '%' . $app . '%')->hashes;

	if ( $count == 0 && scalar @{$aka} > 0 ) {
		foreach my $ak ( @{$aka} ) {
			if (exists $ak->{'value'}) {
				my @a = split ',', $ak->{'value'};
				foreach my $o ( @a ) {
					$o = &subs::unformat_name($o);
					if ($o eq $app) {
						$app = &subs::unformat_name($ak->{'app'});
						$res = &db_query('select * from settings where app=?',$app);
						$re = $res->hashes;
						last;
					}
				}
			}
		}
	}
	my $me_settings = &subs::settings_grabber({ app => 'me' });

	my $colour = '#' . &random_colour_grabber();

	$returner->{'app'} = $app;
	my $settings = {
		'colour' => $colour,
		'dark_colour' => &dark_colour_for($colour),
		'worth' => $me_settings->{'worth'},
		'visible' => 'public',
		'permanent' => 'checked',
		'pos' => $type,
		'duration' => $me_settings->{'duration'},
		'currency' => $me_settings->{'currency'},
		'unit' => $me_settings->{'unit'},
		'cost' => 0,
		'enc' => 'on',
		'public' => 'off',
		'warranty' => $me_settings->{'warranty'},
		'notification_text' => &subs::format_name($app),
		'schedule' => 'once',
		'uuid' => &random_string_creator(25),
		'navigation' => 'none'
	};

	foreach my $s (keys %{$settings}) {
		my @seen = grep { $_->{'setting'} eq $s } @{$re};

		unless ( scalar @seen > 0 ) {
			my $pen = {
				app => $app,
				timestamp => &subs::rightNow(),
				setting => $s,
				value => $settings->{$s},
				server_time => &subs::rightNow(),
				device => $device,
				uuid => &random_string_creator(20)
			};
			&db_insert('settings', $pen);
			$returner->{$s} = $settings->{$s};
		}
		else {
			my $set = $seen[0];
			$returner->{$s} = $set->{'value'};
			if (scalar @seen > 1) {
				#unshift @seen;
				foreach my $s ( @seen ) {
					&subs::db_delete('settings', { app => $app, uuid => $s->{'uuid'} });
					&Manager::deletion_registration({ table => 'settings', app => $app, uuid => $s->{'uuid'}, scope => 'single', server_time => $s->{'server_time'} });
				}
			}
		}
	}
	return $returner;
};

&signatorial_establisher();

sub signatorial_establisher {
	my $context = shift;
	# Pin the session secret even when the signatorial image is missing. Left
	# unpinned, each Mojolicious worker signs sessions with its own random key, so
	# a session the dock mints (a ticket) will not verify at the manager - the
	# Gate a client lands on holding a perfectly good ticket. The fallback is
	# deterministic (the configured path), so the tree's workers share it.
	$gb::secret_maker ||= [ md5_sum('signatorial:' . ($config->{'signatorial'} || 'jawnos')) ];
	if ($config->{'signatorial'} && -e $config->{'signatorial'}) {

		my $j = &subs::terminal_name(&subs::home($config->{'signatorial'}));
		my $checksum = `base64 $j`;
		my $md5 = md5_sum $checksum;
		$gb::secret_maker = [ $md5 ];
		return $md5;
	}
	elsif ($context ne 'designer') {
		return &random_string_creator(12);
	}
}

sub signatorial_identity_file() {
	return &home('~/.jawnos_signatorial_id');
}

# A second copy beside the database. The home copy is the traditional one, but
# it depends on HOME, which a container, a `run-as` shell or a hand-run script
# can have wrong - and a database restored from another machine must never be
# able to change this machine's identity. The database directory is local, is
# not replaced by a restore (only jawnos.db is), and is excluded from the code
# sync, so this copy survives both.
sub signatorial_identity_mirror() {
	return './database/.jawnos_signatorial_id';
}

sub signatorial_identity_write {
	my $id = shift;
	for my $file ( &signatorial_identity_file(), &signatorial_identity_mirror() ) {
		next unless defined $file && length $file;
		if (open my $fh, '>', $file) {
			chmod 0600, $file;
			print $fh $id, "\n";
			close $fh;
		}
	}
	return $id;
}

sub signatorial_designer() {
	my $designation = shift;
	if (!$designation && $gb::signatorial) {
		return $gb::signatorial;
	}

	# A persisted identity is the point: it must not change when a picture is
	# added or removed, and every container or clone must have its own. The
	# file is written once - by setup for a new install, or by the legacy
	# migration below for a machine that predates it - and is never recomputed.
	my @identity_files = ( &signatorial_identity_file(), &signatorial_identity_mirror() );
	for my $file ( @identity_files ) {
		next unless defined $file && length $file && -e $file;
		my $id = `cat $file`;
		chomp $id;
		if ($id =~ /^[0-9a-f]{16,64}$/i) {
			$gb::signatorial = lc $id;
			# heal the other copy if it is missing (a wrong HOME, a new mirror)
			&signatorial_identity_write($gb::signatorial);
			return $gb::signatorial;
		}
	}

	# A restored database arrives with the donor's settings, and the donor's
	# remote_machines roster lists THIS machine as a peer. The most-used device
	# id in those settings is then the donor's own identity, not ours (ours is
	# excluded below because the roster names it as a peer). The configured
	# domain is local - it lives in config.json, not the database - so it
	# survives a restore and names exactly one roster row. Trust that first.
	my $domain = $config->{'domain'} || '';
	if ($domain) {
		my $row = eval {
			&db_query(
				"select signatorial from remote_machines"
				. " where fqdn = ? and signatorial is not null and signatorial != ''"
				. " order by server_time desc limit 1", $domain
			)->hash;
		};
		my $mine = ($row && $row->{'signatorial'}) ? lc $row->{'signatorial'} : '';
		if ($mine =~ /^[0-9a-f]{16,64}$/) {
			&signatorial_identity_write($mine);
			$gb::signatorial = $mine;
			return $gb::signatorial;
		}
	}

	# A machine that predates the identity file: its current signatorial is
	# already the key on its settings, continent and sync rows. Take the most
	# used long device value that is not a peer's signatorial, and pin that -
	# never recompute it, since the picture folder may have drifted since.
	#
	# A database restored from another machine also has a most-used id - the
	# donor's - and its vault row is sealed with the donor's house key, which
	# this machine's key cannot open. So a candidate whose vault will not open
	# is a foreign database's identity, not ours; skip it rather than adopt it.
	my $candidates = eval {
		&db_query(
			"select device from settings"
			. " where device is not null and length(device) >= 16"
			. " and device not in (select signatorial from remote_machines where signatorial is not null)"
			. " group by device order by count(*) desc limit 5"
		)->hashes;
	} || [];
	my $stored;
	for my $candidate ( @{$candidates} ) {
		my $id = $candidate->{'device'} || '';
		next unless $id =~ /^[0-9a-f]{16,64}$/i;
		$id = lc $id;
		my $vault = eval {
			&db_query(
				"select value from settings where app = ? and setting = ? and device = ?"
				. " order by server_time desc limit 1", '__president', 'vault', $id
			)->hash;
		};
		if ($vault && $vault->{'value'}) {
			my $plain = eval { &note_decrypter(&house_key(), $vault->{'value'}) };
			next unless defined $plain && length $plain;
		}
		$stored = $id;
		last;
	}
	if ($stored) {
		&signatorial_identity_write($stored);
		$gb::signatorial = $stored;
		return $gb::signatorial;
	}

	# Legacy migration: compute exactly what this machine announced before the
	# identity was persisted, then pin it. Every remote_machines.signatorial,
	# settings.device and JSON reference keeps pointing at the same value.
	my $folder = './public/images/jonathans';
	my $jonathans = `ls $folder`;
	my @jonathans = split /\n/, $jonathans;
	my $checksum = $database;
	foreach my $j ( @jonathans ) {
		$j = &terminal_name($folder . '/' . $j);
		$checksum .= encode_base64 `cat $j`;
	}
	my $md5 = md5_sum &signatorial_establisher('designer') . $checksum;
	&signatorial_identity_write($md5);
	$gb::signatorial = $md5;

	return $gb::signatorial;
}

sub runner_label() {
	# the machine a command ran on, for the appointment details
	my $hostname = `hostname`;
	chomp $hostname;
	return $hostname;
}

sub destination_relay() {
	# Run an app's command on other machines: a POST to the machine's
	# /manager/reset, which runs that machine's own command for the app and
	# records its own appointment (exactly what a press there does). The
	# destination is a signatorial from the remote machine list; 'all' fans out
	# to every active machine. Returns a label for the machine that took it, or
	# undef when nobody did.
	my $data = shift;
	my $destination = $data->{'destination'};
	my $app = $data->{'app'};
	my $movement = $data->{'movement'} || 'command';
	my $timestamp = $data->{'timestamp'} || &subs::rightNow();
	my $me = &subs::signatorial_designer();
	my $rms;
	if (!$destination || $destination eq 'all') {
		$rms = &subs::remote_machine_lister({ connection => 'active' });
	}
	else {
		$rms = &subs::remote_machine_lister({ signatorial => $destination, connection => 'active' });
	}
	$rms = [] unless ref $rms eq 'ARRAY';
	my $sent = 0;
	my $label;
	my $considered = 0;
	foreach my $rm ( @{$rms} ) {
		next unless ref $rm eq 'HASH';
		my $sig = $rm->{'signatorial'};
		next unless $sig && $sig ne $me;   # this machine's own copy is run by the caller
		$considered++;
		unless ($rm->{'ip'}) {
			$log->error('destination relay to ' . $sig . ' skipped: no address on its row') if $log;
			next;
		}
		my $hop = &Manager::remote_useragent_maker({ rm => $rm, signatorial => $sig });
		unless ($hop && $hop->{'ua'} && $hop->{'manager'}) {
			$log->error('destination relay to ' . $sig . ' skipped: no signed agent for ' . ($rm->{'manager'} || '?')) if $log;
			next;
		}
		# A button press is waiting on this, and an unreachable machine must fall
		# back to running here promptly: the peer agent carries the long snapshot
		# inactivity timeout (3000 s), which is far too long to hold a tap.
		$hop->{'ua'}->connect_timeout(4)->inactivity_timeout(12);
		my $res = eval {
			$hop->{'ua'}->insecure(1)->post($hop->{'manager'} . '/manager/reset' => form => {
				app => $app,
				type => $movement,
				timestamp => $timestamp,
				notes => 'sent from ' . $me
			})->result;
		};
		if ($res && eval { $res->is_success }) {
			$sent++;
			$label = $rm->{'hostname'} . ' (' . $rm->{'ip'} . ')' unless $label;
		}
		else {
			my $why = $@ || ($res ? ('HTTP ' . $res->code) : 'no answer');
			$why =~ s/\s+/ /g;
			$log->error('destination relay to ' . $sig . ' failed: ' . $why) if $log;
		}
	}
	unless ($considered) {
		$log->error('destination relay: no active machine matches ' . ($destination || 'all')) if $log;
	}
	if (!$destination || $destination eq 'all') {
		return $sent ? 'every machine (' . $sent . ')' : undef;
	}
	return $label;
}

sub run_command() {
	my $app = shift;
	my $command = shift;
	my $timestamp = shift;
	my $exec = 'none';
	my $whoami = `whoami`;
	chomp $whoami;
	my $hostname = `hostname`;
	chomp $hostname;
  &subs::subprocessor(sub {
    Mojo::IOLoop->reset;
		if ($command =~ /^&/) {
			$exec = eval { $command };
			my $json = { type => 'command', whoami => 'President', hostname => $hostname, uuid => &subs::random_string_creator(), command => $command, 'return' => $exec, timestamp => $timestamp };

			&Websocket::send('server', $json);
		}
		else {
			$exec = eval { return `$command` };
			my $json = { type => 'command', whoami => $whoami, hostname => $hostname, uuid => &subs::random_string_creator(), command => $command, 'return' => $exec, timestamp => $timestamp };

			&Websocket::send('server', $json);
			sleep(.3);
			my $msg = { app => $app, whoami => $whoami, hostname => $hostname, uuid => &subs::random_string_creator(25), console => $command };
			&Websocket::send('server', $msg);
		}
		return 'done';
	}, { name => 'run command' });
}

sub rightNow() {
	my $precision = shift;
	my $time = time() * 1000;

	unless ($precision) {
		$time = sprintf("%.0f",$time);
	}

	return $time;
}

# Whether this machine has a real GPS. termux-location names the provider that
# answered; only a `gps` answer proves the hardware. The flag is cache, which is
# this machine's own and never syncs, so one phone cannot lend its GPS to a
# laptop. A network fix can be a cell-tower guess blocks from where the person
# stands, so it never turns the flag on by itself.
sub navigation_gps_present {
	my $c = &cache_get({ app => '__president', context => 'navigation', subcontext => 'gps' });
	return (ref $c eq 'HASH' && $c->{'present'}) ? 1 : 0;
}

# Remember that a real GPS answered here. Returns 1 once the flag is set.
sub navigation_gps_confirm {
	my $provider = lc(shift // '');
	return 0 unless $provider eq 'gps';
	return 1 if &navigation_gps_present();
	&cache_set({ app => '__president', context => 'navigation', subcontext => 'gps', warranty => '-10y' }, { present => 1, at => &rightNow() });
	return 1;
}

# The app's GPS service writes each fix to ~/.president/location.json. Only a
# record that names provider=gps may become a place: a network fix looks like a
# fix in every other field, which is how the phone was reported in places it had
# never been. Returns the fix hash (aged by the fix's own timestamp) or undef.
sub native_location {
	my ($opts) = @_;
	$opts ||= {};
	my $file = &subs::home('~/.president/location.json');
	return undef unless -e $file;
	my $raw = eval { read_file($file) };
	return undef unless defined $raw && $raw =~ /\S/;
	my $loc = eval { decode_json($raw) };
	return undef unless ref $loc eq 'HASH';
	return undef unless (($loc->{'provider'} || '') eq 'gps');
	return undef unless (($loc->{'status'} || '') eq 'fix');
	return undef unless defined $loc->{'latitude'} && defined $loc->{'longitude'};
	return undef unless $loc->{'latitude'} =~ /^-?\d+(?:\.\d+)?$/ && abs($loc->{'latitude'}) <= 90;
	return undef unless $loc->{'longitude'} =~ /^-?\d+(?:\.\d+)?$/ && abs($loc->{'longitude'}) <= 180;
	my $now = &subs::rightNow();
	my $age;
	if (($loc->{'time'} || '') =~ /^\d+$/) {
		$age = $now - $loc->{'time'};
	}
	elsif (($loc->{'elapsedMs'} || '') =~ /^\d+$/) {
		$age = $loc->{'elapsedMs'};
		$age += ($now - $loc->{'sampled'}) if (($loc->{'sampled'} || '') =~ /^\d+$/);
	}
	else {
		return undef;
	}
	$age = 0 if $age < 0;
	$loc->{'age_ms'} = $age;
	my $max = defined $opts->{'max_age_ms'} ? $opts->{'max_age_ms'} : (10 * 60 * 1000);
	return undef if $age > $max;
	return $loc;
}

# The navigation utility's own pace, in seconds. President adopts this machine's
# Batch pools. A pool is a group of utilities that wake together on one pace;
# the pace lives on the pool, not on each job, so moving a job between pools
# (or out of all of them) changes only where it is written down. Stored in the
# machine's utility row as a list, so the order is the person's:
#   __batch_groups => [ { id, label, seconds }, ... ]
# An older row stored a plain { id => seconds } map and reads the same; a row
# that has never been edited has no pools of its own and takes gb.pl's defaults.
sub batch_pools {
	my $row = shift;
	my $stored = (ref $row eq 'HASH') ? $row->{'__batch_groups'} : undef;
	my @pools;
	if (ref $stored eq 'ARRAY') {
		my %seen;
		foreach my $pool ( @{$stored} ) {
			next unless ref $pool eq 'HASH';
			my $id = $pool->{'id'} // '';
			$id =~ s/[^a-z0-9_]//g;
			next unless $id ne '' && !$seen{$id}++;
			my $seconds = int($pool->{'seconds'} || 0);
			$seconds = $gb::batch_groups->{$id}->{'seconds'} || 900 unless $seconds > 0;
			my $label = $pool->{'label'} // '';
			$label =~ s/^\s+|\s+$//g;
			$label = $id if $label eq '';
			push @pools, { id => $id, label => $label, seconds => $seconds };
		}
	}
	elsif (ref $stored eq 'HASH') {
		foreach my $id ( sort keys %{$stored} ) {
			my $seconds = int($stored->{$id} || 0);
			$seconds = $gb::batch_groups->{$id}->{'seconds'} || 900 unless $seconds > 0;
			push @pools, { id => $id, label => ($gb::batch_groups->{$id}->{'label'} || $id), seconds => $seconds };
		}
	}
	if (!defined $stored) {
		foreach my $id ( @gb::batch_order, sort keys %{$gb::batch_groups} ) {
			next if !$gb::batch_groups->{$id} || grep { $_ eq $id } map { $_->{'id'} } @pools;
			push @pools, { id => $id, label => ($gb::batch_groups->{$id}->{'label'} || $id), seconds => $gb::batch_groups->{$id}->{'seconds'} || 900 };
		}
	}
	return \@pools;
}

# The pool a job belongs to, or undef when it runs on its own interval.
sub batch_pool_of {
	my $row = shift;
	my $job = shift;
	return undef unless ref $row eq 'HASH' && ref $row->{$job} eq 'HASH';
	my $group = $row->{$job}->{'group'} // '';
	return undef if $group eq '';
	foreach my $pool ( @{ &batch_pools($row) } ) {
		return $pool if $pool->{'id'} eq $group;
	}
	return undef;
}

# The pace a job actually keeps: its pool's seconds, or undef when it is not in
# a pool (the caller then uses the job's own interval).
sub batch_interval {
	my $row = shift;
	my $job = shift;
	my $pool = &batch_pool_of($row, $job);
	return $pool ? $pool->{'seconds'} : undef;
}

# The machine's navigation interval, in seconds. The runtime adopts the stored
# row from the utility controller at runtime, but Manager and the scripts do not
# share that process, so read the same persisted row here. A navigation job in a
# batch pool keeps the pool's pace.
sub navigation_interval {
	my $signatorial = &subs::signatorial_designer();
	my $controls = eval { return decode_json &subs::setting_grabber({ app => '__president', setting => 'utility_controller' }) } || {};
	my $interval = &batch_interval($controls->{$signatorial}, 'navigation');
	$interval = $controls->{$signatorial}->{'navigation'}->{'interval'} unless $interval && $interval > 0;
	$interval = $gb::timeouts->{'navigation'}->{'interval'} unless $interval && $interval > 0;
	return $interval || 600;
}

# The pace navigation must keep right now, in seconds. The machine's utility
# interval is the base, but a running appointment whose app asks for fixes more
# often than that (its navigation setting, say 1m) is a request to update faster
# than the slower utility slot - so the pace follows the app down to a
# battery-wise floor. Base only asks for the utility's own pace.
sub navigation_pace {
	my $data = shift || {};
	my $base = &navigation_interval();
	return $base if $data->{'base'};
	my $fastest = $base;
	my $running = &subs::db_query('select app from appointments where (type = ? or type = ?) and timestamp < ?', 'start', 'record', &subs::rightNow())->hashes;
	foreach my $appt ( @{$running} ) {
		my $navigation = eval { return &subs::setting_grabber({ app => $appt->{'app'}, setting => 'navigation' }) };
		next unless defined $navigation && $navigation =~ /\S/;
		next if $navigation =~ /^(?:none|once)$/i;
		my $ms = ($navigation =~ /^\d+$/ && $navigation > 1000) ? $navigation : &subs::time_abbrev_translator($navigation);
		next unless $ms && $ms > 0;
		my $seconds = $ms / 1000;
		$fastest = $seconds if $seconds < $fastest;
	}
	$fastest = 10 if $fastest < 10;
	return $fastest;
}

# How long a fix the browser writes stays the machine's current place. It has
# to outlive the next automatic navigation run or the place falls back to public
# between fixes - the old flat five minutes did exactly that whenever the
# navigation utility was slower than five minutes. A scheduled watcher says when
# its own next run is due; otherwise the utility's pace (or the app's, when that
# is longer) is the gap to cover. One more interval lets the place survive a run
# that could not get a fix, and two minutes of grace absorbs a late slot.
sub navigation_hold_warranty {
	my $data = shift || {};
	my $now = $data->{'server_time'} || &subs::rightNow();
	my $grace = 2 * 60 * 1000;
	my $hold = 5 * 60 * 1000;
	my $navigation = $data->{'navigation'};
	my $next = $data->{'next_navigation'};
	my $timestamp = $data->{'timestamp'};
	if ($next && $timestamp && $next > $timestamp) {
		# both came from the browser's clock, so their difference is the wait
		$hold = ($next - $timestamp) if ($next - $timestamp) > $hold;
	}
	elsif (defined $navigation && $navigation =~ /^\d+$/ && $navigation > 0) {
		$hold = $navigation if $navigation > $hold;
	}
	my $pace = &navigation_pace({ base => 1 }) * 1000;
	$hold = $pace if $pace > $hold;
	$hold += $pace;
	return $now + $hold + $grace;
}

sub headless_navigation() {
	my $signatorial = &subs::signatorial_designer();
	my $now = &subs::rightNow();
	my $navigation_due = [];
	my $note;
	my $running_appts = &subs::db_query('select app,uuid,type,warranty from appointments where (type = ? or type = ?) and timestamp < ?', 'start', 'record', $now)->hashes;
	foreach my $appt ( @{$running_appts} ) {
		my $navigation = &subs::setting_grabber({ app => $appt->{'app'}, setting => 'navigation' });
		if ($navigation eq 'none') {
			next;
		}
		if ($navigation eq 'once') {
			# `once` means "log when the person acts", but a start on a cold GPS
			# can happen before the first fix arrives. If the running appointment
			# still has no point of its own, give it the next real fix rather than
			# losing the act.
			my $has_point = &subs::db_query('select uuid from continent where app = ? and uuid like ? and latitude is not null and latitude != ? order by server_time desc limit 1', $appt->{'app'}, $appt->{'uuid'} . '%', '')->hashes->[0];
			unless ($has_point) {
				push @{$navigation_due}, {
					app => $appt->{'app'},
					uuid => $appt->{'uuid'},
					warranty => $appt->{'warranty'},
				};
			}
			next;
		}
		else {
			my $last_appt_location = &subs::db_query('select * from continent where app=? and uuid like ? order by server_time desc', $appt->{'app'}, $appt->{'uuid'} . '%')->hashes->[0];
			my $increment = &subs::time_abbrev_translator($navigation);
			if ($now >= $last_appt_location->{'timestamp'} + $increment ) {
				push @{$navigation_due}, { app => $appt->{'app'}, uuid => $appt->{'uuid'} };
			}
		}
	}

	# utility_runner is the navigation schedule; this second gate only guards a
	# call from elsewhere. The runner's tick of slack keeps a call landing a few
	# milliseconds before the interval from skipping a whole slot (the stamp is
	# taken at the slot, so a strict comparison can be just short).
	my $pace = &navigation_pace();
	if ($now - $gb::timeouts->{'navigation'}->{'lasted_run'} >= ($pace * 1000) - 5000) {
		$gb::timeouts->{'navigation'}->{'lasted_run'} = $now;
		my $returner = {
			uuid => &subs::random_string_creator(103),
			type => 'temporary',
			app => '__president',
			timestamp => $now,
			signatorial => $signatorial,
			server_time => &subs::rightNow(),
			# duration_sayer reads seconds; a millisecond count here used to become
			# "8d 8h" for a four-minute pace and left a stale place current for days
			warranty => &subs::ago_calc('-' . &subs::duration_sayer(&navigation_interval() * 3),$now),
		};
		my $written = 0;
		# The capture runs on the navigation interval alone (the gate above). It
		# used to also wait until the machine's newest location row was older than
		# the interval - but the browser writes those rows too (continent_record),
		# so an open app reset the clock and this autonomous capture starved. It now
		# records on its own cadence whether or not the browser just did.
		if (&subs::device_setter() eq 'mobile') {
			# The app's GPS service keeps this machine's fix on disk, so there
			# is no process to spawn and no wait; the file is as fresh as the
			# navigation pace. A machine that has not run the service yet
			# falls back to termux-location -p gps, never the network provider.
			my $current_pace = &navigation_pace();
			my $max_age = ($current_pace * 2 * 1000) + 120000;
			$max_age = 5 * 60 * 1000 if $max_age < 5 * 60 * 1000;
			$max_age = 15 * 60 * 1000 if $max_age > 15 * 60 * 1000;
			my $loc = &subs::native_location({ max_age_ms => $max_age });
			unless ($loc) {
				my $jloc = `timeout 20 termux-location -p gps 2>/dev/null`;
				my $j = eval { decode_json($jloc) } || {};
				if (($j->{'provider'} || '') eq 'gps' && $j->{'latitude'}
					&& ($j->{'elapsedMs'} || 1e9) <= $max_age) {
					$loc = {
						provider => 'gps',
						latitude => $j->{'latitude'},
						longitude => $j->{'longitude'},
						accuracy => $j->{'accuracy'},
						elapsedMs => $j->{'elapsedMs'},
					};
				}
			}
			# Only a `gps` provider answer proves this machine has the
			# hardware; a machine with no GPS must never become a source
			# another machine borrows from.
			&subs::navigation_gps_confirm($loc->{'provider'}) if $loc;
			my $has_gps = &subs::navigation_gps_present();
			# The service already bounds the fix's age; a walk still gives
			# perfectly usable fixes that are a little loose.
			my $usable = $has_gps && $loc && $loc->{'latitude'}
				&& ($loc->{'accuracy'} || 0) < 500;
			if ($usable) {
				$returner->{'latitude'} = $loc->{'latitude'};
				$returner->{'longitude'} = $loc->{'longitude'};
				$returner->{'accuracy'} = sprintf("%.2F", ($loc->{'accuracy'} || 0));
				&subs::db_delete('continent', { type => 'temporary', signatorial => $signatorial });
				my $treturner = clone $returner;
				$treturner->{'uuid'} = &subs::random_string_creator(31);
				&subs::db_insert('continent', $treturner);
				$written = 1;
				$note = 'fix gps ' . ($returner->{'accuracy'} || '?') . 'm';
			}
			else {
				$log->info('navigation: no fresh GPS fix; no place recorded');
				$note = 'no usable fix';
			}
		}
		else {
			$returner = &subs::embedded_location_grabber($returner);
			if ($returner->{'latitude'}) {
				&subs::db_delete('continent', { type => 'temporary', signatorial => $signatorial });
				my $treturner = clone $returner;
				$treturner->{'uuid'} = &subs::random_string_creator(31);
				&subs::db_insert('continent', $treturner);
				$written = 1;
				$note = 'fix ' . ($returner->{'accuracy'} || '?') . 'm';
			}
		}
		if ($returner->{'latitude'} && $written == 1) {
			# Hand the fix to a computer on this LAN before the appointment
			# bookkeeping runs: the laptop records the place, but only this
			# machine (the one holding the GPS) starts or stops appointments.
			&subs::navigation_share_fix($returner);

		#	&subs::db_insert('continent', $returner);
			foreach my $nd ( @{$navigation_due} ) {
				$returner->{'uuid'} = $nd->{'uuid'} . '-' . &subs::random_string_creator(9);
				$returner->{'app'} = $nd->{'app'};
				$returner->{'warranty'} = $nd->{'warranty'};
				$returner->{'type'} = 'app';
				&subs::db_insert('continent', $returner);
			}
			&subs::navigation_automation($returner, 'gps');

		}
	}
	return $note;
}

sub navigation_information() {
	my $data = shift;
	my $current_locations;
	if ($data->{'signatorial'}) {
		$current_locations = &subs::db_query('select * from continent where type=? and signatorial =? and cast(warranty as integer) > cast(? as integer)','temporary',$data->{'signatorial'},&subs::rightNow())->hashes;
	} else {
		$current_locations = &subs::db_query('select * from continent where type=? and cast(warranty as integer) > cast(? as integer)','temporary',&subs::rightNow())->hashes;
	}
	my $navigation_information = {};
	my $runs = 0;
	my $count = 0;
	foreach my $cl ( @{$current_locations} ) {
		$count++;
		my $cache = &subs::cache_get({ app => 'travel', context => 'navigation_information', subcontext => $cl->{'signatorial'} });
		next if $cache->{'timestamp'} + 5000 >= &subs::rightNow();
		$navigation_information->{$cl->{'signatorial'}}->{'__location'} = $cl;
		if (!$cache->{'__location'}) { $runs++; $runs++; next; }
		if (!$cache->{'__location'}->{'warranty'} || $cache->{'__location'}->{'warranty'} < &subs::rightNow()) { $runs++; $runs++; next; }
		my @old_location = (deg2rad($cache->{'__location'}->{'longitude'}), deg2rad(90 - $cache->{'__location'}->{'latitude'}));
		my @new_location = (deg2rad($cl->{'longitude'}), deg2rad(90 - $cl->{'latitude'}));
		my $distance = sprintf("%.3f", great_circle_distance(@old_location, @new_location, $gb::planet_radius));

		if ($distance < .020 || ($data->{'cache'} eq 'yes' && $cache->{'__location'}->{'latitude'}) ) {
			$navigation_information->{$cl->{'signatorial'}} = $cache;
			next;
		}
		elsif (!$cache->{'__location'}->{'latitude'}) {
#			&subs::headless_navigation();
			$runs++;$runs++;
		}
		$runs++;
	}

	if ($runs < $count && scalar @{$current_locations} > 0) {
		return $navigation_information;
	}
	elsif (scalar @{$current_locations} == 0 && $data->{'signatorial'}) {
		my $pset = &subs::settings_grabber({ app => '__president', settings => [ $data->{'signatorial'} . '_site_type', $data->{'signatorial'} . '_site_rating' ] });
		if ($pset->{$data->{'signatorial'} . '_site_type'}) {
			$navigation_information->{$data->{'signatorial'}}->{'site_type'} = $pset->{$data->{'signatorial'} . '_site_type'};
			$navigation_information->{$data->{'signatorial'}}->{'site_rating'} = $pset->{$data->{'signatorial'} . '_site_rating'};
			$navigation_information->{$data->{'signatorial'}}->{'site_source'} = 'manual';
		} else {
			$navigation_information->{$data->{'signatorial'}}->{'site_type'} = 'public';
			$navigation_information->{$data->{'signatorial'}}->{'site_rating'} = $gb::site_types->{'public'}->{'rating'};
			$navigation_information->{$data->{'signatorial'}}->{'site_source'} = 'lost';
		}
		return $navigation_information;
	}
	else {
		my $pset = {};
		my $hpds = &subs::db_query('select * from settings where setting=? and value is not null and value != ?', 'home_plate_duties', '[]')->hashes;
		foreach my $hpder ( @{$hpds} ) {
			my $home_plate = eval { return decode_json &subs::setting_grabber({ app => $hpder->{'app'}, setting => 'home_plate' }) || &subs::setting_grabber({ app => 'me', setting => 'home_plate' }) } || {};
			if ($home_plate->{'latitude'}) {
				my $hpd = eval { return decode_json $hpder->{'value'} } || [];
				foreach my $hp ( @{$hpd} ) {
					my $parent_app = $hpder->{'app'};
					my $app = $hp->{'self'} eq 'on' ? $hpder->{'app'} : $hp->{'app'};
					if (!$app && ($hp->{'self'} eq 'off' && !$hp->{'app'})) {
						next;
					}
					my @home_plate = (deg2rad($home_plate->{'longitude'}), deg2rad(90 - $home_plate->{'latitude'}));
					foreach my $returner ( @{$current_locations} ) {
						next if grep { $_ eq $returner->{'signatorial'}} @{$hp->{'signatorials'}};
						push @{$hp->{'signatorials'}}, $returner->{'signatorial'};

						$pset->{$returner->{'signatorial'}} = &subs::settings_grabber({ app => '__president', settings => [ $returner->{'signatorial'} . '_site_type', $returner->{'signatorial'} . '_site_rating' ] })
							unless $pset->{$returner->{'signatorial'}};

						my @visitor = (deg2rad($returner->{'longitude'}), deg2rad(90 - $returner->{'latitude'}));
						my $distance = sprintf("%.3f", great_circle_distance(@home_plate, @visitor, $gb::planet_radius));

						my $hset = &subs::settings_grabber({ app => $app, settings => [ 'warranty', 'toggle', 'site_type'] });
						my $tog = $hset->{'toggle'};
						my $ndata = {
							app => $app,
							distance => $distance,
							parent_app => $parent_app
					#		current_location => $returner,
					#		coordinates => $home_plate
						};
						if ($hp->{'placement'} eq 'within') {
							if ($distance <= $hp->{'distance'}) {
								push @{$navigation_information->{$returner->{'signatorial'}}->{'within'}}, $ndata;
								push @{$navigation_information->{$returner->{'signatorial'}}->{'site_types'}}, $hset->{'site_type'} || 'public';
							} else {
								push @{$navigation_information->{$returner->{'signatorial'}}->{'other'}}, $ndata;
							}
						}
						elsif ($hp->{'placement'} eq 'without') {
							if ($distance > $hp->{'distance'}) {
								push @{$navigation_information->{$returner->{'signatorial'}}->{'without'}}, $ndata;
							} else {
								push @{$navigation_information->{$returner->{'signatorial'}}->{'other'}}, $ndata;
							}
						}
						else {

							push @{$navigation_information->{$returner->{'signatorial'}}->{'other'}}, $ndata;

						}
						my $site_type = $navigation_information->{$returner->{'signatorial'}}->{'site_type'} || $gb::site_types->{'public'}->{'name'};
						my $site_rating = $navigation_information->{$returner->{'signatorial'}}->{'site_rating'} || $gb::site_types->{'public'}->{'rating'};
						my $types = $navigation_information->{$returner->{'signatorial'}}->{'site_types'};
						foreach my $t ( reverse sort { $gb::site_types->{$a}->{'rating'} <=> $gb::site_types->{$b}->{'rating'} } keys %{$gb::site_types} ) {
							if ( grep { $_ eq $t } @{$types} ) {
								$site_type = $t;
								$site_rating = $gb::site_types->{$t}->{'rating'};
								if ($site_rating >= 3) {
									last;
								}
							}
						}
						if ($pset->{$returner->{'signatorial'}}->{$returner->{'signatorial'} . '_site_type'}) {
							$navigation_information->{$returner->{'signatorial'}}->{'site_type'} = $pset->{$returner->{'signatorial'}}->{$returner->{'signatorial'} . '_site_type'};
							$navigation_information->{$returner->{'signatorial'}}->{'site_rating'} = $pset->{$returner->{'signatorial'}}->{$returner->{'signatorial'} . '_site_rating'};
							$navigation_information->{$returner->{'signatorial'}}->{'site_source'} = 'manual';
						} else {
							$navigation_information->{$returner->{'signatorial'}}->{'site_type'} = $site_type || 'public';
							$navigation_information->{$returner->{'signatorial'}}->{'site_rating'} = $site_rating || 0;
							$navigation_information->{$returner->{'signatorial'}}->{'site_source'} = 'navigation';
						}
					}
				}
			}
		}
		foreach my $sig ( keys %{$navigation_information} ) {
			$navigation_information->{'timestamp'} = &subs::rightNow();
			&subs::cache_set({ app => 'travel', context => 'navigation_information', subcontext => $sig, warranty => '-10m' }, $navigation_information->{$sig});
		}
		return $navigation_information;
	}
}

# ---- Visibility -----------------------------------------------------------
#
# A thing's visibility is no longer a checkbox. The setting (`visible`) is one
# of three place words: private, public or dangerous. They are the site types in
# gb.pl, and places are numbered 1 (private), 2 (public) and 3 (dangerous): a
# thing is shown while the room is at or below its number. There is no `on` or
# `off` any more; private is the least visible level, and public is what a new
# app is born with.
#
# A person's relationship is numbered on the same scale - friend 1 (private),
# stranger 2 (public), enemy 3 (dangerous) - so an enemy's presence raises the
# room to dangerous. Strangers are not negative and do not change the room.
our %relationship_rating = (friend => 1, stranger => 2, enemy => 3);
our @relationship_order = qw/friend stranger enemy/;

# A relationship value as a number. Understands the new single values, the old
# multiple_select JSON list and the old relationship words, so a row written by
# an older build still reads. The most negative word in a list decides.
sub relationship_part_rating {
	my ($part) = @_;
	$part = lc($part // '');
	$part =~ s/^\s+|\s+$//g;
	return 0 unless length $part;
	return $relationship_rating{$part} if exists $relationship_rating{$part};
	return 3 if $part =~ /^(?:enemy|hostile|combative|adversarial|blacklist|blacklisted|blocked)$/;
	return 2 if $part =~ /^(?:stranger|unknown|indifferent|neutral|competitive)$/;
	return 1 if $part =~ /^(?:friend|friendly|self|familial|amicable|professional|sexual|marital|holy)$/;
	return 0;
}

sub relationship_rating {
	my ($value) = @_;
	$value = $value->{'value'} if ref $value eq 'HASH';
	$value = join ',', @{$value} if ref $value eq 'ARRAY';
	return 0 unless defined $value;
	my $v = "$value";
	$v = lc $v;
	$v =~ s/^\s+|\s+$//g;
	return $relationship_rating{$v} if exists $relationship_rating{$v};
	if ($v =~ /^\s*\[/) {
		my $list = eval { decode_json($v) };
		$v = ref $list eq 'ARRAY' ? join ',', @{$list} : '';
	}
	my $rating = 0;
	foreach my $part (split /[,\s]+/, $v) {
		my $r = &relationship_part_rating($part);
		$rating = $r if $r > $rating;
	}
	return $rating;
}

sub relationship_value {
	my ($value) = @_;
	my $rating = &relationship_rating($value);
	return '' unless $rating;
	return ('', 'friend', 'stranger', 'enemy')[$rating];
}

sub relationship_options {
	return [ map { {
		value => $_,
		rating => $relationship_rating{$_},
		label => &format_name($_),
	} } @relationship_order ];
}

# The newest app_measures row for an app, across devices: a relationship is a
# fact about the person, not about the phone it was typed on.
sub person_relationship_value {
	my ($app) = @_;
	return '' unless defined $app && length $app;
	my $row = eval {
		&db_query("select value from settings where app = ? and setting = 'app_measures' order by cast(server_time as integer) desc limit 1", $app)->hashes->[0];
	};
	my $am = $row ? (eval { decode_json($row->{'value'}) } || {}) : {};
	my $value = &relationship_value($am->{'relationship'}->{'value'} // '');
	unless (length $value) {
		my $direct = eval {
			&db_query("select value from settings where app = ? and setting = 'relationship' order by cast(server_time as integer) desc limit 1", $app)->hashes->[0];
		};
		$value = &relationship_value($direct->{'value'} // '') if $direct;
	}
	return $value;
}

sub person_relationship_rating {
	my ($app) = @_;
	return &relationship_rating(&person_relationship_value($app));
}

# Every app that carries a relationship, newest row wins. Used by the
# junderground grade so the room reads the house's own relationship map rather
# than a second hand-typed list.
sub person_relationships {
	my %map;
	my $rows = eval {
		&db_query("select app, value from settings where setting = 'app_measures' and value like '%relationship%' order by cast(server_time as integer)")->hashes;
	} || [];
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'} // next;
		my $am = eval { decode_json($row->{'value'}) } || {};
		my $value = &relationship_value($am->{'relationship'}->{'value'} // '');
		next unless length $value;
		$map{$app} = { value => $value, rating => $relationship_rating{$value} };
	}
	my $direct = eval {
		&db_query("select app, value from settings where setting = 'relationship' order by cast(server_time as integer)")->hashes;
	} || [];
	foreach my $row ( @{$direct} ) {
		my $app = $row->{'app'} // next;
		my $value = &relationship_value($row->{'value'});
		next unless length $value;
		$map{$app} = { value => $value, rating => $relationship_rating{$value} };
	}
	return \%map;
}

# Who is present: a person app with an appointment still running. junderground
# starts one for each other person in a room it has joined, and a person's own
# open appointment is a presence too, so this is the house's one local signal.
our $present_person_apps_cache;
sub present_person_apps {
	my ($opts) = @_;
	$opts ||= {};
	return $present_person_apps_cache if defined $present_person_apps_cache && !$opts->{'refresh'};
	my $rows = eval {
		&db_query(q{
			select distinct a.app as app
			  from appointments a
			 where (a.stop_timestamp is null or a.stop_timestamp = '')
			   and a.type in ('start','record')
			   and exists (
			       select 1 from settings s
			        where s.app = a.app
			          and s.setting in ('pos','mab')
			          and s.value = 'person'
			   )
		})->hashes;
	} || [];
	my @apps = map { $_->{'app'} } grep { defined $_->{'app'} && length $_->{'app'} } @{$rows};
	$present_person_apps_cache = \@apps;
	return $present_person_apps_cache;
}

our $presence_relationship_cache;
sub present_relationship_rating {
	my ($opts) = @_;
	$opts ||= {};
	return $presence_relationship_cache if defined $presence_relationship_cache && !$opts->{'refresh'};
	my $rating = 0;
	foreach my $app ( @{ &present_person_apps($opts) } ) {
		my $r = &person_relationship_rating($app);
		$rating = $r if $r > $rating;
	}
	$presence_relationship_cache = $rating;
	return $rating;
}

# A person with an Enemy relationship and an open appointment. During lockdown
# these are the only apps a fingerprint may reveal, one at a time, so the
# person can be seen and stopped.
our $lockdown_enemy_apps_cache;
sub lockdown_enemy_apps {
	my ($opts) = @_;
	$opts ||= {};
	return $lockdown_enemy_apps_cache if defined $lockdown_enemy_apps_cache && !$opts->{'refresh'};
	my %apps;
	foreach my $app ( @{ &present_person_apps($opts) } ) {
		$apps{$app} = 1 if &person_relationship_rating($app) >= 3;
	}
	$lockdown_enemy_apps_cache = \%apps;
	return $lockdown_enemy_apps_cache;
}

# A dangerous place and an Enemy present are the same thing: the house locks
# down. There is deliberately no destructive "leave" here - the emergency wipe
# is a separate act, never something a sensor can trigger.
sub lockdown_active {
	return &visibility_exposure() >= 3 ? 1 : 0;
}

# The fingerprint reveal. It is a short grant on this device, not a change to
# the room: other apps stay shut, only the Enemy's running app appears, and the
# grant lapses on its own so the lockdown comes back if nothing is stopped.
sub lockdown_revealed {
	my ($device) = @_;
	$device = &device_setter() unless defined $device && length $device;
	return 0 unless $device;
	my $now = &rightNow();
	my $rows = eval {
		&db_query("select data from cache where context = 'lockdown_reveal' and device = ? order by server_time desc", $device)->hashes;
	} || [];
	foreach my $row ( @{$rows} ) {
		my $d = eval { decode_json($row->{'data'}) } || {};
		return 1 if ($d->{'until'} || 0) > $now;
	}
	return 0;
}

sub lockdown_reveal_store {
	my ($device, $until) = @_;
	$device = &device_setter() unless defined $device && length $device;
	return 0 unless $device;
	my $now = &rightNow();
	$until = $now + 120000 unless defined $until && $until > $now;
	&db_query("delete from cache where context = 'lockdown_reveal' and device = ?", $device);
	&db_insert('cache', {
		uuid => &random_string_creator(25),
		context => 'lockdown_reveal',
		app => 'security',
		device => $device,
		data => encode_json({ until => $until }),
		timestamp => $now,
		server_time => $now,
	});
	return $until;
}

sub lockdown_reveal_clear {
	my ($device) = @_;
	$device = &device_setter() unless defined $device && length $device;
	return 0 unless $device;
	&db_query("delete from cache where context = 'lockdown_reveal' and device = ?", $device);
	return 1;
}

# Close every window the lockdown does not allow, now. Security stays (it is
# the way to the fingerprint), an app marked dangerous stays, and the Enemy's
# own app stays only while this device holds a fresh reveal.
our %lockdown_sweep_at;
sub lockdown_sweep {
	my ($opts) = @_;
	$opts ||= {};
	return 0 unless &lockdown_active();
	my $now = &rightNow();
	my $device = $opts->{'device'};
	$device = &device_setter() unless defined $device;
	my $tab = $opts->{'browser_tab_id'};
	my $key = ($device || '') . "\x1f" . ($tab || '');
	return 0 if !$opts->{'force'} && defined $lockdown_sweep_at{$key} && $now - $lockdown_sweep_at{$key} < 3000;
	$lockdown_sweep_at{$key} = $now;
	my $revealed = &lockdown_revealed($device);
	my $enemies = &lockdown_enemy_apps();
	&Websocket::send('server', { console => '$("#start_menu").addClass("lockdown");', browser_tab_id => $tab });
	my $rows = eval {
		&db_query("select distinct app, browser_tab_id from websockets where type = 'stayingAlive'")->hashes;
	} || [];
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'} // next;
		my $row_tab = $row->{'browser_tab_id'} || '';
		next if defined $tab && length $tab && $row_tab ne $tab;
		next if $app =~ /^(?:server|tab|manager)\z/;
		next if $app eq 'security';
		if ($enemies->{$app}) {
			next if $revealed;
		}
		elsif (&visibility_normalize(&app_visibility_value($app)) eq 'dangerous') {
			next;
		}
		&window_closer($app, $row_tab);
	}
	return 1;
}

# The numeric rating of the room now: the place's own number, raised to 3 when
# an enemy is present. A house with no fix reads as public, the same default
# the manual place switch and the guide use.
our $visibility_exposure_cache;
sub visibility_site_rating {
	my $sig = &signatorial_designer();
	my $nav = eval { &navigation_information({ signatorial => $sig, cache => 'yes' }) } || {};
	my $rating = $nav->{$sig}->{'site_rating'};
	return ($rating =~ /^\d+$/ && $rating > 0) ? $rating + 0 : 2;
}

sub visibility_exposure {
	return $visibility_exposure_cache if defined $visibility_exposure_cache;
	my $place = &visibility_site_rating();
	my $presence = &present_relationship_rating();
	$place = 3 if $presence >= 3;   # an enemy is a dangerous room
	$visibility_exposure_cache = $place;
	return $visibility_exposure_cache;
}

# Normalise the visible setting. The three levels are the numbered place scale.
# `checked`/`on` become public (the new default); `unchecked` and the retired
# `off` become private, the least visible level that still exists.
sub visibility_normalize {
	my ($value) = @_;
	my $v = lc($value // '');
	$v =~ s/^\s+|\s+$//g;
	return 'private' if $v eq 'private' || $v eq 'unchecked' || $v eq 'off' || $v eq 'hidden' || $v eq 'none' || $v eq 'no' || $v eq '1';
	return 'dangerous' if $v eq 'dangerous' || $v eq '3';
	return 'public';
}

sub visibility_rank {
	my ($value) = @_;
	my $v = &visibility_normalize($value);
	return 1 if $v eq 'private';
	return 3 if $v eq 'dangerous';
	return 2;
}

# This device's row wins, then the house's `all` row, then the person's `me`
# row, then the newest. No row at all is the new-app default: public.
our %app_visibility_cache;
sub app_visibility_value {
	my ($app) = @_;
	return 'public' unless defined $app && length $app;
	my $device = &device_setter();
	my $cache_key = $device . "\x1f" . $app;
	return $app_visibility_cache{$cache_key} if exists $app_visibility_cache{$cache_key};
	my $rows = eval {
		&db_query("select value, device from settings where app = ? and setting = 'visible' order by cast(server_time as integer) desc", $app)->hashes;
	} || [];
	my ($own, $all, $me, $latest);
	foreach my $row ( @{$rows} ) {
		my $d = $row->{'device'} // '';
		$latest = $row->{'value'} unless defined $latest;
		$all = $row->{'value'} if $d eq 'all';
		$me = $row->{'value'} if $d eq 'me';
		$own = $row->{'value'} if $d eq $device;
	}
	my $value = defined $own ? $own : defined $all ? $all : defined $me ? $me : $latest;
	$value = &visibility_normalize($value);
	$app_visibility_cache{$cache_key} = $value;
	return $value;
}

# A picker can ask about hundreds of apps at once (every appointment in the
# house). Read their visibility rows in one query and fill the same request
# cache app_visibility_value uses, so each app's check costs no query.
sub app_visibility_preload {
	my ($apps) = @_;
	return 0 unless ref $apps eq 'ARRAY' && scalar @{$apps};
	my $device = &device_setter();
	my %wanted;
	foreach my $app ( @{$apps} ) {
		next unless defined $app && length $app;
		$wanted{$app} = 1;
	}
	return 0 unless scalar keys %wanted;
	my $rows = eval {
		&db_query("select app, value, device from settings where setting = 'visible' order by cast(server_time as integer) desc")->hashes;
	} || [];
	my (%own, %all, %me, %latest);
	foreach my $row ( @{$rows} ) {
		my $app = $row->{'app'} // next;
		next unless $wanted{$app};
		my $d = $row->{'device'} // '';
		my $value = $row->{'value'};
		$latest{$app} = $value unless defined $latest{$app};
		$all{$app} = $value if $d eq 'all';
		$me{$app} = $value if $d eq 'me';
		$own{$app} = $value if $d eq $device;
	}
	foreach my $app ( keys %wanted ) {
		my $value = defined $own{$app} ? $own{$app}
			: defined $all{$app} ? $all{$app}
			: defined $me{$app} ? $me{$app}
			: $latest{$app};
		$app_visibility_cache{$device . "\x1f" . $app} = &visibility_normalize($value);
	}
	return 1;
}

sub visibility_hidden_for {
	my ($value, $exposure) = @_;
	my $rank = &visibility_rank($value);
	$exposure = &visibility_exposure() unless defined $exposure;
	return $exposure > $rank ? 1 : 0;
}

sub app_hidden_now {
	my ($app) = @_;
	return 0 unless defined $app && length $app;
	if (&lockdown_active()) {
		return 0 if $app eq 'security';
		my $device = &device_setter();
		if (&lockdown_enemy_apps()->{$app}) {
			return &lockdown_revealed($device) ? 0 : 1;
		}
		return 0 if &visibility_normalize(&app_visibility_value($app)) eq 'dangerous';
		return 1;
	}
	return &visibility_hidden_for(&app_visibility_value($app));
}

sub app_visible_now {
	my ($app) = @_;
	return &app_hidden_now($app) ? 0 : 1;
}

# The domain -> app map the Internet app keeps. A site a person assigned to an
# app is that app's session too, so both the manager and the browser tick read
# the same map.
sub internet_domain_app_map {
	my $value = &setting_grabber({ app => 'internet', setting => 'domain_apps' });
	my $map = eval { decode_json($value || '{}') } || {};
	return ref $map eq 'HASH' ? $map : {};
}

# A browser posts a site span every half minute while its page is in front
# (and as the page closes or loses focus). While a span for a mapped domain
# keeps arriving, its app's session runs. A gap longer than the grace is a
# person who left: the session stops at the last span's end, not at the next
# tick, so the recorded time is the time actually spent on the site.
our $internet_site_tick_at;
sub internet_site_appointment_tick {
	my ($opts) = @_;
	$opts ||= {};
	my $now = &rightNow();
	return 0 if !$opts->{'force'} && defined $internet_site_tick_at && $now - $internet_site_tick_at < 2000;
	$internet_site_tick_at = $now;
	my $map = &internet_domain_app_map();
	return 0 unless scalar keys %{$map};
	my $grace = 60000;
	my $from = $now - 15 * 60 * 1000;
	my $rows = eval {
		&db_query(q{
			select key_name, started_at, ended_at
			  from usage_sessions
			 where kind = 'site' and cast(ended_at as integer) >= ?
			 order by cast(started_at as integer) asc
		}, $from)->hashes;
	} || [];
	my (%run_start, %run_end, %domains_for_app);
	foreach my $domain ( keys %{$map} ) {
		my $app = $map->{$domain} // next;
		push @{$domains_for_app{$app}}, $domain if length $domain;
	}
	foreach my $row ( @{$rows} ) {
		my $domain = lc($row->{'key_name'} // '');
		$domain =~ s/^www\.//;
		my $app = $map->{$domain} || next;
		my $start = int($row->{'started_at'} // 0);
		my $end = int($row->{'ended_at'} // 0);
		next unless $start > 0 && $end > 0;
		if (!defined $run_end{$app}) {
			$run_start{$app} = $start;
			$run_end{$app} = $end;
		}
		elsif ($start <= $run_end{$app} + $grace) {
			$run_end{$app} = $end if $end > $run_end{$app};
		}
		else {
			$run_start{$app} = $start;
			$run_end{$app} = $end;
		}
	}
	# Sessions this tick owns: close one whose site is no longer reported, or
	# whose app the visibility rule now hides. Never touch a session the person
	# started themselves.
	my $open_rows = eval {
		&db_query(q{
			select app, uuid, timestamp from appointments
			 where source = 'Internet' and (type = 'start' or type = 'record')
			   and stop_seen is null
		})->hashes;
	} || [];
	foreach my $open ( @{$open_rows} ) {
		my $app = $open->{'app'} || next;
		my $uuid = $open->{'uuid'} || next;
		my $started = int($open->{'timestamp'} // 0);
		my $last = $run_end{$app};
		if (!defined $last) {
			my $domains = $domains_for_app{$app} || [];
			if (scalar @{$domains}) {
				my $ph = join ',', map { '?' } @{$domains};
				my $row = eval {
					&db_query("select max(cast(ended_at as integer)) as last_end from usage_sessions where kind = 'site' and key_name in ($ph) and cast(ended_at as integer) >= ?", @{$domains}, $started)->hash;
				} || {};
				$last = int($row->{'last_end'}) if defined $row->{'last_end'} && $row->{'last_end'} ne '';
			}
		}
		my $active = defined $last && ($now - $last) <= $grace && !&app_hidden_now($app);
		next if $active;
		my $stop_at = (defined $last && $last > $started) ? $last : $now;
		my $duration = $stop_at - $started;
		$duration = 0 if $duration < 0;
		&db_update('appointments', {
			type => 'stop',
			stop_timestamp => $stop_at,
			stop_seen => 'yes',
			duration => $duration,
			server_time => $now,
		}, { uuid => $uuid, app => $app });
		&intelligent_automation_toggle({ appt_uuid => $uuid, app => $app, 'state' => 'off', timestamp => $stop_at });
		&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $app . '\',\'' . $uuid . '\');' });
	}
	# Sessions to start: a mapped site that is still being reported and has no
	# session of any kind running for its app.
	foreach my $app ( sort keys %run_end ) {
		next if $now - $run_end{$app} > $grace;
		next if &app_hidden_now($app);
		next if &open_session_uuid($app);
		my $init = &setting_initializer($app, $run_start{$app});
		my $name = (ref $init eq 'HASH' && $init->{'app'}) ? $init->{'app'} : $app;
		next if $name ne $app && (&open_session_uuid($name) || &app_hidden_now($name));
		my $start_at = $run_start{$app};
		# A session that just ended (a person starting and stopping by hand while
		# the page was open) must not be counted twice.
		my $prev = eval {
			&db_query("select max(cast(stop_timestamp as integer)) as last_end from appointments where app = ? and stop_timestamp is not null and stop_timestamp != '' and cast(stop_timestamp as integer) <= ?", $name, $now)->hash;
		} || {};
		my $prev_end = int($prev->{'last_end'} // 0);
		$start_at = $prev_end if $prev_end > $start_at;
		my $settings = &settings_grabber({ app => $name });
		my $uuid = &random_string_creator(90);
		my $row = {
			app => $name,
			uuid => $uuid,
			type => 'start',
			timestamp => $start_at,
			server_time => $now,
			device => &device_setter(),
			source => 'Internet',
			seen => 'yes',
			project => $settings->{'t_project'},
			pos => $settings->{'pos'},
		};
		$row->{'warranty'} = &ago_calc(($init->{'warranty'} || '-10y'), $now) if ref $init eq 'HASH';
		&db_insert('appointments', $row);
		my ($model, $options, $jmodel, $joptions) = &usual_appointment_maker($row, $settings);
		$row->{'model'} = $jmodel if $jmodel;
		$row->{'options'} = $joptions if $joptions;
		$row->{'unit'} = $model->{'unit'} if $model->{'unit'} && !$row->{'unit'};
		$row->{'quantity'} = $model->{'quantity'} if $model->{'quantity'} && !$row->{'quantity'};
		&db_update('appointments', { model => $row->{'model'}, options => $row->{'options'}, unit => $row->{'unit'}, quantity => $row->{'quantity'} }, { uuid => $uuid, app => $name })
			if $row->{'model'} || $row->{'options'} || $row->{'unit'} || $row->{'quantity'};
		&intelligent_automation_toggle({ appt_uuid => $uuid, app => $name, 'state' => 'on', timestamp => $start_at });
		&Websocket::send('tab', { console => 'appointmentDetailGrabber(\'' . $name . '\',\'' . $uuid . '\');' });
	}
	return 1;
}

# A settings write or a presence change must be seen by the rest of this
# request; a worker serves one request at a time, so these are request caches.
sub visibility_cache_clear {
	%app_visibility_cache = ();
	$visibility_exposure_cache = undef;
	$presence_relationship_cache = undef;
	$present_person_apps_cache = undef;
	$lockdown_enemy_apps_cache = undef;
	return 1;
}

# The plate remembers how its latest navigation stop happened. A departure more
# than three radii away is certain - no ordinary GPS jitter brings a person back
# from there - so a return must start a new session instead of reopening the one
# it closed. A near-boundary stop stays resumable for the fifteen-minute window
# in navigation_automation. The fact is transient (a cache entry), but it only
# has to outlive the next fix and the resume window.
sub navigation_plate_exit_set {
	my ($app, $duty, $certain) = @_;
	return unless $app && $duty;
	&subs::cache_set({
		app => '__president',
		context => 'navigation_plate_exit',
		subcontext => $app . ':' . $duty,
		warranty => '-1h'
	}, { certain => ($certain ? 1 : 0), at => &subs::rightNow() });
}

sub navigation_plate_exit_certain {
	my ($app, $duty) = @_;
	return 0 unless $app && $duty;
	my $exit = &subs::cache_get({ app => '__president', context => 'navigation_plate_exit', subcontext => $app . ':' . $duty });
	return (ref $exit eq 'HASH' && $exit->{'certain'}) ? 1 : 0;
}

sub navigation_plate_exit_clear {
	my ($app, $duty) = @_;
	return unless $app && $duty;
	&subs::cache_delete({ app => '__president', context => 'navigation_plate_exit', subcontext => $app . ':' . $duty });
}

# A departure more than three radii from a plate is a certain leave: no ordinary
# GPS jitter brings a person back to that plate from there. A loose fix is not
# certainty - 200 m is the house's own bound on a usable place - so a coarse
# reading does not count.
sub navigation_plate_certain_exit {
	my $data = shift || {};
	my $radius = 0 + ($data->{'radius'} || 0);
	return 0 unless $radius > 0;
	my $measured = 0 + ($data->{'measured'} || 0);
	my $accuracy = 0 + ($data->{'accuracy'} || 0);
	return 0 if $accuracy >= 200;
	return $measured > 3 * $radius ? 1 : 0;
}

sub navigation_automation() {
	my ($returner, $provider) = @_;
	$returner->{'signatorial'} = &subs::signatorial_designer() unless $returner->{'signatorial'};
	my $signatorial = $returner->{'signatorial'};

	# Only a fix a real GPS produced may cross a plate. The browser's network
	# estimate and a desktop's home-plate fallback carry no provider, and both
	# are exactly the plausible-looking place that must not move an appointment.
	return unless (($provider || '') eq 'gps');

	my $cache = &subs::cache_get({ app => '__president', context => 'navigation_automation', subcontext => $signatorial });
	return if $cache->{'timestamp'} + 5000 > &subs::rightNow();
	&subs::cache_set({ app => '__president', context => 'navigation_automation', subcontext => $signatorial }, { timestamp => &subs::rightNow() });


	my $device = &subs::device_setter();
	my $hpds = &subs::db_query('select * from settings where setting=? and value is not null and value != ?', 'home_plate_duties', '[]')->hashes;
	foreach my $hpder ( @{$hpds} ) {
		my $home_plate = eval { return decode_json &subs::setting_grabber({ app => $hpder->{'app'}, setting => 'home_plate' }) || &subs::setting_grabber({ app => 'me', setting => 'home_plate' }) } || {};
		if ($home_plate->{'latitude'}) {
			my $hpd = eval { return decode_json $hpder->{'value'} } || [];
			foreach my $hp ( @{$hpd} ) {
				if ($hp->{'device'} eq $signatorial || $hp->{'device'} eq $device) {
					my $app = $hp->{'self'} eq 'on' ? $hpder->{'app'} : $hp->{'app'};
					if (!$app && ($hp->{'self'} eq 'off' && !$hp->{'app'})) {
						next;
					}
					my @home_plate = (deg2rad($home_plate->{'longitude'}), deg2rad(90 - $home_plate->{'latitude'}));
					my @visitor = (deg2rad($returner->{'longitude'}), deg2rad(90 - $returner->{'latitude'}));
					my $distance = sprintf("%.3f", great_circle_distance(@home_plate, @visitor, $gb::planet_radius));
					my $duty_key = $hp->{'uuid'};
					$duty_key = join('|', $hpder->{'app'} || '', $app || '', $hp->{'placement'} || '', $hp->{'distance'} || '', $hp->{'action'} || '') unless $duty_key;
					# A stop-side fix farther than three radii is a certain leave. The
					# comparison only matters when the person comes back: that return
					# starts a new session instead of reopening the closed one.
					my $certain_exit = &subs::navigation_plate_certain_exit({
						radius => $hp->{'distance'},
						measured => $distance,
						accuracy => $returner->{'accuracy'},
					});
					my $actable = 0;
					my $cactable = 0;

					my $hset = &subs::settings_grabber({ app => $app, settings => [ 'warranty', 'toggle', 'site_type'] });
					my $tog = &subs::appt_toggle_checker($app) || $hset->{'toggle'};
					my $hpdata = {
						app => $app,
						timestamp => &subs::rightNow(),
						type => $hp->{'action'},
						subtype => 'navigation',
						uuid => &subs::random_string_creator(22)
					};
					if ($hp->{'placement'} eq 'within') {
						if ($distance <= $hp->{'distance'}) {
							if ($hset->{'site_type'} eq 'dangerous') {
							#	&Manager::leave();
							}
							elsif ($tog ne 'on') {
								# A return within fifteen minutes of a navigation stop is the
								# same visit, so reopen that session rather than starting a new
								# one. A leave farther than three radii was certain, so its
								# return starts a new session even inside the window. Reopen
								# only the newest stop - the one the person has just come back
								# from - never every stop in the window.
								my $lappts = &subs::db_query('select * from appointments where app = ? and subtype = ? and type = ? and stop_timestamp >= ? order by stop_timestamp desc limit 1', $app, 'navigation', 'stop', &subs::rightNow() - 15 * 60 * 1000)->hashes;
								my $certain_leave = &subs::navigation_plate_exit_certain($app, $duty_key);
								&subs::navigation_plate_exit_clear($app, $duty_key);
								if (scalar @{$lappts} > 0 && !$certain_leave) {
									foreach my $lapp ( @{$lappts} ) {
										$hpdata->{'uuid'} = $lapp->{'uuid'};
										# reopen the session it closed when the plate was left. stop_seen
										# must be cleared too: the stop resolvers (stop_target_row /
										# open_session_uuid) define the open session as one with stop_seen
										# null, so leaving it set left the row open but invisible - the
										# plate's own next leave and return then had nothing to close or
										# reopen (a "returning home" that never logged).
										&subs::db_update('appointments', {
											type => $hp->{'action'},
											stop_timestamp => undef,
											stop_seen => undef,
											server_time => &subs::rightNow(),
											duration => undef
										}, { app => $app, uuid => $lapp->{'uuid'} });
									}
									$actable = 0;
									$cactable = 1;
								} else {
									$actable = 1;
									$cactable = 1;
								}
							}
							else {
								# Back inside with the session still running: the departure is
								# over, so a later stop starts a fresh certainty.
								&subs::navigation_plate_exit_clear($app, $duty_key);
							}
						}
						else {
							# A far fix upgrades the departure even when nothing was running
							# to stop (a near first fix may already have closed the session).
							&subs::navigation_plate_exit_set($app, $duty_key, 1) if $certain_exit;
							if ($tog eq 'on') {
								my $stoppable = 0;
								my $lappts = &subs::db_query('select uuid,app,type,subtype,timestamp,server_time from appointments where app=? and (type = ? or type =?) and timestamp < ?', $app, 'start','record',$returner->{'timestamp'})->hashes;
								foreach my $lappt ( @{$lappts} ) {
									# an appointment the navigation itself started was started
									# here, so leaving the plate closes it; a hand-started one
									# still needs a recorded in-plate fix before it is touched
									if ($lappt->{'subtype'} eq 'navigation') {
										$stoppable = 1;
										next;
									}
									my $locals = &subs::db_query('select * from continent where app=? and uuid like ? and signatorial=?', $app, $lappt->{'uuid'} . '%',$signatorial)->hashes;
									foreach my $local ( @{$locals} ) {
										my @visitor = (deg2rad($local->{'longitude'}), deg2rad(90 - $local->{'latitude'}));
										my $distance = sprintf("%.3f", great_circle_distance(@home_plate, @visitor, $gb::planet_radius));
										if ($distance <= $hp->{'distance'}) {
											$stoppable = 1;
										}
									}
								}
								if ($stoppable == 1) {
									$hpdata->{'type'} = 'stop';
									undef $hpdata->{'uuid'};
									$actable = 1;
									$cactable = 1;
									&subs::navigation_plate_exit_set($app, $duty_key, $certain_exit);
								}
							}
						}
					}
					if ($hp->{'placement'} eq 'without') {
						if ($distance >= $hp->{'distance'}) {
							if ($tog ne 'on') {
								$actable = 1;
								$cactable = 1;
							}
						}
						else {
							if ($tog eq 'on') {
								my $stoppable = 0;
								my $lappts = &subs::db_query('select uuid,app,type,subtype,timestamp,server_time from appointments where app=? and (type = ? or type =?) and timestamp < ?', $app, 'start','record',$returner->{'timestamp'})->hashes;
								foreach my $lappt ( @{$lappts} ) {
									# an appointment the navigation itself started was started
									# here, so leaving the plate closes it; a hand-started one
									# still needs a recorded in-plate fix before it is touched
									if ($lappt->{'subtype'} eq 'navigation') {
										$stoppable = 1;
										next;
									}
									my $locals = &subs::db_query('select * from continent where app=? and uuid like ? and signatorial=?', $app, $lappt->{'uuid'} . '%',$signatorial)->hashes;
									foreach my $local ( @{$locals} ) {
										my @visitor = (deg2rad($local->{'longitude'}), deg2rad(90 - $local->{'latitude'}));
										my $distance = sprintf("%.3f", great_circle_distance(@home_plate, @visitor, $gb::planet_radius));
										if ($distance >= $hp->{'distance'}) {
											$stoppable = 1;
										}
									}
								}
								if ($stoppable == 1) {
									$hpdata->{'type'} = 'stop';
									undef $hpdata->{'uuid'};
									$actable = 1;
									$cactable = 1;
								}
							}
						}
					}

					if ($actable == 1) {
						&Manager::appointment_writer(undef, $hpdata);

					}
					if ($cactable == 1) {
						my $cdata = {
							timestamp => $returner->{'timestamp'},
							latitude => $returner->{'latitude'},
							longitude => $returner->{'longitude'},
							accuracy => sprintf("%.2F", $returner->{'accuracy'}),
							server_time => &subs::rightNow(),
							uuid => $hpdata->{'uuid'} . '-' . &subs::random_string_creator(8),
							type => 'app',
							app => $app,
							warranty => &subs::ago_calc($hset->{'warranty'}, &subs::rightNow()),
							signatorial => $signatorial
						};
						&subs::db_insert('continent', $cdata);
					}
				}
			}
		}
	}

	&subs::navigation_information();
}


# The hour of the day each app most often happens at, over the recent past, in
# one query for every app. The clothesline reads in the order the day does, so
# this gives it that order; it also names the apps whose routine is regular
# enough to hang themselves, and the hour to hang them at. `hour_days` is how
# many of the days the anchor hour was seen on, `days` how many days the app was
# seen at all.
sub clothesline_daily_hours() {
	my $days = 14;
	my $now = &rightNow();
	my $since = $now - ($days * 86400 * 1000);
	my $rows = &db_query('select app, timestamp from appointments where timestamp >= ? and timestamp <= ? and type in (?, ?)', $since, $now, 'usual', 'stop')->hashes;
	my (%hour_days, %app_days);
	foreach my $r ( @{$rows} ) {
		next unless $r->{'timestamp'};
		my $time = localtime($r->{'timestamp'} / 1000);
		my ($hour, $yday) = ($time->[2], $time->[7]);
		$hour_days{$r->{'app'}}->{$hour}->{$yday} = 1;
		$app_days{$r->{'app'}}->{$yday} = 1;
	}
	my $out = {};
	foreach my $app ( keys %hour_days ) {
		my ($best, $bestc) = (undef, -1);
		foreach my $h ( keys %{$hour_days{$app}} ) {
			my $c = scalar keys %{$hour_days{$app}->{$h}};
			if ($c > $bestc) { ($best, $bestc) = ($h, $c); }
		}
		$out->{$app} = { hour => $best, hour_days => $bestc, days => scalar keys %{$app_days{$app}} };
	}
	return $out;
}

sub hang_to_dry() {
	my $server_time = &rightNow();
	my $returner = [];

	my $time_plinkos = clone $gb::time_plinkos;
	my $cls = &db_query('select * from settings where setting = ? and device = ? and app!= ? and value is not null', 'clothesline', $device,'__president')->hashes;

	foreach my $clr ( @{$cls} ) {

		my $cl = eval { return decode_json $clr->{'value'} } || {};
		my $time = localtime($server_time / 1000);
		my $app = &unformat_name($clr->{'app'});
		my $settings = &settings_grabber({ app => $app });
		my $app_data = { name => $app, app => $app, formatted_name => &format_name($app), colour => $settings->{'colour'}, dark_colour => $settings->{'dark_colour'} };
		my $time_plinko = $cl->{'time_plinko'} || {};
		my @schedule = split ',', $cl->{'schedule'};
		foreach my $schedule ( @schedule ) {

		}
		my $count = scalar keys %{$cl->{'time_plinko'}};
		my $cl_count = 0;

		for (my $n = 0; $n <= 8; $n++) {
			my $ft = $time->[$n];
			if ($n == 2) {
				if ($ft == 0) {
					$ft = '12am';
				}
				elsif ($ft >= 12) {
					if ($ft == 12) { $ft = 24; }
					$ft = ($ft - 12) . 'pm';
				}
				elsif ($time->[$n] > 0 && $time->[$n] < 13) {
					$ft .= 'am';
				}
			}
			if ($n == 4) { $ft = $time->monname; }
			if ($n == 5) { $ft += 1900; }
			if ($n == 6) { $ft = $time->wdayname; }

			if ($time_plinko->{$time_plinkos->[$n]->{'name'}}) {

				if (grep { $_ eq $ft || $_ eq 'all' } @{$time_plinko->{$time_plinkos->[$n]->{'name'}}}) {
					$cl_count++;
					if ($cl_count == $count) {
						if (!&app_hidden_now($app)) {
							push @{$returner}, $app_data;
						}

					}
				}
			}
		}
		unless (grep { $_->{'app'} eq $app } @{$returner}) {
			my $running_appts = &db_query('select * from appointments where app = ? and (type = ? or type = ?)',$app, 'start','record')->hashes;
			if (scalar @{$running_appts} > 0) {
				push @{$returner}, $app_data;
			}
			foreach my $circumstance( keys %{$gb::budget_modes} ) {
				if ($cl->{$circumstance . '_budget'}) {
					my $budget = &subs::cache_get({ app => $app, context => 'budget', subcontext => $circumstance });
					if (grep { $budget->{'status'} eq $_ } @{$cl->{$circumstance . '_budget'}}) {
						push @{$returner}, $app_data unless grep { $_->{'app'} eq $app } @{$returner};
					}
				}
			}
		}



	}
	# The day's order, and the apps regular enough to hang themselves. An app the
	# user has never given a clothesline setting is offered at the hour its own
	# history keeps it, when that hour holds on most of the last fortnight and the
	# app is in its visible state. A setting of `off` in `clothesline_daily_auto`
	# turns the automatic hanging off; it is on when unset.
	my $daily = &clothesline_daily_hours();
	my $cur_time = localtime($server_time / 1000);
	my $cur_hour = $cur_time->[2];
	my %configured = map { &unformat_name($_->{'app'}) => 1 } @{$cls};
	# an app another app adds on its own - a default option, or a default model -
	# is not a thing the user clicks, so it never hangs itself (the coffee behind
	# the cream, the lunch behind its eggs). Their parent carries the routine.
	my $autos = &db_query(q{select distinct name from option where name is not null and name != app and lower(coalesce(def,'')) not in ('','off','false','0')
		union
		select distinct name from model where name is not null and name != app and lower(coalesce(def,'')) not in ('','off','false','0')})->hashes;
	my %auto_hung = map { $_->{'name'} => 1 } @{$autos};
	# the tasks an app carries: starting it records them as well, so they are not
	# clicks of the user's either (the flush and wash hands behind a pee or dump)
	my $task_rows = &db_query('select value from settings where setting = ? and value is not null', 'tasks')->hashes;
	foreach my $tr ( @{$task_rows} ) {
		my $list = eval { return decode_json $tr->{'value'} } || [];
		foreach my $t ( @{$list} ) {
			next unless $t->{'task'};
			$auto_hung{&unformat_name($t->{'task'})} = 1;
		}
	}
	# ...but a task or default the user also runs on their own is still theirs to
	# hang: a meaningful share of an app's own appointments carry no source (they
	# were not spawned by a parent). wash_hands is run by hand about half the time
	# and must stay; a flush that mostly follows a pee does not.
	my $auto_since = $server_time - (14 * 86400 * 1000);
	my $run_rows = &db_query(q{select app, count(*) total, sum(case when source_uuid is null or source_uuid = '' then 1 else 0 end) direct from appointments where type in ('usual','stop') and timestamp >= ? group by app}, $auto_since)->hashes;
	my %user_run;
	foreach my $r ( @{$run_rows} ) {
		next unless $r->{'total'};
		$user_run{$r->{'app'}} = 1 if ($r->{'direct'} / $r->{'total'}) >= 0.25;
	}
	my $auto = &setting_grabber({ app => '__president', setting => 'clothesline_daily_auto' });
	unless (defined $auto && lc($auto) eq 'off') {
		foreach my $app ( sort keys %{$daily} ) {
			next if $configured{$app};
			next if $auto_hung{$app} && !$user_run{$app};
			my $routine = $daily->{$app};
			next unless $routine->{'hour_days'} >= 7;
			next unless $routine->{'hour'} == $cur_hour;
			my $aset = &settings_grabber({ app => $app });
			next if &app_hidden_now($app);
			push @{$returner}, { name => $app, app => $app, formatted_name => &format_name($app), colour => $aset->{'colour'}, dark_colour => $aset->{'dark_colour'} };
		}
	}
	# left to right, the order the day happens in; apps with no time of their own
	# (no history yet) fall to the end rather than shuffling those that have one
	@{$returner} = sort {
		my $ha = (defined $daily->{$a->{'app'}} && defined $daily->{$a->{'app'}}->{'hour'}) ? $daily->{$a->{'app'}}->{'hour'} : 24;
		my $hb = (defined $daily->{$b->{'app'}} && defined $daily->{$b->{'app'}}->{'hour'}) ? $daily->{$b->{'app'}}->{'hour'} : 24;
		$ha <=> $hb || $a->{'app'} cmp $b->{'app'};
	} @{$returner};
	&subs::subprocessor(sub {
		foreach my $clothes ( @{$returner} ) {
			&Manager::centre_view_grabber({ app => &subs::unformat_name($clothes->{'app'}), timestamp => &subs::rightNow() });
		}
	}, { name => 'clothesline centreview cacher' });
	my $jreturner = encode_json $returner;
	&setting_setter({ app => '__president', setting => 'clothesline', value => $jreturner });
	return 0;

}

# ---- web measures ----------------------------------------------------------
# A web measure used to be a CSS selector plus a count, applied to whatever the
# last fetch stored. That works until a page reorders, and it cannot say where
# a JSON value lives. One spec now covers both worlds:
#
#   JSON:  { "path": "properties.currentConditions.temperature.value.en" }
#   HTML:  { "selector": "#price", "count": 0, "attribute": "text" }
#          { "row": "tr", "match": "Gold", "within": "td" }
#
# with optional regex, fallback, number/unit/scale and the old prev/next
# context. The old selector/count specs keep working unchanged; a JSON id from
# the prettyfier is mapped back to its path, so weather's old selectors start
# reading the decoded JSON instead of the rendered DOM.
sub web_measure_clean_text {
	my ($s) = @_;
	return '' unless defined $s;
	$s =~ s/\x{00A0}/ /g;
	$s =~ s/\s+/ /g;
	$s =~ s/^\s+|\s+$//g;
	return $s;
}

sub web_measure_json_path {
	my ($json, $path) = @_;
	return undef unless defined $path && length $path;
	my $p = $path;
	$p =~ s/^\$//;
	$p =~ s/\[(\d+)\]/.$1/g;
	my @t = grep { length } split /\./, $p;
	my $node = $json;
	for my $t (@t) {
		if (ref $node eq 'HASH') {
			return undef unless exists $node->{$t};
			$node = $node->{$t};
		}
		elsif (ref $node eq 'ARRAY') {
			return undef unless $t =~ /^\d+$/ && $t < scalar @{$node};
			$node = $node->[$t];
		}
		else {
			return undef;
		}
	}
	return $node;
}

# The JSON prettyfier writes <span id="propertiescurrentConditions..."> by
# concatenating the keys (arrays become 1arr, 2arr...). Recover the real path
# from that id, so an old JSON selector keeps working and can be read as a
# path instead of through the rendered page.
sub web_measure_json_id_path {
	my ($json, $id) = @_;
	return undef unless defined $id && length $id;
	my $flat = sub { my $s = shift; $s =~ s/[^A-Za-z0-9]//g; return $s; };
	my $want = $flat->($id);
	my $walk;
	$walk = sub {
		my ($node, $parts, $idparts) = @_;
		if (ref $node eq 'HASH') {
			foreach my $k ( sort keys %{$node} ) {
				my $r = $walk->($node->{$k}, [@{$parts}, $k], [@{$idparts}, $k]);
				return $r if defined $r;
			}
		}
		elsif (ref $node eq 'ARRAY') {
			for my $i ( 0 .. $#{$node} ) {
				my $r = $walk->($node->[$i], [@{$parts}, $i], [@{$idparts}, ($i + 1) . 'arr']);
				return $r if defined $r;
			}
		}
		else {
			return join('.', @{$parts}) if $flat->(join '', @{$idparts}) eq $want;
		}
		return undef;
	};
	return $walk->($json, [], []);
}

# Every scalar path a JSON response offers, for the picker and the audit tool.
sub web_measure_json_paths {
	my ($json, $prefix, $out, $limit) = @_;
	$prefix = '' unless defined $prefix;
	$out = [] unless ref $out eq 'ARRAY';
	$limit ||= 4000;
	return $out if scalar @{$out} >= $limit;
	if (ref $json eq 'HASH') {
		foreach my $k ( sort keys %{$json} ) {
			my $p = length $prefix ? $prefix . '.' . $k : $k;
			&web_measure_json_paths($json->{$k}, $p, $out, $limit);
		}
	}
	elsif (ref $json eq 'ARRAY') {
		for my $i ( 0 .. $#{$json} ) {
			my $p = (length $prefix ? $prefix : '') . '[' . $i . ']';
			&web_measure_json_paths($json->[$i], $p, $out, $limit);
		}
	}
	else {
		push @{$out}, { path => $prefix, value => $json };
	}
	return $out;
}

# One number parser for every source. Currency, percent, a degree sign and a
# unit suffix are stripped; a comma decimal and a thousands separator are read
# by position; a leading minus (or parentheses) is kept. appt_measure_writer
# used to strip everything but digits and dots, which quietly turned -0.5 into
# 0.5.
sub web_measure_number {
	my ($raw, $spec) = @_;
	$spec ||= {};
	return undef unless defined $raw;
	my $s = &web_measure_clean_text($raw);
	return undef unless length $s;
	my $neg = 0;
	if ($s =~ /^\((.*)\)\s*$/) { $neg = 1; $s = $1; }
	my ($token) = $s =~ /([+\-]?(?:\d[\d.,']*|\.\d+)(?:[eE][+\-]?\d+)?)/;
	return undef unless defined $token;
	$token =~ s/['\s]//g;
	my $sign = 1;
	if ($token =~ s/^-//) { $sign = -1; }
	$token =~ s/^\+//;
	my $dec = $spec->{'decimal'};
	my $thou = $spec->{'thousands'};
	if (!defined $dec || !length $dec) {
		my $last_comma = rindex($token, ',');
		my $last_dot = rindex($token, '.');
		if ($last_comma >= 0 && $last_dot >= 0) {
			if ($last_comma > $last_dot) { $dec = ','; $thou = '.'; }
			else { $dec = '.'; $thou = ','; }
		}
		elsif ($last_comma >= 0) {
			my @c = split /,/, $token;
			if (scalar @c == 2 && length($c[1]) && length($c[1]) <= 2) { $dec = ','; $thou = ''; }
			else { $dec = '.'; $thou = ','; }
		}
		else { $dec = '.'; $thou = ''; }
	}
	if ($thou) { $token =~ s/\Q$thou\E//g; }
	if ($dec ne '.') { $token =~ s/\Q$dec\E/./g; }
	return undef unless $token =~ /^\d*(?:\.\d*)?$/ && $token =~ /\d/;
	my $n = $token + 0;
	$n = -$n if $neg || $sign < 0;
	my $scale = $spec->{'scale'};
	$n *= $scale if defined $scale && $scale =~ /^-?\d+(?:\.\d+)?$/;
	if (defined $spec->{'decimals'} && $spec->{'decimals'} =~ /^\d+$/) {
		return sprintf('%.' . $spec->{'decimals'} . 'f', $n);
	}
	# Keep the precision the page wrote. A fixed %.10f rounds 149,095,031.14
	# through a float and prints 149095031.1399999857.
	my $dp = ($token =~ /\.(\d+)$/) ? length($1) : 0;
	$dp = 10 if $dp > 10;
	my $out = sprintf('%.' . $dp . 'f', $n);
	$out =~ s/0+$// if $out =~ /\./;
	$out =~ s/\.$//;
	return $out;
}

# Some pages write a label as bare text, with the value in the next element:
#   Phase: <span>Waxing Crescent</span><br>
# Mojo::DOM drops text nodes from children(), so match the label in the
# container's own markup and return the first element that follows it.
sub web_measure_after_text_label {
	my ($dom, $container, $label, $skip) = @_;
	return undef unless $dom && defined $container && length $container && defined $label && length $label;
	my $box = $dom->at($container) or return undef;
	my $html = $box->to_string;
	my $needle = lc $label;
	my $pos = -1;
	for (my $i = 0; $i <= ($skip || 0); $i++) {
		$pos = index(lc($html), $needle, $pos + 1);
		return undef if $pos < 0;
	}
	my $cursor = 0;
	foreach my $child ( @{$box->children} ) {
		next unless $child->type eq 'tag';
		my $markup = $child->to_string;
		my $at = index($html, $markup, $cursor);
		next unless $at >= 0;
		$cursor = $at + length $markup;
		next unless $at > $pos;
		my $tag = lc($child->tag || '');
		next if $tag eq 'br' || $tag eq 'hr' || $tag eq 'wbr';
		return $child;
	}
	return undef;
}

# Extract one value from a fetched page. $ctx is { format, json, dom, raw }.
sub web_measure_extract {
	my ($spec, $ctx) = @_;
	$spec ||= {};
	$ctx ||= {};
	require Mojo::DOM;
	require Mojo::Collection;
	my $result = { ok => 0, value => undef, raw => undef, used => '', error => '' };
	my $json = $ctx->{'json'};
	my $dom = $ctx->{'dom'};
	my $raw_value;
	my $used = '';
	my $attr = $spec->{'attribute'} || 'text';

	# 1. an explicit JSON path
	if (ref $json && defined $spec->{'path'} && length $spec->{'path'}) {
		my $v = &web_measure_json_path($json, $spec->{'path'});
		if (defined $v && !ref $v) { $raw_value = $v; $used = 'path'; }
		else { $result->{'error'} = 'JSON path not found'; }
	}

	# 2. an old JSON id selector, mapped back to a path
	if (!defined $raw_value && ref $json && defined $spec->{'selector'} && $spec->{'selector'} =~ /^\s*\[id\s*=\s*["']?([^"'\]]+)["']?\]\s*$/i) {
		my $id = $1;
		my $path = &web_measure_json_id_path($json, $id);
		if (defined $path) {
			my $v = &web_measure_json_path($json, $path);
			if (defined $v && !ref $v) {
				$raw_value = $v;
				$used = 'path (from id)';
				$result->{'path'} = $path;
			}
		}
	}

	# 3. label then value: the label's own next cell/sibling, or a selector
	# inside the label's row. This survives a reordered page where a global
	# count does not.
	if (!defined $raw_value && $dom && defined $spec->{'label'} && length $spec->{'label'}) {
		my $want = $spec->{'label'};
		my $match_label = sub {
			my $t = &web_measure_clean_text(shift);
			return 0 unless length $t && length $t <= 200;
			if ($want =~ m{^/(.*)/([i]?)$}) { return $t =~ /$1/i ? 1 : 0; }
			return index(lc($t), lc($want)) >= 0 ? 1 : 0;
		};
		my $scope = $dom;
		if (defined $spec->{'container'} && length $spec->{'container'}) {
			my $box = $dom->at($spec->{'container'});
			$scope = $box if $box;
		}
		# all_text, not text: text only returns an element's own text, so a
		# <td><a>Silver</a></td> or <dd><span>2.4</span></dd> would look empty.
		my @labels = $scope->find('td, th, dt, dd, b, strong, span, div, label, h1, h2, h3, h4, h5, h6, p')->each;
		my @picked = grep { $match_label->($_->all_text) } @labels;
		# the tightest match wins: a <dt>Condition:</dt> is the label, not the
		# <dl> that contains it and its value
		@picked = sort { length($a->all_text) <=> length($b->all_text) } @picked;
		my $label_node = $picked[ $spec->{'label_count'} || 0 ];
		my $node;
		if ($label_node) {
			my $value = $spec->{'value'};
			if (defined $value && $value eq 'parent_next') {
				my $p = $label_node->parent;
				$node = $p ? $p->next : undef;
			}
			elsif (defined $value && $value eq 'next') {
				$node = $label_node->next;
			}
			elsif (defined $spec->{'value_selector'} && length $spec->{'value_selector'}) {
				my $scope = $label_node->parent;
				if (defined $spec->{'row'} && length $spec->{'row'}) {
					my $r = $label_node->ancestors($spec->{'row'})->[0];
					$scope = $r if $r;
				}
				my $nodes = $scope ? $scope->find($spec->{'value_selector'}) : Mojo::Collection->new;
				$node = $nodes->[ $spec->{'count'} || 0 ];
			}
			else {
				# a bare label means "the cell or sibling beside it"
				$node = $label_node->next;
			}
		}
		elsif (defined $spec->{'container'} && length $spec->{'container'}) {
			# a label written as bare text (moongiant: "Moon Angle: <span>0.49</span>")
			# has no element to match; walk the container's children instead.
			$node = &web_measure_after_text_label($dom, $spec->{'container'}, $want, $spec->{'label_count'} || 0);
		}
		if ($node) {
			$raw_value = ($attr ne 'text') ? $node->attr($attr) : $node->all_text;
			$used = 'label';
		}
	}

	# 4. HTML row + label + cell (the stable way to read a table)
	if (!defined $raw_value && $dom && defined $spec->{'row'} && length $spec->{'row'}) {
		my @rows = $dom->find($spec->{'row'})->each;
		my @cand;
		my $match = $spec->{'match'};
		foreach my $row (@rows) {
			my $t = &web_measure_clean_text($row->all_text);
			if (defined $match && length $match) {
				if ($match =~ m{^/(.*)/([i]?)$}) { next unless $t =~ /$1/i; }
				else { next unless index(lc($t), lc($match)) >= 0; }
			}
			if (defined $spec->{'contains'} && length $spec->{'contains'}) {
				next unless index(lc($t), lc($spec->{'contains'})) >= 0;
			}
			push @cand, $row;
		}
		my $row = $cand[ $spec->{'row_count'} || 0 ];
		if ($row) {
			my $nodes = (defined $spec->{'within'} && length $spec->{'within'})
				? $row->find($spec->{'within'})
				: Mojo::Collection->new($row);
			my $node = $nodes->[ $spec->{'count'} || 0 ];
			if ($node) {
				$raw_value = ($attr ne 'text') ? $node->attr($attr) : $node->all_text;
				$used = 'row';
			}
		}
	}

	# 5. the classic CSS selector + count. An [id="…"] selector is a JSON id
	# only when there is JSON to read; on an HTML page it is a real selector
	# (tradingeconomics puts prices in <td id="p">).
	if (!defined $raw_value && $dom && defined $spec->{'selector'} && length $spec->{'selector'} && ($spec->{'selector'} !~ /^\s*\[id\s*=/i || !ref $json)) {
		my @nodes = $dom->find($spec->{'selector'})->each;
		if (defined $spec->{'contains'} && length $spec->{'contains'}) {
			@nodes = grep { index(lc(&web_measure_clean_text($_->all_text)), lc($spec->{'contains'})) >= 0 } @nodes;
		}
		my $node;
		if ((defined $spec->{'prev'} && length $spec->{'prev'}) || (defined $spec->{'next'} && length $spec->{'next'})) {
			foreach my $n ( @nodes ) {
				my $p = $n->previous;
				my $q = $n->next;
				my $okp = !defined $spec->{'prev'} || !length $spec->{'prev'} || ($p && index(lc(&web_measure_clean_text($p->all_text)), lc($spec->{'prev'})) >= 0);
				my $okq = !defined $spec->{'next'} || !length $spec->{'next'} || ($q && index(lc(&web_measure_clean_text($q->all_text)), lc($spec->{'next'})) >= 0);
				if ($okp && $okq) { $node = $n; last; }
			}
		}
		$node ||= $nodes[ $spec->{'count'} || 0 ];
		if ($node) {
			$raw_value = ($attr ne 'text') ? $node->attr($attr) : $node->all_text;
			$used = 'selector';
		}
	}

	# 6. named fallbacks
	if (!defined $raw_value && ref $spec->{'fallback'} eq 'ARRAY') {
		foreach my $f ( @{$spec->{'fallback'}} ) {
			next unless ref $f eq 'HASH';
			my $r = &web_measure_extract($f, $ctx);
			return $r if $r->{'ok'};
		}
	}

	unless (defined $raw_value) {
		$result->{'error'} ||= 'no element matched';
		return $result;
	}

	if (defined $spec->{'regex'} && length $spec->{'regex'}) {
		my $re = $spec->{'regex'};
		if ($re =~ m{^/(.*)/([i]?)$}) { $re = $1; }
		if ($raw_value =~ /$re/) { $raw_value = defined $1 ? $1 : $&; }
		else { $result->{'error'} = 'regex did not match'; return $result; }
	}

	$raw_value = &web_measure_clean_text($raw_value);
	if ($spec->{'number'}) {
		my $n = &web_measure_number($raw_value, $spec);
		return { %{$result}, error => 'not a number' } unless defined $n;
		$raw_value = $n;
	}
	return { ok => 1, value => $raw_value, raw => $raw_value, used => $used, error => '', path => $result->{'path'} };
}

# Suggest working specs for a label on this page. The useful shape for a table
# is "the row that contains Gold, cell N", where N is the first cell *after*
# the label. Every candidate is tested against the page before it is offered,
# so a suggestion is a value the extractor will really read.
sub web_measure_suggest {
	my ($ctx, $label) = @_;
	my $dom = $ctx->{'dom'};
	return [] unless $dom && defined $label && length $label;
	my @out;
	my $seen;
	my $add = sub {
		my ($spec, $value) = @_;
		my $key = join '|', map { $_ . '=' . (defined $spec->{$_} ? $spec->{$_} : '') } sort keys %{$spec};
		return if $seen->{$key}++;
		push @out, { spec => $spec, value => $value };
	};
	my $test = sub {
		my ($spec) = @_;
		my $r = &web_measure_extract($spec, $ctx);
		return undef unless $r->{'ok'} && defined $r->{'value'} && length $r->{'value'};
		return &web_measure_clean_text($r->{'value'});
	};

	# the row that holds the label, then the cells after the label's own cell
	my @rows = grep {
		index(lc(&web_measure_clean_text($_->all_text)), lc($label)) >= 0
	} $dom->find('tr')->each;
	foreach my $row ( @rows ) {
		my @cells = $row->find('td, th')->each;
		my $label_idx = -1;
		for my $i ( 0 .. $#cells ) {
			if (index(lc(&web_measure_clean_text($cells[$i]->all_text)), lc($label)) >= 0) { $label_idx = $i; last; }
		}
		next if $label_idx < 0;
		for my $j ( $label_idx + 1 .. $#cells ) {
			my $txt = &web_measure_clean_text($cells[$j]->all_text);
			next unless length $txt;
			my $spec = { row => 'tr', match => $label, within => 'td, th', count => $j };
			my $v = $test->($spec);
			$add->($spec, $v) if defined $v;
		}
		foreach my $sel ( '[data-testid="change"]', '.price', '.value', 'span', 'b', 'strong' ) {
			my $spec = { row => 'tr', match => $label, within => $sel, count => 0 };
			my $v = $test->($spec);
			$add->($spec, $v) if defined $v;
		}
		last if scalar @out >= 4;
	}

	# definition-list / label-and-next shapes
	foreach my $spec ( { label => $label, value => 'next' }, { label => $label, value => 'parent_next' } ) {
		my $v = $test->($spec);
		$add->($spec, $v) if defined $v;
	}

	# a label written as bare text inside a container that has an id
	# (moongiant: "Moon Angle: <span>0.49</span>")
	my $scanned = 0;
	foreach my $box ( $dom->find('[id]')->each ) {
		last if scalar @out >= 4 || $scanned++ >= 200;
		my $kids = $box->children;
		next if scalar @{$kids} > 100;
		my $html = $box->to_string;
		foreach my $child ( @{$kids} ) {
			next unless $child->type eq 'tag';
			next if ($child->tag || '') =~ /^(?:br|hr|wbr)$/i;
			my $markup = $child->to_string;
			my $at = index($html, $markup);
			next if $at <= 0;
			my ($tail) = substr($html, 0, $at) =~ /([^<>]*)$/;
			$tail = &web_measure_clean_text($tail);
			next unless $tail =~ /([A-Za-z][A-Za-z0-9 .\/#%()+_-]{0,40}:)\s*$/;
			my $near = $1;
			next unless index(lc($near), lc($label)) >= 0;
			my $spec = { container => '#' . $box->attr('id'), label => $near };
			my $v = $test->($spec);
			$add->($spec, $v) if defined $v;
			last if scalar @out >= 4;
		}
	}
	return \@out;
}

# Build the specs a person can choose after clicking a value in the web view:
# a JSON path, a table row, a label/value pair, or - last - the old CSS
# selector + count. Every candidate is run through the extractor, so the list
# only contains shapes that really read this page.
sub web_measure_candidates {
	my ($dom, $json, $selector, $index) = @_;
	return [] unless $dom;
	$index = 0 unless defined $index && $index =~ /^\d+$/;
	my $ctx = { dom => $dom, json => $json, format => (ref $json ? 'json' : 'html') };
	my @out;
	my %seen;
	my $add = sub {
		my ($kind, $spec) = @_;
		return unless ref $spec eq 'HASH';
		my $r = &web_measure_extract($spec, $ctx);
		return unless $r->{'ok'} && defined $r->{'value'} && length $r->{'value'};
		my $key = encode_json($spec);
		return if $seen{$key}++;
		push @out, { kind => $kind, spec => $spec, value => &web_measure_clean_text($r->{'value'}) };
	};

	my @found;
	if (defined $selector && length $selector) {
		my $nodes = eval { $dom->find($selector) };
		@found = $nodes ? $nodes->each : ();
	}
	my $el = $found[$index] || $found[0];

	# 1. the JSON prettyfier puts the concatenated keys in the value span's id
	if (ref $json && $el) {
		my $id = $el->attr('id');
		unless (defined $id && length $id) {
			my $span = $el->ancestors('span[id]')->[0];
			$id = $span->attr('id') if $span;
		}
		if (defined $id && length $id) {
			my $path = &web_measure_json_id_path($json, $id);
			$add->('JSON path', { path => $path }) if defined $path && length $path;
		}
	}

	# 2. the table row and the cell inside it
	my $row = $el ? ($el->tag eq 'tr' ? $el : $el->ancestors('tr')->[0]) : undef;
	my $cell = $el;
	while ($cell && ($cell->tag || '') !~ /^(?:td|th)$/i) { $cell = $cell->parent; }
	if ($row && $cell) {
		my @cells = $row->find('td, th')->each;
		my $cell_index = 0;
		my $s = $cell->previous;
		while ($s) {
			$cell_index++ if $s->type eq 'tag' && ($s->tag || '') =~ /^(?:td|th)$/i;
			$s = $s->previous;
		}
		my $label = @cells ? &web_measure_clean_text($cells[0]->all_text) : '';
		$label = substr($label, 0, 80);
		if (length $label && $label !~ /^[\d.,+\-%\s]+$/) {
			my $row_count = 0;
			foreach my $r ( $dom->find($row->tag)->each ) {
				last if $r->to_string eq $row->to_string;
				$row_count++ if index(lc(&web_measure_clean_text($r->all_text)), lc($label)) >= 0;
			}
			my $tag = $cell->tag;
			my $within = $tag;
			my $count = 0;
			if (my $testid = $cell->attr('data-testid-cell')) {
				$within = $tag . '[data-testid-cell="' . $testid . '"]';
			}
			elsif (my $cid = $cell->attr('id')) {
				$within = $tag . '[id="' . $cid . '"]';
			}
			else {
				$within = 'td, th';
				$count = $cell_index;
			}
			my $spec = { row => $row->tag, match => $label, within => $within, count => $count };
			$spec->{'row_count'} = $row_count if $row_count;
			$add->('table row', $spec);
			$add->('table row', { row => $row->tag, match => $label, within => 'td, th', count => $cell_index }) if $within ne 'td, th';
		}
	}

	# 3. a definition list: <dt>Label:</dt><dd>value</dd>
	if ($el) {
		my $dd = $el;
		while ($dd && ($dd->tag || '') ne 'dd') { $dd = $dd->parent; }
		if ($dd) {
			my $dt = $dd->previous;
			if ($dt && ($dt->tag || '') eq 'dt') {
				my $label = &web_measure_clean_text($dt->all_text);
				$add->('label', { label => $label, value => 'next' }) if length $label;
			}
		}
	}

	# 4. a label written as bare text in a container that has an id
	if ($el && $el->parent) {
		my $parent = $el->parent;
		my $cid = $parent->attr('id');
		if (defined $cid && length $cid) {
			my $html = $parent->to_string;
			my $markup = $el->to_string;
			my $at = index($html, $markup);
			if ($at > 0) {
				my $before = substr($html, 0, $at);
				my ($tail) = $before =~ /([^<>]*)$/;
				$tail = &web_measure_clean_text($tail);
				if ($tail =~ /([A-Za-z][A-Za-z0-9 .\/#%()+_-]{0,40}:?)\s*$/) {
					my $label = $1;
					$add->('label', { container => '#' . $cid, label => $label });
				}
			}
		}
	}

	# 5. the old selector + count, always available as a fallback
	if (defined $selector && length $selector) {
		$add->('selector', { selector => $selector, count => $index });
	}

	return \@out;
}

# app/setting rows, with the local device preferred but a row stored on another
# device still visible. A web measure is an app fact, not a device fact: the
# phone can be the headless browser and still use the selectors configured on
# the computer. Dedupe by $by when a setting has one row per subsetting.
sub setting_rows_for {
	my ($app, $setting, $by) = @_;
	my $dev = &device_setter();
	my $sig = &signatorial_designer();
	my $rows = &db_query(q{
		select * from settings
		where app = ? and setting = ?
		order by case when device = ? or device = ? or device = 'all' or device is null then 0 else 1 end,
		         cast(server_time as integer) desc
	}, $app, $setting, $dev, $sig)->hashes || [];
	if ($by) {
		my %seen;
		@{$rows} = grep { !$seen{ defined $_->{$by} ? $_->{$by} : '' }++ } @{$rows};
	}
	return $rows;
}

sub setting_value_for {
	my ($app, $setting) = @_;
	my $rows = &setting_rows_for($app, $setting);
	return $rows->[0] ? $rows->[0]->{'value'} : undef;
}

sub headless_browser() {
	my $changes = 0;
	my $signatorial = &subs::signatorial_designer();
	# A web measure is an app fact, not a device fact. Read the recurrence and
	# URL regardless of the device that configured them; the local row wins when
	# there is more than one. This is what lets the phone be the headless browser
	# while the selectors remain on the computer.
	my $apps = &subs::db_query(q{select distinct app from settings where setting = ? and app is not null and value is not null and value != ?}, 'web_recurring', '')->hashes || [];
	foreach my $a ( @{$apps} ) {
		my $app = $a->{'app'};
		next unless defined $app && length $app;
		my $rw = &subs::setting_rows_for($app, 'web_recurring')->[0] or next;
		# The newest choice wins. A machine keeps its own row and may also see a
		# peer's, so an old row saying "mobile" would keep a phone fetching after
		# the app was moved to the server. Read the newest row, not any row.
		my ($wd) = sort { ($b->{'server_time'} || 0) <=> ($a->{'server_time'} || 0) }
			grep { defined $_->{'value'} && length $_->{'value'} }
			@{ &subs::setting_rows_for($app, 'web_headless_device') };
		next unless $wd;
		my $headless_for = $wd->{'value'};
		next unless $headless_for eq $device || $headless_for eq $signatorial || $headless_for eq 'all';
		# One URL per app, and the newest configuration wins. These rows are per
		# device, so an older machine can still carry a URL the app has moved on
		# from; fetching every row pulled two feeds (a JSON API and its retired
		# HTML page) at once. The history a fetch leaves behind is keyed by URL,
		# so a second URL also kept resetting the first one's last_run.
		my ($w) = sort { ($b->{'server_time'} || 0) <=> ($a->{'server_time'} || 0) }
			grep { defined $_->{'value'} && length $_->{'value'} }
			@{ &subs::setting_rows_for($app, 'web') };
		next unless $w;
		my $url = $w->{'value'};
		my $history = &subs::db_query('select * from websites where app=? and url=? order by timestamp desc', $app, $url)->hashes;
		my $last_run = $history->[0] ? $history->[0]->{'timestamp'} : 0;
		my $recurrence = &time_abbrev_translator($rw->{'value'}) || '1M';
		next unless &subs::rightNow() - $last_run > $recurrence;
		my ($window,$internal_url,$uuid,$timestamp) = &Manager::website_grabber({
			app => $app,
			website => $url,
			timestamp => &subs::rightNow(),
			user_agent => $gb::user_agent,
		});
		$changes = 1;
	}
	if ($changes == 1) {
		my $c = &subs::controller_builder();
		my $update = $c->render_to_string(
			template => 'web',
			app => ''
		);
		&Websocket::send('tab', { type => 'replaceWith', selector => '#web', content => $update });


	}
}

sub telephone_contacts_check() {

	return 0 unless $device eq 'mobile';

	my $n = 0;
	my $jcontacts = `termux-contact-list`;
	my $contacts = eval { return decode_json $jcontacts } || [];
	foreach my $contact ( @{$contacts} ) {
		my $name = &subs::unformat_name($contact->{'name'});
		my $number = $contact->{'number'};
		$number =~ s/\D+//gi;

		next unless $number;

		my $phones = &subs::settings_grabber({ app => $name, settings => ['phone', 'phones', 'uuid' ] });

		# only a person the house already knows: a contact never mints an app
		next unless $phones->{'uuid'};
		next if &subs::contact_matches('phone', $phones->{'phone'}, $number);

		# another number for somebody whose line is already set is another line on
		# them, not a replacement: the phone row keeps what call and text route on,
		# and the typed list holds the rest (mobile, home, work, a custom label).
		if (!$phones->{'phone'}) {
			&subs::setting_setter({ app => $name, setting => 'phone', value => $number });
			$n++;
			next;
		}
		my $list = eval { return decode_json $phones->{'phones'} } || [];
		$list = [ $list ] if ref $list eq 'HASH';
		$list = [] unless ref $list eq 'ARRAY';
		next if grep { ref $_ eq 'HASH' && &subs::contact_matches('phone', $_->{'value'}, $number) } @{$list};
		push @{$list}, {
			uuid => &subs::random_string_creator(20),
			type => 'mobile',
			label => '',
			value => $number
		};
		&subs::setting_setter({ app => $name, setting => 'phones', value => encode_json $list });
		$n++;
	}
	return $n;
}

# The contacts of one kind a person keeps: the plain setting (phone/email) and
# the typed list beside it (phones/emails, rows of {type,label,value}). Comparison
# tidies the way the rest of the code does - a phone to its digits (a leading 1
# dropped) so a country code or spacing never hides a match, an email lowered.
sub contact_normalizer {
	my ($kind, $value) = @_;
	return '' unless defined $value && length $value;
	if ($kind eq 'phone') {
		my $n = $value;
		$n =~ s/\D+//g;
		$n =~ s/^1//;
		return $n;
	}
	my $e = lc $value;
	$e =~ s/^\s+//;
	$e =~ s/\s+$//;
	return $e;
}

sub contact_matches {
	my ($kind, $a, $b) = @_;
	my $x = &subs::contact_normalizer($kind, $a);
	my $y = &subs::contact_normalizer($kind, $b);
	return 0 unless length $x && length $y;
	if ($kind eq 'phone') {
		$x = substr $x, -10 if length $x >= 10;
		$y = substr $y, -10 if length $y >= 10;
	}
	return $x eq $y ? 1 : 0;
}

# Every app whose records hold this phone or email: the plain setting first
# (phone/email), then the typed list (phones/emails). A match is the address, so
# the two are scanned the same way - a number kept as somebody's work line names
# them as surely as the one on the app.
sub contact_apps {
	my ($kind, $value) = @_;
	return () unless defined $value && length $value;
	my (%seen, @apps);
	my $plain = &subs::db_query('select app, value from settings where setting=? and value != ?', $kind, '')->hashes;
	foreach my $r ( @{$plain} ) {
		next unless &subs::contact_matches($kind, $r->{'value'}, $value);
		push @apps, $r->{'app'} unless $seen{ $r->{'app'} }++;
	}
	my $rows = &subs::db_query('select app, value from settings where setting=? and value != ?', $kind . 's', '')->hashes;
	foreach my $r ( @{$rows} ) {
		my $list = eval { return decode_json $r->{'value'} } || [];
		$list = [ $list ] if ref $list eq 'HASH';
		next unless ref $list eq 'ARRAY';
		foreach my $c ( @{$list} ) {
			next unless ref $c eq 'HASH';
			next unless &subs::contact_matches($kind, $c->{'value'}, $value);
			push @apps, $r->{'app'} unless $seen{ $r->{'app'} }++;
		}
	}
	return @apps;
}

# Every line the house holds of one kind, one app's under it: the plain setting
# (phone/email) first and marked primary, then the typed list (phones/emails) with
# its type and label. A person with a home and a work line is one entry with all
# of them, not one per number - which is what the Phone app's directory and
# Chat's friends both want. Pass $only_app to read just one person's lines.
sub contact_lines {
	my ($kind, $only_app) = @_;
	my $mine = (defined $only_app && length $only_app) ? $only_app : undef;
	my %lines;
	my $plain = &subs::db_query('select app, value, server_time from settings where setting=? and value != ? order by server_time desc', $kind, '')->hashes;
	foreach my $r ( @{$plain} ) {
		my $app = $r->{'app'};
		next if $mine && $app ne $mine;
		next if exists $lines{$app};
		my $v = $r->{'value'};
		next unless defined $v && length $v;
		$lines{$app} = [ { value => $v, type => '', label => '', primary => 1 } ];
	}
	my $lists = &subs::db_query('select app, value from settings where setting=? and value != ?', $kind . 's', '')->hashes;
	foreach my $r ( @{$lists} ) {
		my $app = $r->{'app'};
		next if $mine && $app ne $mine;
		my $list = eval { return decode_json $r->{'value'} } || [];
		$list = [ $list ] if ref $list eq 'HASH';
		next unless ref $list eq 'ARRAY';
		$lines{$app} ||= [];
		my %seen = map { &subs::contact_normalizer($kind, $_->{'value'}) => 1 } @{ $lines{$app} };
		foreach my $c ( @{$list} ) {
			next unless ref $c eq 'HASH';
			my $v = $c->{'value'};
			next unless defined $v && length $v;
			my $key = &subs::contact_normalizer($kind, $v);
			next if $key && $seen{$key}++;
			push @{ $lines{$app} }, { value => $v, type => ($c->{'type'} || ''), label => ($c->{'label'} || ''), primary => 0 };
		}
	}
	return \%lines;
}

# How one line reads in a list: the number or address, and - for a line beyond
# the first - its type in front of it (a custom entry wears its own label). A
# blocked line says so.
sub contact_line_label {
	my $l = shift;
	my $text = $l->{'value'};
	my $type = $l->{'type'} || '';
	my $label = $l->{'label'} || '';
	my $name = ($type eq 'custom' && length $label) ? $label : $type;
	$text = $name . ' ' . $text if length $name && !$l->{'primary'};
	$text .= ' (blocked)' if $l->{'blocked'};
	return $text;
}

# The app a number belongs to: the person who saved it, or - when the house
# does not know the number - the number itself, filed as an app of its own so
# a stranger's calls and texts still land somewhere, and naming that app later
# turns the stranger into a person. The phone row is made at the same time, so
# the next call or text from the same number resolves the same way. Matching is
# on the last ten digits of both sides, the way the call-log check learned to,
# and covers the typed list as well as the plain phone row.
sub phone_number_app {
	my $number = shift;
	$number =~ s/\D+//g;
	$number =~ s/^1//;
	return '' unless $number;
	my @known = &subs::contact_apps('phone', $number);
	return $known[0] if scalar @known;
	# unknown: the number becomes the app, and the row makes it known
	&subs::setting_setter({ app => $number, setting => 'phone', value => $number });
	return $number;
}

sub telephone_call_log_check() {

	return 0 unless $device eq 'mobile';

	my $n = 0;
	my $call_logs = `termux-call-log -l 30`;
	my $calls = eval { return decode_json $call_logs } || [];

	foreach my $call ( grep { $_->{'phone_number'} =~ /\d/ } @{$calls} ) {
		my $name = &subs::unformat_name($call->{'name'});
		my $number = $call->{'phone_number'};
		$number =~ s/\D+//gi;
		my $timestamp = &subs::ago_calc($call->{'date'},&subs::rightNow());

		my @duration = split /:/, $call->{'duration'};


		my $duration = '';
		if (scalar @duration == 3) {
			$duration .= $duration[0] . 'h ';
			$duration .= $duration[1] . 'm ';
			$duration .= $duration[2] . 's';
		}
		else {
			$duration .= $duration[0] . 'm ';
			$duration .= $duration[1] . 's';
		}
		$duration = &subs::time_abbrev_translator($duration);


		# the log carries the number in whatever shape the carrier sent it (+1…,
		# bare digits, sometimes with the country code) while the house keeps its
		# contacts as they were typed (519-849-5604, 2263493283, the odd +1…).
		# Match on the last ten digits of both: a raw substring test meant a
		# contact stored without the country code (or with dashes) never met its
		# own call - which is why a working termux-call-log still filed nothing.
		# (the matching itself lives in phone_number_app)
		# an unknown caller is still a call: file it on the number's own app
		# (the number becomes the app), rather than dropping it on the floor
		my $app = &subs::phone_number_app($number) || 'phone';

		# the live phone app may already have written this call as it happened
		# (window.JawnPhoneEvent): skip it so a live call and its call-log trail
		# are one appointment, not two
		my $live = &subs::db_query('select uuid from appointments where subtype=? and timestamp between ? and ? limit 1', 'phone', $timestamp - 180000, $timestamp + 180000)->hashes;
		next if scalar @{$live} > 0;

		my $appts = &subs::db_query('select * from appointments where app=? and timestamp = ?', $app, $timestamp)->hashes;
		unless (scalar @{$appts} > 0) {
			my $data = {
				app => $app,
				type => 'start',
				duration => '-' . $duration,
				timestamp => $timestamp,
				stop_timestamp => ($timestamp + $duration),
				seen => 'yes',
				subtype => 'phone'
			};

			my $c = &subs::controller_builder();
			&Manager::appointment_writer($c,$data);
			$n++;
		}
	}
	return $n;
}

sub appt_toggle_checker() {
	my $app = shift;
	return unless $app;
	my $server_time = &subs::rightNow();
	my $toggle = 'off';
	# An open row is a running session, however long it has run. The configured
	# duration is only a guess - a real session can be much longer - so elapsed
	# time must never turn an appointment off by itself. Doing that made a place
	# whose session outlived its estimate look stopped: navigation then started a
	# fresh session on every tick while the old one was still open.
	my $open = &subs::db_query('select timestamp from appointments where app=? and (type=? or type=?) and stop_seen is null and timestamp <= ? order by timestamp desc limit 1', $app, 'start', 'record', $server_time)->hashes->[0];
	$toggle = 'on' if $open;
	# rewriting an unchanged toggle cost two writes and a websocket message on
	# every header render
	my $current = &subs::setting_grabber({ app => $app, setting => 'toggle' });
	&subs::setting_setter({ app => $app, setting => 'toggle', value => $toggle }) unless defined $current && $current eq $toggle;
	return $toggle;
}

# ---- warehouse / inventory helpers -----------------------------------------

# Where are we right now? navigation_automation starts a place when GPS says we
# are in it, which shows up as its 'toggle' being on. A device without GPS
# (laptop/desktop) can't do that, so we fall back to whichever running place is
# flagged with inventory ability.
sub current_place() {
	my $q = &db_query('select app from settings where setting=? and value=?', 'toggle', 'on');
	my $toggled = $q ? $q->hashes : [];
	my ($inventory, $fallback);
	foreach my $t ( @{$toggled} ) {
		my $app = $t->{'app'};
		my $pin = &db_query('select app from settings where app=? and (setting=? or setting=?) and value=? limit 1', $app, 'pos', 'mab', 'place');
		next unless ($pin && $pin->hashes->[0]);
		$fallback = $app unless $fallback;
		my $inv = &setting_grabber({ app => $app, setting => 'inventory_ability' });
		$inventory = $app if $inv && $inv eq 'on';
	}
	return $inventory || $fallback || '';
}

# What an item has on hand right now: its signed stock rows summed per unit, the
# same figure the warehouse Levels view shows. A money row (it names an account)
# and a balance anchor (kind inventory) are not stock and are left out, the way
# warehouse_grabber reads them.
sub warehouse_stock_for {
	my ($item) = @_;
	return {} unless $item && $item ne '';
	my $rows = &db_query('select quantity, unit, kind, type, account from warehouse where item = ?', $item);
	my %stock;
	foreach my $r ( @{ $rows ? $rows->hashes : [] } ) {
		my $kind = $r->{'kind'};
		$kind = ($r->{'type'} eq 'inventory' ? 'inventory' : (($r->{'account'} && $r->{'account'} ne '') ? 'money' : 'stock')) if !defined $kind || $kind eq '';
		next unless $kind eq 'stock';
		my $unit = $r->{'unit'} || 'each';
		$stock{$unit} += &numeric_formatter($r->{'quantity'}) + 0;
	}
	return \%stock;
}

# What an item has on hand, in the unit its own app names (its `unit` setting),
# else its sole unit - what a fixed-level quantity budget reads. Zero when nothing
# of it is stocked.
sub warehouse_on_hand {
	my ($item, $settings) = @_;
	my $stock = &warehouse_stock_for($item);
	my $unit = $settings && $settings->{'unit'};
	return $stock->{$unit} + 0 if $unit && defined $stock->{$unit};
	my @units = grep { defined $stock->{$_} } keys %{$stock};
	return 0 unless scalar @units == 1;
	return $stock->{$units[0]} + 0;
}

# How to reach a stock target from what is on hand now, in whole packages where
# the item names them: a shortfall of four covered by a six-pack reads "buy one
# six-pack". The smallest pack that covers the shortfall is bought once; when no
# pack covers it the biggest is repeated; with no packaging at all the bare
# shortfall is the answer.
sub warehouse_restock_for {
	my ($item, $target) = @_;
	my $settings = &settings_grabber({ app => $item });
	my $on_hand = &warehouse_on_hand($item, $settings);
	my $short = ($target || 0) - $on_hand;
	my $plan = { item => $item, on_hand => $on_hand, target => ($target || 0), short => ($short > 0 ? $short : 0), buy => undef };
	return $plan unless $short > 0;
	my $packaging = eval { return decode_json &setting_grabber({ app => $item, setting => 'app_packaging' }) }
		|| eval { return decode_json &setting_grabber({ app => $item, setting => 'packaging' }) }
		|| {};
	my @packs = sort { $a->{'quantity'} <=> $b->{'quantity'} }
		map { { name => $packaging->{$_}->{'name'}, quantity => ($packaging->{$_}->{'quantity'} + 0) } }
		grep { ref $packaging->{$_} eq 'HASH' && ($packaging->{$_}->{'quantity'} || '') =~ /[0-9]/ }
		keys %{$packaging};
	my ($covers) = grep { $_->{'quantity'} >= $short } @packs;
	if ($covers) {
		$plan->{'buy'} = { %{$covers}, count => 1, units => $covers->{'quantity'} };
	}
	elsif (scalar @packs) {
		my $pack = $packs[-1];
		my $count = int(( $short + $pack->{'quantity'} - 1 ) / $pack->{'quantity'});
		$plan->{'buy'} = { %{$pack}, count => $count, units => $count * $pack->{'quantity'} };
	}
	else {
		$plan->{'buy'} = { name => 'each', quantity => 1, count => $short, units => $short };
	}
	return $plan;
}

# The shelf life (e.g. '3w') declared on an item's packaging, if any.
sub warehouse_item_expires {
	my $item = shift;
	my $packaging = eval { return decode_json &setting_grabber({ app => $item, setting => 'packaging' }) } || {};
	foreach my $p ( values %{$packaging} ) {
		next unless ref $p eq 'HASH';
		my $exp = $p->{'expires'};
		return $exp if $exp && $exp ne '';
	}
	return '';
}

# Where does an item live? Most specific first: an explicit 'place' setting on
# the item, a 'default_place' on the item's packaging, a 'place' setting on the
# app, the app itself when it is a place (pos=place), and finally wherever we
# currently are. Returns '' when nothing resolves, and callers treat that as
# "do not touch stock".
sub warehouse_place_for {
	my ($app,$item) = @_;
	foreach my $subject ( $item, $app ) {
		next unless $subject;
		my $q = &db_query('select value from settings where app=? and setting=? limit 1', $subject, 'place');
		my $s = $q ? $q->hashes->[0] : undef;
		return $s->{'value'} if $s->{'value'} && $s->{'value'} ne '';
	}
	if ($item) {
		my $packaging = eval { return decode_json &setting_grabber({ app => $item, setting => 'packaging' }) } || {};
		foreach my $p ( values %{$packaging} ) {
			next unless ref $p eq 'HASH';
			return $p->{'default_place'} if $p->{'default_place'} && $p->{'default_place'} ne '';
		}
	}
	if ($app) {
		my $q = &db_query('select value from settings where app=? and setting=? and value=? limit 1', $app, 'pos', 'place');
		return $app if ($q && $q->hashes->[0]);
	}
	return &current_place();
}

# The journal metadata stored in a warehouse row's data column: why the stock
# moved, what app it came from, and the uuid of the document that caused it.
sub warehouse_journal_entry {
	my $d = shift;
	return encode_json {
		reason => $d->{'reason'},
		source => $d->{'source'},
		source_uuid => $d->{'source_uuid'}
	};
}

# Record a stock movement. Positive quantity puts stock in, negative takes it
# out. Only called once a place is known, so stock never lands unplaced.
sub warehouse_movement {
	my $d = shift;
	my $item = $d->{'item'};
	my $quantity = &numeric_formatter($d->{'quantity'}) + 0;
	return unless $item && $quantity != 0;
	my $wdata = {
		timestamp => $d->{'timestamp'} || &rightNow(),
		server_time => &rightNow(),
		item => $item,
		model => $d->{'model'},
		options => $d->{'options'},
		uuid => &random_string_creator(40),
		quantity => $quantity,
		unit => $d->{'unit'} || 'each',
		place => $d->{'place'},
		# the warehouse has three faces now; this writer only ever moves stock
		kind => $d->{'kind'} || 'stock',
		type => $d->{'type'} || 'stock',
		account => $d->{'account'},
		project => $d->{'project'},
		warranty => $d->{'warranty'},
		app_uuid => $d->{'app_uuid'},
		data => &warehouse_journal_entry($d)
	};
	&db_insert('warehouse', $wdata);
	return $wdata;
}

# FIFO-walk the stock and write off whatever has outlived its packaging shelf
# life. Runs on a timer (see President.pl). Each write-off references the lot it
# expired via app_uuid, and since the write-off is itself a negative movement,
# the next pass consumes that lot and won't expire it twice.
sub warehouse_expiry_sweep() {
	my $now = &rightNow();
	my $q = &db_query('select * from warehouse where item is not null and item != ? and place is not null and place != ? order by timestamp asc', '', '');
	my $rows = $q ? $q->hashes : [];
	my %lots;
	foreach my $r ( @{$rows} ) {
		my $unit = $r->{'unit'} || 'each';
		my $types = $gb::measures->{$unit}->{'types'} || [];
		next if ($r->{'account'} && $r->{'account'} ne '') || (grep { $_ eq 'currency' } @{$types});
		my $qty = &numeric_formatter($r->{'quantity'}) + 0;
		next if $qty == 0;
		my $key = $r->{'place'} . "\0" . $r->{'item'};
		my $queue = $lots{$key} ||= [];
		if ($qty > 0) {
			push @{$queue}, { uuid => $r->{'uuid'}, ts => &numeric_formatter($r->{'timestamp'}) + 0, remaining => $qty, row => $r };
		}
		else {
			my $need = -$qty;
			foreach my $lot ( @{$queue} ) {
				last if $need <= 0;
				next if $lot->{'remaining'} <= 0;
				my $take = $lot->{'remaining'} < $need ? $lot->{'remaining'} : $need;
				$lot->{'remaining'} -= $take;
				$need -= $take;
			}
		}
	}
	my $written = 0;
	foreach my $key ( keys %lots ) {
		my ($place,$item) = split /\0/, $key;
		my $expires = &warehouse_item_expires($item);
		next unless $expires;
		foreach my $lot ( @{$lots{$key}} ) {
			next unless $lot->{'remaining'} > 0;
			my $expiry = eval { &ago_calc('-' . $expires, $lot->{'ts'}) } || 0;
			next unless $expiry && $now > $expiry;
			my $src = $lot->{'row'};
			&warehouse_movement({
				item => $item,
				quantity => $lot->{'remaining'} * -1,
				unit => $src->{'unit'},
				place => $place,
				model => $src->{'model'},
				account => $src->{'account'},
				project => $src->{'project'},
				warranty => $src->{'warranty'},
				timestamp => $now,
				app_uuid => $lot->{'uuid'},
				type => 'expiry',
				reason => 'expired',
				source => $place,
				source_uuid => $lot->{'uuid'}
			});
			$lot->{'remaining'} = 0;
			$written++;
		}
	}
	return $written;
}

