sub crypto_fiat_table { return [ map { { %{$_} } } @crypto_fiat_table ] }
sub crypto_fiat_codes { return [ map { $_->{'code'} } @crypto_fiat_table ] }
sub crypto_fiat {
	my ($code) = @_;
	return undef unless defined $code && length $code;
	$code = uc $code;
	foreach my $f ( @crypto_fiat_table ) { return { %{$f} } if $f->{'code'} eq $code; }
	return undef;
}

sub crypto_assets {
	return [ map { { %{$_} } } @crypto_asset_list ];
}

sub crypto_asset {
	my ($code) = @_;
	return undef unless defined $code && length $code;
	$code = uc $code;
	foreach my $a ( @crypto_asset_list ) {
		return { %{$a} } if $a->{'code'} eq $code;
	}
	return undef;
}

sub crypto_enabled {
	my $v = &setting_grabber({ app => 'crypto', setting => 'enabled', device => 'all' });
	return 0 if defined $v && $v eq 'off';
	return 1;
}

sub crypto_enabled_assets {
	my $raw = &setting_grabber({ app => 'crypto', setting => 'assets', device => 'all' });
	my $list = eval { decode_json($raw) };
	$list = [] unless ref $list eq 'ARRAY';
	my %known = map { $_->{'code'} => 1 } @crypto_asset_list;
	$list = [ 'BTC', 'ETH', 'USDC', 'USDT' ] unless scalar @{$list};
	my @out = grep { $known{$_} } map { uc $_ } @{$list};
	return @out ? \@out : [ 'BTC', 'ETH', 'USDC', 'USDT' ];
}

# The house's reporting currency: the one the ledger, budgets and statements
# already speak. misc/currency can arrive as a JSON list, so read the first
# three-letter code from it.
sub crypto_report_currency {
	my $c = &setting_grabber({ app => 'misc', setting => 'currency', benign => 1 });
	$c = '' unless defined $c;
	$c =~ s/[^A-Za-z]//g;
	$c = uc substr($c, 0, 3);
	return $c =~ /^[A-Z]{3}$/ ? $c : 'CAD';
}

# The coin an account holds, or '' when it is not a wallet. The asset setting is
# what names it; an older wallet with only the tender set is Bitcoin, so a row
# never becomes unreadable.
sub crypto_account_asset {
	my ($app) = @_;
	return '' unless defined $app && length $app;
	my $tender = &setting_grabber({ app => $app, setting => 'payment_type' });
	return '' unless defined $tender && lc($tender) eq 'crypto';
	my $asset = &crypto_asset(&setting_grabber({ app => $app, setting => 'crypto_asset' }));
	$asset ||= &crypto_asset('BTC');
	return $asset->{'code'};
}

sub crypto_accounts {
	my $rows = &db_query("select distinct app from settings where setting = 'payment_type' and lower(value) = 'crypto' order by app")->hashes;
	my @out;
	foreach my $r ( @{$rows} ) {
		my $s = &settings_grabber({ app => $r->{'app'}, settings => [ qw/crypto_asset crypto_network wallet_address wallet_label currency/ ] });
		my $asset = &crypto_asset($s->{'crypto_asset'}) || &crypto_asset('BTC');
		my $xpub = &crypto_wallet_setting($r->{'app'}, 'wallet_xpub') || '';
		my $static_address = &crypto_wallet_setting($r->{'app'}, 'wallet_address') || '';
		push @out, {
			app => $r->{'app'},
			formatted_name => &format_name($r->{'app'}),
			asset => $asset->{'code'},
			asset_name => $asset->{'name'},
			decimals => $asset->{'decimals'},
			network => $s->{'crypto_network'} || $asset->{'network'},
			address => $static_address,
			label => $s->{'wallet_label'} || '',
			xpub => $xpub,
			per_invoice => ($xpub ne '' && $asset->{'code'} eq 'BTC') ? 1 : 0,
			currency => $s->{'currency'} || &crypto_report_currency(),
		};
	}
	return \@out;
}

# A typed amount becomes a plain decimal string, never a float: 18-decimal coins
# would lose their last places on the way through a Perl number. Commas are
# thousands separators (the same rule numeric_formatter uses) and only the last
# dot is a decimal point.
sub crypto_amount_number {
	my ($text, $asset) = @_;
	return undef unless defined $text;
	my $a = ref $asset eq 'HASH' ? $asset : &crypto_asset($asset);
	my $decimals = $a ? $a->{'decimals'} : 8;
	$text = "$text";
	$text = Text::Unidecode::unidecode($text) if $text =~ /[^\x00-\x7F]/;
	$text =~ s/[^0-9.,\-]//g;
	my $negative = $text =~ /-/ ? 1 : 0;
	$text =~ s/-//g;
	$text =~ s/,//g;
	$text =~ s/\.(?=.*\.)//g;
	$text = '0' if $text eq '' || $text eq '.';
	return undef unless $text =~ /^\d+(?:\.\d+)?$/;
	my ($int, $frac) = split /\./, $text, 2;
	$frac = '' unless defined $frac;
	$int =~ s/^0+(?=\d)//;
	$frac = substr($frac, 0, $decimals) if $decimals >= 0;
	$frac =~ s/0+$//;
	my $out = length $frac ? "$int.$frac" : $int;
	$out = "-$out" if $negative && $out ne '0';
	return $out;
}

# Display form: the coin's own decimals, trimmed, with at least two places so a
# small amount still reads as money rather than a bare integer.
sub crypto_amount_format {
	my ($amount, $asset) = @_;
	my $a = ref $asset eq 'HASH' ? $asset : &crypto_asset($asset);
	my $code = $a ? $a->{'code'} : (defined $asset && length $asset ? uc $asset : '');
	my $decimals = $a ? $a->{'decimals'} : 8;
	my $n = defined $amount ? "$amount" : '0';
	my $negative = $n =~ /^-/ ? 1 : 0;
	$n =~ s/^-//;
	$n =~ s/[^0-9.]//g;
	my ($int, $frac) = split /\./, $n, 2;
	$int = '0' unless defined $int && length $int;
	$frac = '' unless defined $frac;
	my $cap = $decimals > 8 ? 8 : $decimals;
	$frac = substr($frac, 0, $cap);
	$frac =~ s/0+$//;
	$frac .= ('0' x (2 - length $frac)) if length $frac < 2;
	my $out = ($negative ? '-' : '') . $int . '.' . $frac;
	return length $code ? "$out $code" : $out;
}

# A seed phrase pasted into an address field is refused before it is stored.
sub crypto_looks_like_secret {
	my ($text) = @_;
	return 0 unless defined $text && length $text;
	my $t = lc $text;
	return 1 if $t =~ /\b(seed phrase|mnemonic|private key|recovery phrase)\b/;
	my @words = grep { length } split /\s+/, $t;
	my $count = scalar @words;
	return 1 if ($count == 12 || $count == 15 || $count == 18 || $count == 21 || $count == 24)
		&& !grep { /[^a-z]/ } @words;
	return 0;
}

sub crypto_address_valid {
	my ($asset, $address) = @_;
	my $a = ref $asset eq 'HASH' ? $asset : &crypto_asset($asset);
	return 0 unless $a;
	my $s = defined $address ? $address : '';
	$s =~ s/\s+//g;
	return 0 unless length $s;
	my $net = lc($a->{'network'} || '');
	return $s =~ /^(bc1[02-9ac-hj-np-z]{11,71}|[13][1-9A-HJ-NP-Za-km-z]{25,34})$/ ? 1 : 0 if $a->{'code'} eq 'BTC';
	return $s =~ /^(ltc1[02-9ac-hj-np-z]{11,71}|[LM3][1-9A-HJ-NP-Za-km-z]{25,34})$/ ? 1 : 0 if $a->{'code'} eq 'LTC';
	return $s =~ /^[D9A][1-9A-HJ-NP-Za-km-z]{25,34}$/ ? 1 : 0 if $a->{'code'} eq 'DOGE';
	return $s =~ /^r[1-9A-HJ-NP-Za-km-z]{24,34}$/ ? 1 : 0 if $a->{'code'} eq 'XRP';
	return $s =~ /^(addr1[0-9a-z]{20,100}|Ae[0-9A-Za-z]{50,60}|DdzFF[0-9A-Za-z]{50,100})$/ ? 1 : 0 if $a->{'code'} eq 'ADA';
	return $s =~ /^1[1-9A-HJ-NP-Za-km-z]{45,47}$/ ? 1 : 0 if $a->{'code'} eq 'DOT';
	return $s =~ /^(bitcoincash:)?[qp][0-9a-z]{41}$/ ? 1 : 0 if $a->{'code'} eq 'BCH';
	return $s =~ /^G[A-Z2-7]{55}$/ ? 1 : 0 if $a->{'code'} eq 'XLM';
	return $s =~ /^cosmos1[0-9a-z]{38,60}$/ ? 1 : 0 if $a->{'code'} eq 'ATOM';
	return $s =~ /^(EQ|UQ|kQ|0Q)[A-Za-z0-9_-]{46,48}$/ ? 1 : 0 if $a->{'code'} eq 'TON';
	return $s =~ /^T[1-9A-HJ-NP-Za-km-z]{33}$/ ? 1 : 0 if $net eq 'tron';
	return $s =~ /^0x[0-9a-fA-F]{40}$/ ? 1 : 0 if $net eq 'ethereum' || $net eq 'bnb';
	return $s =~ /^([XPC][A-Za-z0-9-]{10,120}|0x[0-9a-fA-F]{40})$/ ? 1 : 0 if $net eq 'avalanche';
	return $s =~ /^[1-9A-HJ-NP-Za-km-z]{32,44}$/ ? 1 : 0 if $net eq 'solana';
	return $s =~ /^[A-Za-z0-9]{20,100}$/ ? 1 : 0;
}

# ---- watch-only Bitcoin addresses (BIP32 public derivation) -------------------
# An account xpub is public: it derives receive addresses and cannot spend. A
# wallet that carries one gives every invoice its own address. OpenSSL does the
# scalar multiple (import the scalar as a private key, export its public point)
# and the hash/encoding work; the one step it does not expose - adding the
# parent point to IL*G - is a handful of BigInt operations below.
#
# Everything here is public data. There is deliberately no function that takes a
# private key, a seed phrase or an xprv.
require Math::BigInt;

our $crypto_secp256k1_p = Math::BigInt->new('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F');
our $crypto_secp256k1_n = Math::BigInt->new('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
our $crypto_base58_alphabet = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
our $crypto_bech32_charset = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
our %crypto_base58_index;
@crypto_base58_index{ split //, $crypto_base58_alphabet } = ( 0 .. 57 ) unless %crypto_base58_index;

# The public version bytes a wallet exports for an account. A testnet key is
# accepted only when the wallet itself is not on bitcoin mainnet.
our %crypto_xpub_version = (
	0x0488B21E => { script => 'p2pkh',       net => 'main' },
	0x049D7CB2 => { script => 'p2sh-p2wpkh', net => 'main' },
	0x04B24746 => { script => 'p2wpkh',      net => 'main' },
	0x043587CF => { script => 'p2pkh',       net => 'test' },
	0x044A5262 => { script => 'p2sh-p2wpkh', net => 'test' },
	0x045F1CF6 => { script => 'p2wpkh',      net => 'test' },
);

# A private extended key or a WIF is a spending key, never a watch-only one.
sub crypto_xpub_is_private {
	my ($text) = @_;
	return 0 unless defined $text && length $text;
	my $s = $text;
	$s =~ s/^\s+|\s+$//g;
	return 1 if $s =~ /^(?:[xyztuv]prv)/i;
	return 1 if $s =~ /^[5KLc9][1-9A-HJ-NP-Za-km-z]{50,51}$/;
	return 0;
}

sub crypto_big_mod {
	my ($v) = @_;
	$v->bmod($crypto_secp256k1_p);
	$v->badd($crypto_secp256k1_p) if $v->is_neg;
	return $v;
}

sub crypto_secp256k1_add {
	my ($x1, $y1, $x2, $y2) = @_;
	return undef unless defined $x1 && defined $x2 && defined $y1 && defined $y2;
	my ($num, $den);
	if ($x1->bcmp($x2) == 0) {
		return undef if $y1->bcmp($y2) != 0 || $y1->is_zero;
		$num = &crypto_big_mod($x1->copy->bmul($x1)->bmul(3));
		$den = &crypto_big_mod($y1->copy->bmul(2));
	}
	else {
		$num = &crypto_big_mod($y2->copy->bsub($y1));
		$den = &crypto_big_mod($x2->copy->bsub($x1));
	}
	my $inv = eval { $den->copy->bmodinv($crypto_secp256k1_p) };
	return undef unless $inv;
	my $lambda = &crypto_big_mod($num->copy->bmul($inv));
	my $x3 = &crypto_big_mod($lambda->copy->bmul($lambda)->bsub($x1)->bsub($x2));
	my $y3 = &crypto_big_mod($lambda->copy->bmul(&crypto_big_mod($x1->copy->bsub($x3)))->bsub($y1));
	return ($x3, $y3);
}

sub crypto_secp256k1_pub_parse {
	my ($bytes) = @_;
	return undef unless defined $bytes && length($bytes) == 33
		&& (substr($bytes, 0, 1) eq "\x02" || substr($bytes, 0, 1) eq "\x03");
	my $pk = eval { Crypt::PK::ECC->new };
	return undef unless $pk;
	my $ok = eval { $pk->import_key_raw($bytes, 'secp256k1'); 1 };
	return undef unless $ok;
	my $u = eval { $pk->export_key_raw('public') };
	return undef unless defined $u && length($u) == 65 && substr($u, 0, 1) eq "\x04";
	return ( Math::BigInt->from_bytes(substr($u, 1, 32)), Math::BigInt->from_bytes(substr($u, 33, 32)) );
}

# IL*G. The scalar is imported as a secp256k1 private key and its public point
# exported, so the curve work stays in CryptX.
sub crypto_secp256k1_mul_g {
	my ($raw) = @_;
	return undef unless defined $raw && length($raw) == 32;
	my $pk = eval { Crypt::PK::ECC->new };
	return undef unless $pk;
	my $ok = eval { $pk->import_key_raw($raw, 'secp256k1'); 1 };
	return undef unless $ok;
	my $u = eval { $pk->export_key_raw('public') };
	return undef unless defined $u && length($u) == 65 && substr($u, 0, 1) eq "\x04";
	return ( Math::BigInt->from_bytes(substr($u, 1, 32)), Math::BigInt->from_bytes(substr($u, 33, 32)) );
}

sub crypto_secp256k1_compress {
	my ($x, $y) = @_;
	return undef unless $x && $y;
	my $hex = $x->as_hex;
	$hex =~ s/^0x//;
	$hex = ('0' x 64) . $hex;
	$hex = substr($hex, -64);
	return ($y->is_odd ? "\x03" : "\x02") . pack('H*', $hex);
}

sub crypto_base58_encode {
	my ($bytes) = @_;
	return '' unless defined $bytes && length $bytes;
	my $n = Math::BigInt->from_bytes($bytes);
	my $base = Math::BigInt->new(58);
	my $out = '';
	while (!$n->is_zero) {
		my $r = $n->copy->bmod($base)->numify;
		$out = substr($crypto_base58_alphabet, $r, 1) . $out;
		$n->bdiv($base);
	}
	my $zeros = ($bytes =~ /^(\x00*)/) ? length($1) : 0;
	return ('1' x $zeros) . $out;
}

sub crypto_base58_decode {
	my ($s) = @_;
	return undef unless defined $s && length $s;
	my $n = Math::BigInt->new(0);
	foreach my $c ( split //, $s ) {
		return undef unless exists $crypto_base58_index{$c};
		$n->bmul(58)->badd($crypto_base58_index{$c});
	}
	my $bytes = $n->is_zero ? '' : $n->to_bytes;
	my $zeros = ($s =~ /^(1*)/) ? length($1) : 0;
	return ("\x00" x $zeros) . $bytes;
}

sub crypto_base58check_encode {
	my ($payload) = @_;
	return undef unless defined $payload;
	return &crypto_base58_encode($payload . substr(Digest::SHA::sha256(Digest::SHA::sha256($payload)), 0, 4));
}

sub crypto_base58check_decode {
	my ($s) = @_;
	my $raw = &crypto_base58_decode($s);
	return undef unless defined $raw && length($raw) >= 4;
	my $payload = substr($raw, 0, -4);
	my $check = substr($raw, -4);
	return undef unless $check eq substr(Digest::SHA::sha256(Digest::SHA::sha256($payload)), 0, 4);
	return $payload;
}

sub crypto_hash160 {
	my ($bytes) = @_;
	return undef unless defined $bytes;
	my $ok = eval { require Crypt::Digest::RIPEMD160; 1 };
	return undef unless $ok;
	return Crypt::Digest::RIPEMD160::ripemd160(Digest::SHA::sha256($bytes));
}

sub crypto_bech32_polymod {
	my (@v) = @_;
	my @gen = (0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3);
	my $chk = 1;
	foreach my $v (@v) {
		my $top = $chk >> 25;
		$chk = (($chk & 0x1ffffff) << 5) ^ $v;
		for my $i (0 .. 4) {
			$chk ^= $gen[$i] if (($top >> $i) & 1);
		}
	}
	return $chk;
}

sub crypto_bech32_hrp_expand {
	my ($hrp) = @_;
	return ( (map { ord($_) >> 5 } split //, $hrp), 0, (map { ord($_) & 31 } split //, $hrp) );
}

sub crypto_bech32_convert_bits {
	my ($data, $from, $to, $pad) = @_;
	my ($acc, $bits, @out) = (0, 0);
	foreach my $b ( unpack('C*', $data) ) {
		$acc = (($acc << $from) | $b) & ((1 << ($from + $bits)) - 1);
		$bits += $from;
		while ($bits >= $to) {
			$bits -= $to;
			push @out, (($acc >> $bits) & ((1 << $to) - 1));
		}
	}
	push @out, (($acc << ($to - $bits)) & ((1 << $to) - 1)) if $pad && $bits > 0;
	return @out;
}

sub crypto_segwit_encode {
	my ($hrp, $version, $program) = @_;
	return undef unless defined $hrp && defined $program && length($program);
	my @data = ( $version, &crypto_bech32_convert_bits($program, 8, 5, 1) );
	my $const = $version == 0 ? 1 : 0x2bc830a3;
	my $polymod = &crypto_bech32_polymod(&crypto_bech32_hrp_expand($hrp), @data, (0) x 6) ^ $const;
	my @check = map { ($polymod >> (5 * (5 - $_))) & 31 } (0 .. 5);
	return $hrp . '1' . join('', map { substr($crypto_bech32_charset, $_, 1) } (@data, @check));
}

# Decode an account xpub (or ypub/zpub and their testnet forms). Returns the
# public key and chain code plus the script type the version bytes name.
sub crypto_xpub_decode {
	my ($text) = @_;
	return undef unless defined $text && length $text;
	my $s = $text;
	$s =~ s/^\s+|\s+$//g;
	my $raw = &crypto_base58check_decode($s);
	return undef unless defined $raw && length($raw) == 78;
	my ($version, $depth, $fingerprint, $child, $chain, $pub) = unpack('N C a4 N a32 a33', $raw);
	my $v = $crypto_xpub_version{$version} or return undef;
	return undef unless length($pub) == 33
		&& (substr($pub, 0, 1) eq "\x02" || substr($pub, 0, 1) eq "\x03");
	return {
		version => $version, depth => $depth, fingerprint => unpack('H*', $fingerprint),
		child => $child, chain => $chain, pub => $pub,
		script => $v->{'script'}, net => $v->{'net'},
	};
}

sub crypto_xpub_valid {
	my ($text) = @_;
	return 0 if &crypto_xpub_is_private($text);
	return defined &crypto_xpub_decode($text) ? 1 : 0;
}

# One non-hardened public child. Returns undef when BIP32 says the child is
# invalid (IL = 0 or IL >= n), so the caller can try the next index.
sub crypto_xpub_child {
	my ($x, $index) = @_;
	return undef unless ref $x eq 'HASH' && defined $x->{'pub'} && defined $x->{'chain'};
	$index = 0 unless defined $index && $index =~ /^\d+$/;
	my $I = Digest::SHA::hmac_sha512($x->{'pub'} . pack('N', $index), $x->{'chain'});
	my $IL = substr($I, 0, 32);
	my $IR = substr($I, 32, 32);
	my $il = Math::BigInt->from_bytes($IL);
	return undef if $il->is_zero || $il->bcmp($crypto_secp256k1_n) >= 0;
	my ($gx, $gy) = &crypto_secp256k1_mul_g($IL);
	return undef unless defined $gx;
	my ($px, $py) = &crypto_secp256k1_pub_parse($x->{'pub'});
	return undef unless defined $px;
	my ($cx, $cy) = &crypto_secp256k1_add($px, $py, $gx, $gy);
	return undef unless defined $cx;
	return {
		pub => &crypto_secp256k1_compress($cx, $cy),
		chain => $IR,
		index => $index,
		depth => ($x->{'depth'} // 0) + 1,
	};
}

# The address at /0/index under an account xpub, encoded for the script type
# the key names. This is the external (receive) chain only; change addresses
# live at /1/index and are never issued here.
sub crypto_xpub_address {
	my ($xpub, $index) = @_;
	my $x = ref $xpub eq 'HASH' ? $xpub : &crypto_xpub_decode($xpub);
	return undef unless $x;
	$index = 0 unless defined $index && $index =~ /^\d+$/;
	my $ext = &crypto_xpub_child($x, 0);
	return undef unless $ext;
	my $child = &crypto_xpub_child($ext, $index);
	return undef unless $child;
	my $hash = &crypto_hash160($child->{'pub'});
	return undef unless defined $hash && length($hash) == 20;
	my $address;
	if ($x->{'script'} eq 'p2wpkh') {
		$address = &crypto_segwit_encode($x->{'net'} eq 'test' ? 'tb' : 'bc', 0, $hash);
	}
	elsif ($x->{'script'} eq 'p2sh-p2wpkh') {
		my $redeem = "\x00\x14" . $hash;
		$address = &crypto_base58check_encode(($x->{'net'} eq 'test' ? "\xC4" : "\x05") . &crypto_hash160($redeem));
	}
	else {
		$address = &crypto_base58check_encode(($x->{'net'} eq 'test' ? "\x6F" : "\x00") . $hash);
	}
	return undef unless defined $address && length $address;
	my $purpose = $x->{'script'} eq 'p2pkh' ? 44 : $x->{'script'} eq 'p2sh-p2wpkh' ? 49 : 84;
	my $coin = $x->{'net'} eq 'test' ? "1'" : "0'";
	return {
		address => $address,
		index => $index,
		path => "m/$purpose'/$coin/0'/0/$index",
		script => $x->{'script'},
		net => $x->{'net'},
	};
}

# A BIP21 payment request: the address and, when known, the exact amount. No
# label or message, so no ampersand ever reaches the QR encoder's argument.
sub crypto_bip21_uri {
	my ($address, $amount) = @_;
	return '' unless defined $address && length $address;
	my $n = &crypto_amount_number($amount, 'BTC');
	return 'bitcoin:' . $address . (defined $n && $n =~ /[1-9]/ ? '?amount=' . $n : '');
}

sub crypto_rates_read {
	my $raw = &setting_grabber({ app => 'crypto', setting => 'rates', device => 'all' });
	my $r = eval { decode_json($raw) };
	$r = {} unless ref $r eq 'HASH';
	$r->{'rates'} = {} unless ref $r->{'rates'} eq 'HASH';
	$r->{'at'} = 0 unless defined $r->{'at'} && $r->{'at'} =~ /^\d+$/;
	return $r;
}

sub crypto_rates_write {
	my ($rates, $source, $base) = @_;
	return 0 unless ref $rates eq 'HASH';
	# Rates are one house-wide snapshot. A row left on a single device by an
	# older build (or replayed by a peer) is stale and would double the payload;
	# the shared row is the only one read.
	&db_query("delete from settings where app = 'crypto' and setting = 'rates' and device != 'all'");
	my $payload = {
		at => &rightNow(),
		source => ($source || 'manual'),
		base => ($base || &crypto_report_currency()),
		rates => $rates,
	};
	&setting_setter({ app => 'crypto', setting => 'rates', value => encode_json($payload), device => 'all' });
	return $payload;
}

# reporting currency per one unit of $code
sub crypto_rate {
	my ($code, $base) = @_;
	$code = uc($code || '');
	return undef unless length $code;
	my $r = &crypto_rates_read();
	my $rates = $r->{'rates'};
	my $from = $rates->{$code};
	return undef unless defined $from && $from > 0;
	$base = uc($base || '');
	$base = &crypto_report_currency() unless length $base;
	my $to = $rates->{$base};
	return undef unless defined $to && $to > 0;
	return $from / $to;
}

sub crypto_rate_age {
	my $r = &crypto_rates_read();
	return undef unless $r->{'at'};
	return &rightNow() - $r->{'at'};
}

# A fiat pair, read from the same snapshot. The static formulas in gb.pl are the
# fallback only while no snapshot exists yet.
sub exchange_rate {
	my ($from, $to) = @_;
	$from = uc($from || '');
	$to = uc($to || '');
	return undef unless length $from && length $to;
	return 1 if $from eq $to;
	my $r = &crypto_rates_read();
	my $rates = $r->{'rates'};
	my ($f, $t) = ($rates->{$from}, $rates->{$to});
	return undef unless defined $f && defined $t && $f > 0 && $t > 0;
	return $f / $t;
}

sub crypto_value {
	my ($amount, $asset) = @_;
	return undef unless defined $amount && $amount =~ /-?\d/;
	my $rate = &crypto_rate($asset);
	return undef unless defined $rate;
	require Math::BigFloat;
	my $v = Math::BigFloat->new("$amount");
	$v->bmul(Math::BigFloat->new("$rate"));
	return $v->numify;
}

sub crypto_transaction {
	my ($data) = @_;
	my $d = ref $data eq 'HASH' ? $data : eval { decode_json($data || '') };
	my $c = ref $d eq 'HASH' ? $d->{'crypto'} : undef;
	return ref $c eq 'HASH' ? $c : undef;
}

# One snapshot for every asset and every fiat code. The request is public and
# keyless; an offline house keeps its last snapshot rather than losing the rates.
sub crypto_rates_refresh {
	my ($opts) = @_;
	$opts ||= {};
	return { ok => 0, error => 'crypto is off' } unless &crypto_enabled || $opts->{'force'};
	require Mojo::UserAgent;
	my $base = &crypto_report_currency();
	my $ua = Mojo::UserAgent->new(insecure => 1, connect_timeout => 8, inactivity_timeout => 12, request_timeout => 20);
	my (%rates, $source);
	my $res = eval { $ua->get('https://api.coinbase.com/v2/exchange-rates?currency=' . $base)->result };
	if ($res && $res->is_success) {
		my $json = eval { decode_json($res->body) };
		my $raw = ref $json eq 'HASH' ? $json->{'data'}->{'rates'} : undef;
		if (ref $raw eq 'HASH') {
			my %known = map { $_->{'coinbase'} => 1 } @crypto_asset_list;
			my %fiat = map { $_->{'code'} => 1 } @crypto_fiat_table;
			foreach my $code ( keys %{$raw} ) {
				next unless $fiat{$code} || $known{$code};
				my $v = $raw->{$code};
				next unless defined $v && $v =~ /^\d/ && $v > 0;
				$rates{$code} = 1 / $v;
			}
			$source = 'coinbase' if scalar keys %rates > 3;
		}
	}
	if (!$source) {
		my $res2 = eval { $ua->get('https://open.er-api.com/v6/latest/' . $base)->result };
		if ($res2 && $res2->is_success) {
			my $json2 = eval { decode_json($res2->body) };
			my $raw2 = ref $json2 eq 'HASH' ? $json2->{'rates'} : undef;
			if (ref $raw2 eq 'HASH') {
				my %fiat = map { $_->{'code'} => 1 } @crypto_fiat_table;
				foreach my $code ( keys %{$raw2} ) {
					next unless $fiat{$code};
					my $v = $raw2->{$code};
					next unless defined $v && $v =~ /^\d/ && $v > 0;
					$rates{$code} = 1 / $v;
				}
				$source = 'open.er-api' if scalar keys %rates > 3;
			}
		}
	}
	return { ok => 0, error => 'no rate source answered' } unless $source;
	# A fiat-only fallback keeps the coins from the previous snapshot: a stale
	# coin rate is better than a wallet that cannot be valued.
	if ($source ne 'coinbase') {
		my $old = &crypto_rates_read();
		my %coin = map { $_->{'coinbase'} => 1 } @crypto_asset_list;
		foreach my $code ( keys %{ $old->{'rates'} } ) {
			$rates{$code} = $old->{'rates'}->{$code} if $coin{$code} && !exists $rates{$code};
		}
	}
	$rates{$base} = 1 unless exists $rates{$base};
	my $written = &crypto_rates_write(\%rates, $source, $base);
	# The Measures app's PV column is a reading of the same snapshot.
	eval { &crypto_measures_sync(); };
	# The same snapshot feeds the optional history: one measure appointment
	# every six hours, in place of the app and appointment that used to do it.
	eval { &crypto_tracking_tick(); };
	return { ok => 1, source => $source, base => $base, count => scalar keys %rates, at => $written->{'at'} };
}

# What each wallet holds and what it is worth. Native units follow the signed
# amount stored on the transaction (income positive, expense negative, a
# transfer leg signed by its own direction); the money column is the signed
# total, exactly the figure the ledger's account balance uses.
sub crypto_wallets_report {
	my $accounts = &crypto_accounts();
	my $mode = lc(&setting_grabber({ app => 'crypto', setting => 'valuation', device => 'all' }) || 'cost');
	$mode = 'market' if $mode eq 'market';
	$mode = 'cost' unless $mode eq 'market';
	require Math::BigFloat;
	foreach my $w ( @{$accounts} ) {
		my $rows = &db_query("select total, data, movement from appointments where account = ? and type = 'transaction'", $w->{'app'})->hashes;
		my $native = Math::BigFloat->new(0);
		my $book = 0;
		my $count = 0;
		foreach my $r ( @{$rows} ) {
			my $c = &crypto_transaction($r->{'data'});
			next unless $c && defined $c->{'amount'} && $c->{'amount'} =~ /-?\d/;
			next unless uc($c->{'asset'} || '') eq $w->{'asset'};
			$native->badd(Math::BigFloat->new("$c->{'amount'}"));
			$book += ($r->{'total'} || 0) + 0;
			$count++;
		}
		my $rate = &crypto_rate($w->{'asset'});
		$w->{'native'} = $native->bstr();
		$w->{'native_display'} = &crypto_amount_format($w->{'native'}, $w->{'asset'});
		$w->{'book'} = $book;
		$w->{'rate'} = $rate;
		$w->{'market'} = defined $rate ? ($native * $rate)->numify : undef;
		$w->{'value'} = $mode eq 'market' && defined $w->{'market'} ? $w->{'market'} : $book;
		$w->{'valuation'} = $mode;
		$w->{'count'} = $count;
		$w->{'address_short'} = length($w->{'address'}) > 18
			? substr($w->{'address'}, 0, 10) . '…' . substr($w->{'address'}, -6)
			: $w->{'address'};
	}
	return $accounts;
}

# ---- one address per invoice -------------------------------------------------
# The wallet's account xpub makes a fresh receiving address from the external
# chain. The row lives in crypto_address (synced like any other table) so an
# invoice keeps its address across edits, peers and reprints. A wallet with no
# xpub falls back to the single address saved on the account, exactly as before.

sub crypto_invoice_wallet {
	my ($asset) = @_;
	$asset = uc($asset || 'BTC');
	my @wallets = @{ &crypto_accounts() };
	my @same = grep { ($_->{'asset'} || '') eq $asset } @wallets;
	my ($with_key) = grep { ($_->{'xpub'} || '') ne '' } @same;
	return $with_key if $with_key;
	return $same[0] if @same;
	return undef;
}

# A wallet field that must be the same on every machine (the xpub, and the
# address it falls back to). A shared row wins even when it is empty, so
# clearing the field on one machine is not undone by a stale device row.
sub crypto_wallet_setting {
	my ($app, $setting) = @_;
	return '' unless defined $app && length $app;
	my $shared = &setting_grabber({ app => $app, setting => $setting, device => 'all' });
	return $shared if defined $shared;
	return &setting_grabber({ app => $app, setting => $setting });
}

# Read the address an invoice already owns. Never writes: the public invoice
# page and the print view call this, and a GET must not allocate.
sub crypto_invoice_address_read {
	my ($app, $invoice) = @_;
	return undef unless defined $app && length $app && defined $invoice && length $invoice;
	my $q = &db_query("select * from crypto_address where app = ? and invoice_uuid = ? order by server_time desc limit 1", $app, $invoice);
	my $row = $q ? $q->hashes->[0] : undef;
	return { %{$row}, existing => 1 } if $row;
	my $static = &crypto_wallet_setting($app, 'wallet_address') || '';
	my $xpub = &crypto_wallet_setting($app, 'wallet_xpub') || '';
	return { address => $static, static => 1, missing => 1 } if length $xpub;
	return { address => $static, static => 1 };
}

# Reserve this invoice's address. Idempotent: a second call returns the same
# row. insert or ignore keeps two machines that allocated the same index while
# apart from failing the insert; the loser simply takes the next index.
sub crypto_invoice_address {
	my ($opts) = @_;
	my $app = $opts->{'app'};
	my $invoice = $opts->{'invoice'};
	return undef unless defined $app && length $app && defined $invoice && length $invoice;
	my $found = &crypto_invoice_address_read($app, $invoice);
	return $found unless $found && $found->{'missing'};
	my $static = $found->{'address'} || '';
	my $xpub = &crypto_wallet_setting($app, 'wallet_xpub') || '';
	my $x = &crypto_xpub_decode($xpub);
	return { address => $static, static => 1, error => 'the xpub could not be read' } unless $x;
	my $q = &db_query("select max(addr_index) as m from crypto_address where app = ?", $app);
	my $row = $q ? $q->hashes->[0] : undef;
	my $next = (defined $row && defined $row->{'m'}) ? $row->{'m'} + 1 : 0;
	for my $try (0 .. 7) {
		my $index = $next + $try;
		my $a = &crypto_xpub_address($x, $index);
		last unless $a;
		my $now = &rightNow();
		my $uuid = &random_string_creator(40);
		&db_query("insert or ignore into crypto_address (uuid, server_time, ost, app, asset, network, address, derivation, addr_index, path, invoice_uuid, issued_at) values (?,?,?,?,?,?,?,?,?,?,?,?)",
			$uuid, $now, $now, $app, 'BTC', $a->{'net'}, $a->{'address'}, $a->{'script'}, $index, $a->{'path'}, $invoice, $now);
		my $check = &db_query("select * from crypto_address where app = ? and invoice_uuid = ? order by server_time desc limit 1", $app, $invoice);
		my $hit = $check ? $check->hashes->[0] : undef;
		return { %{$hit}, allocated => 1 } if $hit;
	}
	return { address => $static, static => 1, error => 'no free address' };
}

# ---- currency tracking ------------------------------------------------------
# The old way to keep a currency history was an app with an appointment that
# wrote a measure every few hours. The checkbox in Configure -> Plat -> Crypto
# does the same job from the rate snapshot: one appointment of type measure in
# the house's currency app every six hours, carrying every tracked fiat code, so
# the Measures app charts it and no appointment has to run.

sub crypto_tracking_on {
	my $v = &setting_grabber({ app => 'crypto', setting => 'tracking', device => 'all' });
	return (defined $v && $v eq 'on') ? 1 : 0;
}

# The app the history goes to. An explicit choice wins; otherwise adopt the app
# the house already uses for currency measures, so its existing charts carry on.
sub crypto_tracking_app {
	my $pref = &setting_grabber({ app => 'crypto', setting => 'tracking_app', device => 'all' });
	if (defined $pref && length $pref) {
		$pref = &unformat_name($pref);
		return $pref if length $pref;
	}
	foreach my $a ( qw/canadian_dollar currency exchange_rates/ ) {
		my $row = &db_query("select 1 from settings where app = ? and setting = 'app_measures' limit 1", $a)->hashes->[0];
		return $a if $row;
	}
	return 'currency';
}

sub crypto_tracking_interval { return 6 * 60 * 60 * 1000 }

sub crypto_tracking_definitions {
	my ($app) = @_;
	my $row = &db_query("select value from settings where app = ? and setting = 'app_measures' order by server_time desc limit 1", $app)->hashes->[0];
	return {} unless $row;
	my $defs = eval { decode_json($row->{'value'}) };
	return ref $defs eq 'HASH' ? $defs : {};
}

# The app's measures can live on more than one device; update every row that is
# there rather than the one this worker happens to be running as.
sub crypto_tracking_definitions_write {
	my ($app, $defs) = @_;
	return 0 unless ref $defs eq 'HASH';
	my $json = encode_json($defs);
	my $devices = &db_query("select distinct device from settings where app = ? and setting = 'app_measures'", $app)->hashes;
	my @dev = map { $_->{'device'} } @{$devices};
	@dev = ( &device_setter() ) unless scalar @dev;
	foreach my $d ( @dev ) {
		next unless defined $d && length $d;
		&setting_setter({ app => $app, setting => 'app_measures', value => $json, device => $d });
	}
	return 1;
}

# The Measures app's PV column reads the same snapshot the Crypto panel shows:
# one unit of a code, valued in the house's reporting currency. The fiat rows
# Measures already holds are updated in place; every enabled coin gets a row of
# its own, so a market price has somewhere to sit. Called after a refresh and
# whenever Measures opens, so a snapshot taken while the panel was closed still
# fills the column without waiting for the next half-hour.
sub crypto_measures_sync {
	my $rates = &crypto_rates_read();
	my $table = $rates->{'rates'};
	return 0 unless ref $table eq 'HASH' && scalar keys %{$table};
	my $base = $rates->{'base'} || &crypto_report_currency();
	my $base_v = $table->{$base};
	$base_v = 1 unless defined $base_v && $base_v > 0;
	my $raw = &setting_grabber({ app => 'measures', setting => 'measures' });
	my $measures = eval { decode_json($raw) };
	return 0 unless ref $measures eq 'HASH' && scalar keys %{$measures};
	my $changed = 0;
	foreach my $k ( keys %{$measures} ) {
		next unless ref $measures->{$k} eq 'HASH';
		# only a code-shaped row (USD, EUR, JPY) names a snapshot unit
		next unless uc($k) eq $k && $k =~ /^[A-Z]{3}$/;
		my $v = $table->{$k};
		next unless defined $v && $v > 0;
		my $per = $v / $base_v;
		my $pv = $per >= 1 ? sprintf('%.2f', $per) : sprintf('%.6f', $per);
		next if defined $measures->{$k}->{'pv'} && $measures->{$k}->{'pv'} eq $pv;
		$measures->{$k}->{'pv'} = $pv;
		$changed++;
	}
	foreach my $code ( @{ &crypto_enabled_assets() } ) {
		my $v = $table->{$code};
		next unless defined $v && $v > 0;
		my $asset = &crypto_asset($code);
		my $row = $measures->{$code};
		if (ref $row ne 'HASH') {
			$row = $measures->{$code} = {
				name => ($asset->{'name'} || $code),
				types => [ 'currency' ],
				symbol => ($asset->{'symbol'} || ''),
				uuid => &random_string_creator(26),
			};
			$changed++;
		}
		my $per = $v / $base_v;
		my $pv = $per >= 1 ? sprintf('%.2f', $per) : sprintf('%.6f', $per);
		next if defined $row->{'pv'} && $row->{'pv'} eq $pv;
		$row->{'pv'} = $pv;
		$changed++;
	}
	return 0 unless $changed;
	&setting_setter({ app => 'measures', setting => 'measures', value => encode_json($measures) });
	return $changed;
}

sub crypto_tracking_tick {
	my ($opts) = @_;
	$opts ||= {};
	return { ok => 0, error => 'tracking is off' } unless &crypto_tracking_on;
	my $now = &rightNow();
	my $last = &setting_grabber({ app => 'crypto', setting => 'tracked_at', device => 'all' });
	if (!$opts->{'force'} && defined $last && $last =~ /^\d+$/ && $now - $last < &crypto_tracking_interval) {
		return { ok => 0, error => 'not due yet', at => $last };
	}
	my $rates = &crypto_rates_read();
	my $table = $rates->{'rates'} || {};
	return { ok => 0, error => 'no rate snapshot' } unless scalar keys %{$table};
	my $base = $rates->{'base'} || &crypto_report_currency();
	my $base_v = $table->{$base};
	$base_v = 1 unless defined $base_v && $base_v > 0;
	my $app = &crypto_tracking_app();
	my $defs = &crypto_tracking_definitions($app);
	if (!scalar keys %{$defs}) {
		return { ok => 0, error => 'no measures app yet' } unless $opts->{'create'};
		# An app that already exists only needs its measure definitions; a name
		# nobody has used yet is initialized like any other app.
		my $exists = &db_query('select 1 from settings where app = ? limit 1', $app)->hashes->[0]
			|| &db_query('select 1 from appointments where app = ? limit 1', $app)->hashes->[0];
		if (!$exists) {
			my $init = &setting_initializer($app, $now);
			$app = $init->{'app'} if ref $init eq 'HASH' && $init->{'app'};
		}
		$defs = &crypto_tracking_definitions($app);
	}
	my (@entries, $count);
	$count = 0;
	foreach my $f ( @crypto_fiat_table ) {
		next if $f->{'code'} eq $base;   # the base against itself is always 1
		next if $count >= 50;            # the top fifty the source answers
		my $v = $table->{ $f->{'code'} };
		next unless defined $v && $v > 0;
		my $per_base = $base_v / $v;     # units of this code per 1 report unit
		my $shown = sprintf('%.6f', $per_base);
		push @entries, { $f->{'measure'} => $shown, ts => $now, uuid => &random_string_creator(28) };
		$defs->{ $f->{'measure'} } = {
			type => 'number',
			unit => $f->{'code'},
			value => $shown,
			name => $f->{'name'},
		};
		$count++;
	}
	return { ok => 0, error => 'no currencies to record' } unless scalar @entries;
	my $uuid = &random_string_creator(40);
	&db_insert('appointments', {
		app => $app,
		type => 'measure',
		timestamp => $now,
		duration => 1000,
		measures => encode_json(\@entries),
		server_time => $now,
		uuid => $uuid,
		device => &device_setter(),
	});
	&crypto_tracking_definitions_write($app, $defs);
	&setting_setter({ app => 'crypto', setting => 'tracked_at', value => $now, device => 'all' });
	return { ok => 1, app => $app, count => $count, uuid => $uuid, at => $now };
}

# The Store's two directions, named for what the house is doing: an income
# movement is a sale and an expense movement is a purchase. The stored movement
# values do not change - only the words on the Store's own dropdown.
sub store_movement_label {
	my ($m) = @_;
	$m = '' unless defined $m;
	return &lang('store.selling') if $m eq 'income';
	return &lang('store.buying') if $m eq 'expense';
	return &lang('common.' . $m) if $m eq 'transfer' || $m eq 'inventory';
	return &format_name($m);
}

# ---- payment proofs ---------------------------------------------------------
# A payer's crest signs a statement of what was sent for which document; the
# payee signs the same bytes back. The code travels like a crest code (PAY1Z:
# deflated JSON), so it can be pasted or scanned. This is an attestation by the
# two houses, not a chain check: the txid is carried, not verified here.

sub payment_proof_statement {
	my ($record) = @_;
	return undef unless ref $record eq 'HASH';
	my $copy = { %$record };
	delete $copy->{'payer_sig'};
	delete $copy->{'payee_sig'};
	return JSON::PP->new->canonical(1)->encode($copy);
}

sub payment_proof_build {
	my ($record, $priv) = @_;
	return undef unless ref $record eq 'HASH' && defined $priv && length $priv == 32;
	my $json = &payment_proof_statement($record);
	return undef unless defined $json;
	require Crypt::PK::Ed25519;
	my $key = Crypt::PK::Ed25519->new;
	$key->import_key_raw($priv, 'private');
	my $sig = $key->sign_message($json);
	return undef unless defined $sig && length $sig == 64;
	return { %$record, payer_sig => encode_base64($sig, '') };
}

sub payment_proof_verify {
	my ($record) = @_;
	return 0 unless ref $record eq 'HASH';
	return 0 unless ($record->{'format'} || '') eq 'jawnos-payment';
	return 0 unless ($record->{'version'} || 0) == 1;
	my $payer = ref $record->{'payer'} eq 'HASH' ? $record->{'payer'} : {};
	my $pub = eval { decode_base64($payer->{'pubkey'} || '') };
	my $sig = eval { decode_base64($record->{'payer_sig'} || '') };
	return 0 unless defined $pub && length $pub == 32 && defined $sig && length $sig == 64;
	my $json = &payment_proof_statement($record);
	return 0 unless defined $json;
	require Crypt::PK::Ed25519;
	my $key = Crypt::PK::Ed25519->new;
	$key->import_key_raw($pub, 'public');
	return $key->verify_message($sig, $json) ? 1 : 0;
}

sub payment_proof_countersign {
	my ($record, $priv) = @_;
	return undef unless ref $record eq 'HASH' && defined $priv && length $priv == 32;
	my $json = &payment_proof_statement($record);
	return undef unless defined $json;
	require Crypt::PK::Ed25519;
	my $key = Crypt::PK::Ed25519->new;
	$key->import_key_raw($priv, 'private');
	my $sig = $key->sign_message($json);
	return undef unless defined $sig && length $sig == 64;
	return { %$record, payee_sig => encode_base64($sig, '') };
}

sub payment_proof_verify_payee {
	my ($record, $pubkey) = @_;
	return 0 unless ref $record eq 'HASH' && defined $pubkey && length $pubkey;
	my $pub = eval { decode_base64($pubkey) };
	my $sig = eval { decode_base64($record->{'payee_sig'} || '') };
	return 0 unless defined $pub && length $pub == 32 && defined $sig && length $sig == 64;
	my $json = &payment_proof_statement($record);
	return 0 unless defined $json;
	require Crypt::PK::Ed25519;
	my $key = Crypt::PK::Ed25519->new;
	$key->import_key_raw($pub, 'public');
	return $key->verify_message($sig, $json) ? 1 : 0;
}

sub payment_proof_code {
	my ($record) = @_;
	return undef unless ref $record eq 'HASH';
	my $json = JSON::PP->new->canonical(1)->encode($record);
	require Compress::Zlib;
	my $packed = Compress::Zlib::compress($json);
	return undef unless defined $packed && length $packed;
	return 'PAY1Z:' . encode_base64($packed, '');
}

sub payment_proof_parse {
	my ($code) = @_;
	return undef unless defined $code;
	$code =~ s/^\s+|\s+$//g;
	return undef unless $code =~ /^PAY1Z:(.*)$/is;
	my $packed = $1;
	$packed =~ s/\s+//g;
	my $bytes = eval { decode_base64($packed) };
	return undef unless defined $bytes && length $bytes;
	require Compress::Zlib;
	$bytes = Compress::Zlib::uncompress($bytes);
	return undef unless defined $bytes && length $bytes;
	my $record = eval { decode_json($bytes) };
	return ref $record eq 'HASH' ? $record : undef;
}

# A native amount and a claimed amount are equal when they are within 1% - a
# rate moves between quoting and sending, but not by more than that in practice.
sub payment_amount_matches {
	my ($a, $b) = @_;
	return 0 unless defined $a && defined $b && "$a" =~ /\d/ && "$b" =~ /\d/;
	my $x = "$a" + 0;
	my $y = "$b" + 0;
	return 1 if $x == $y;
	return 0 unless $y != 0;
	return abs($x - $y) / abs($y) <= 0.01 ? 1 : 0;
}

# ---- online payments (Configure -> Plat -> Pay) ----------------------------
#
# Four ways for a customer to settle an invoice from the public invoice page:
# Stripe, Square and PayPal create a hosted checkout for the exact balance and
# record the payment when the provider says it is paid; Interac e-Transfer has
# no consumer API, so JawnOS reads the notification letters already arriving in
# the mailbox (or accepts a signed forwarder) and stages them for the seller.
# Keys are sealed like an AI key and never leave the server.

sub pay_secret_names {
	return qw(
		stripe_secret stripe_webhook_secret
		square_access_token square_webhook_key
		paypal_secret paypal_webhook_id
		interac_hook_token
	);
}

# Read a pay setting. The house shares these the way it shares the language, so
# a phone and the desk agree on which provider is on.
sub pay_setting {
	my ($name, $default) = @_;
	return $default unless defined $name && length $name;
	my $v = &setting_grabber({ app => 'pay', setting => $name, device => 'all' });
	return (defined $v && length $v) ? $v : $default;
}

# A secret is stored sealed; a value written by an older build (or a plain row
# replayed by a peer) still opens, so a key is never lost to a format change.
sub pay_secret_read {
	my ($name) = @_;
	my $v = &pay_setting($name, '');
	return '' unless defined $v && length $v;
	# A pay key is always sealed. Without the vault it cannot be opened, and a
	# provider that looks ready but cannot authenticate is worse than one that
	# stays hidden, so a locked vault reads as an empty key.
	my $suds = eval { &suds_grabber() };
	return '' unless $suds;
	my $d = eval { &note_decrypter($suds, $v) };
	return (defined $d && length $d) ? $d : '';
}

sub pay_on {
	return &pay_setting('enabled', 'off') eq 'on' ? 1 : 0;
}

sub pay_currency {
	return &crypto_report_currency();
}

sub pay_providers {
	return [
		{ id => 'stripe',  label => 'Stripe',            kind => 'card' },
		{ id => 'square',  label => 'Square',            kind => 'card' },
		{ id => 'paypal',  label => 'PayPal',            kind => 'wallet' },
		{ id => 'interac', label => 'Interac e-Transfer', kind => 'transfer' },
	];
}

# A provider is offered only when the house turned it on AND it has what it
# needs to work. The public page reads this same answer, so a half-filled panel
# never shows a button that cannot complete.
sub pay_provider_ready {
	my ($provider) = @_;
	return 0 unless &pay_on;
	$provider = lc($provider || '');
	return 0 unless &pay_setting($provider . '_enabled', 'off') eq 'on';
	if ($provider eq 'stripe') {
		return length(&pay_secret_read('stripe_secret')) ? 1 : 0;
	}
	if ($provider eq 'square') {
		return (length(&pay_secret_read('square_access_token')) && length(&pay_setting('square_location_id', ''))) ? 1 : 0;
	}
	if ($provider eq 'paypal') {
		return (length(&pay_setting('paypal_client_id', '')) && length(&pay_secret_read('paypal_secret'))) ? 1 : 0;
	}
	if ($provider eq 'interac') {
		return length(&pay_setting('interac_email', '')) ? 1 : 0;
	}
	return 0;
}

# The accounts a payment may be booked into. An account is an app whose part of
# speech is account, the same list the App tab and a transaction use.
sub pay_accounts {
	my $rows = &db_query("select distinct app from settings where setting in ('pos','mab') and value = 'account' and app is not null and app != '' order by app")->hashes;
	my @out;
	foreach my $r ( @{$rows} ) {
		my $tender = &setting_grabber({ app => $r->{'app'}, setting => 'payment_type' });
		push @out, {
			app => $r->{'app'},
			name => &format_name($r->{'app'}),
			payment_type => ($tender || ''),
		};
	}
	return \@out;
}

# Where a provider's money lands. The panel's own choice wins; without one, the
# first account that names the tender is a sensible fallback so a house that
# never opened this panel still records the money somewhere.
sub pay_account_for {
	my ($provider) = @_;
	my $picked = &pay_setting($provider . '_account', '');
	return $picked if length $picked;
	my $want = ($provider eq 'interac') ? 'interac' : 'credit';
	my $row = &db_query("select app from settings where setting = 'payment_type' and lower(value) = ? and app is not null and app != '' order by app limit 1", $want)->hashes->[0];
	return $row->{'app'} if $row && $row->{'app'};
	my $any = &db_query("select distinct app from settings where setting in ('pos','mab') and value = 'account' and app is not null and app != '' order by app limit 1")->hashes->[0];
	return ($any && $any->{'app'}) ? $any->{'app'} : '';
}

# The address a provider redirects back to, and the address a webhook is sent
# to. The public side of the house lives on port 3000; a house with a public
# name can override the whole thing with pay.base_url.
sub pay_public_base {
	my ($c) = @_;
	my $custom = &pay_setting('base_url', '');
	if (length $custom) { $custom =~ s{/+$}{}; return $custom; }
	my $domain = '';
	my $row = eval { &db_query("select domain from devices where domain is not null and domain != '' limit 1")->hashes->[0] };
	$domain = $row->{'domain'} if $row && $row->{'domain'};
	$domain = $config->{'domain'} if !length $domain && $config && $config->{'domain'};
	my $port = ($config && $config->{'port'}) ? $config->{'port'} : 3000;
	if (length $domain) { return 'https://' . $domain . ':' . $port; }
	# The public invoice page is served on the house's public port, not the
	# manager's working port, so a return or webhook built here must use it.
	my $host = '';
	if ($c) { $host = eval { $c->req->url->host } || ''; }
	if (length $host) { return 'https://' . $host . ':' . $port; }
	return '';
}

sub pay_webhook_url {
	my ($c, $provider) = @_;
	my $base = &pay_public_base($c);
	return $base . '/pay/' . $provider . '/webhook';
}

sub pay_ua {
	require Mojo::UserAgent;
	return Mojo::UserAgent->new(connect_timeout => 8, inactivity_timeout => 25, request_timeout => 35);
}

# The invoice's own reference, printed on the paper and used to match an
# e-transfer's message. It is the human id, not the uuid.
sub pay_invoice_ref {
	my ($data) = @_;
	my $id = ref $data eq 'HASH' ? ($data->{'id'} || '') : '';
	$id =~ s/[^A-Za-z0-9._-]//g;
	return $id;
}

sub pay_invoice_balance {
	my ($inv) = @_;
	my $data = eval { decode_json($inv->{'data'} || '') } || {};
	$data->{'numbers'} = {} unless ref $data->{'numbers'} eq 'HASH';
	$data->{'payments'} = [] unless ref $data->{'payments'} eq 'ARRAY';
	my $paid = 0;
	foreach my $p ( @{ $data->{'payments'} } ) {
		$paid += $p->{'amount'} if defined $p->{'amount'} && $p->{'amount'} =~ /[0-9]/;
	}
	my $balance = defined $data->{'numbers'}->{'balance'}
		? $data->{'numbers'}->{'balance'}
		: (($data->{'numbers'}->{'total'} || 0) - $paid);
	return ($data, $balance + 0, $paid + 0);
}

# Find the invoice a public payment link names. The customer uuid scopes it, so
# one invoice uuid cannot be paid through another customer's page.
sub pay_invoice_lookup {
	my ($uuid, $cx) = @_;
	return () unless defined $uuid && length $uuid;
	my $customer = $cx ? &db_select('settings', undef, { setting => 'uuid', value => $cx })->hashes->[0] : undef;
	my $inv = ($customer && $customer->{'app'})
		? &db_select('appointments', undef, { uuid => $uuid, app => $customer->{'app'} })->hashes->[0]
		: &db_select('appointments', undef, { uuid => $uuid })->hashes->[0];
	return () unless $inv && ($inv->{'type'} || '') eq 'invoice';
	my ($data, $balance, $paid) = &pay_invoice_balance($inv);
	return ($inv, $customer, $data, $balance, $paid);
}

# A hosted checkout is remembered for an hour so a refresh reopens the same one
# instead of creating a second charge. The key carries the amount, so a partial
# payment creates its own session.
sub pay_session_save {
	my ($provider, $uuid, $data) = @_;
	return unless defined $provider && defined $uuid && ref $data eq 'HASH';
	my $minor = int((($data->{'amount'} || 0) * 100) + 0.5);
	my $key = 'pay_session:' . $provider . ':' . $uuid . ':' . $minor;
	&db_query('delete from cache where context = ? and uuid = ?', 'pay_session', $key);
	my $now = &rightNow();
	&db_insert('cache', {
		uuid => $key,
		app => 'pay_session',
		context => 'pay_session',
		timestamp => $now,
		server_time => $now,
		warranty => $now + 3600000,
		data => encode_json({ %{$data}, provider => $provider, invoice_uuid => $uuid, at => $now }),
	});
}

sub pay_session_find {
	my ($provider, $uuid, $amount) = @_;
	return undef unless defined $provider && defined $uuid && length $uuid;
	my $rows = &db_query('select data, server_time from cache where context = ? and uuid like ? order by server_time desc limit 5', 'pay_session', 'pay_session:' . $provider . ':' . $uuid . ':%')->hashes;
	my $want = defined $amount ? int(($amount * 100) + 0.5) : undef;
	foreach my $r ( @{$rows} ) {
		my $d = eval { decode_json($r->{'data'} || '') } || {};
		next if defined $want && defined $d->{'amount'} && int(($d->{'amount'} * 100) + 0.5) != $want;
		return $d;
	}
	return undef;
}

sub pay_session_forget {
	my ($provider, $uuid) = @_;
	return unless defined $provider && defined $uuid && length $uuid;
	&db_query('delete from cache where context = ? and uuid like ?', 'pay_session', 'pay_session:' . $provider . ':' . $uuid . ':%');
}

# The one place a payment is written to an invoice. It is safe to call twice:
# a provider reference already on the invoice is reported, not counted again.
sub pay_record_payment {
	my ($args) = @_;
	$args ||= {};
	my $uuid = $args->{'uuid'} || '';
	my $cx = $args->{'cx'} || '';
	return { ok => 0, error => 'no invoice was named' } unless length $uuid;
	my ($inv, $customer, $data, $balance) = &pay_invoice_lookup($uuid, $cx);
	return { ok => 0, error => 'the invoice could not be found' } unless $inv;

	my $provider = lc($args->{'provider'} || 'other');
	my $ref = $args->{'ref'} || '';
	if (length $ref) {
		foreach my $p ( @{ $data->{'payments'} } ) {
			next unless ($p->{'provider'} || '') eq $provider;
			if (($p->{'provider_ref'} || '') eq $ref) {
				return { ok => 1, duplicate => 1, balance => $balance, uuid => $uuid, cx => $cx };
			}
		}
	}
	# A repeat of a payment that is already on the invoice is answered above. A
	# different reference on a settled invoice is a real extra payment (a second
	# checkout, or an e-transfer that arrived late), so it is recorded and shown
	# as an overpayment rather than silently dropped; the balance stays at zero.

	my $amount = defined $args->{'amount'} ? "$args->{'amount'}" : '0';
	$amount =~ s/[^0-9.\-]//g;
	$amount = 0 + $amount;
	return { ok => 0, error => 'the payment amount could not be read' } unless $amount > 0;
	my $base = &pay_currency();
	my $currency = uc($args->{'currency'} || $base);
	my $value = $amount;
	if ($currency ne $base) {
		my $rate = &exchange_rate($currency, $base);
		return { ok => 0, error => 'no rate is loaded to convert ' . $currency . ' to ' . $base } unless defined $rate && $rate > 0;
		$value = $amount * $rate;
	}
	$value = sprintf('%.2f', $value);
	return { ok => 0, error => 'the payment is worth nothing' } unless $value > 0;

	my $account = $args->{'account'} || &pay_account_for($provider);
	my $ts = $args->{'at'} || &rightNow();
	my $server_time = &rightNow();
	my $tx_uuid = &random_string_creator(40);
	if (length $account) {
		my $tx = {
			app => $inv->{'app'},
			account => $account,
			movement => 'income',
			type => 'transaction',
			timestamp => $ts,
			server_time => $server_time,
			uuid => $tx_uuid,
			amount => $value,
			total => $value,
			tax => 0,
			aux => 0,
			currency => $base,
			item => &unformat_name(($args->{'label'} || $provider) . ' payment'),
			data => encode_json({ pay => {
				provider => $provider,
				ref => $ref,
				value => $value,
				currency => $currency,
				paid => $amount,
			} }),
		};
		&db_insert('appointments', $tx);
		&warehouse_money_mirror($tx);
	}

	my $payment = {
		account => $account,
		uuid => &random_string_creator(12),
		appt_uuid => $tx_uuid,
		amount => $value,
		timestamp => $ts,
		server_time => $server_time,
		provider => $provider,
		provider_ref => $ref,
		currency => $currency,
		paid => $amount,
		note => ($args->{'note'} || ''),
	};
	$payment->{'payer'} = $args->{'payer'} if ref $args->{'payer'} eq 'HASH';
	push @{ $data->{'payments'} }, $payment;
	my $new_balance = $balance - $value;
	my $overpaid = $new_balance < -0.005 ? -$new_balance : 0;
	$payment->{'overpaid'} = $overpaid if $overpaid > 0;
	$new_balance = 0 if $new_balance < 0;
	$new_balance = 0 if abs($new_balance) < 0.005;
	$data->{'numbers'}->{'balance'} = $new_balance;
	my $status = $new_balance <= 0 ? 'completed' : 'open';
	&db_update('appointments', { data => encode_json($data), status => $status, server_time => $server_time }, { uuid => $uuid, app => $inv->{'app'} });
	&Websocket::send('server', { console => 'appointmentDetailGrabber(' . encode_json($inv->{'app'}) . ',' . encode_json($uuid) . ');' });
	&pay_session_forget($provider, $uuid);
	return {
		ok => 1,
		payment => $payment,
		balance => $new_balance,
		status => $status,
		overpaid => $overpaid,
		account => $account,
		uuid => $uuid,
		cx => $cx,
	};
}

# What the public invoice page offers. Only providers that can actually finish
# are listed; Interac has no redirect, so it carries the address and reference
# the customer needs instead of a button.
sub pay_options_for {
	my ($c, $inv, $data, $balance, $cx) = @_;
	return undef unless &pay_on && defined $balance && $balance > 0.005;
	my @methods;
	foreach my $p ( qw/stripe square paypal/ ) {
		next unless &pay_provider_ready($p);
		my $label = $p eq 'stripe' ? 'Pay by card' : $p eq 'square' ? 'Pay with Square' : 'PayPal';
		push @methods, {
			id => $p,
			label => $label,
			url => '/pay/' . $p . '/start?uuid=' . url_escape($inv->{'uuid'}) . '&cx=' . url_escape($cx || ''),
		};
	}
	my $interac;
	if (&pay_provider_ready('interac')) {
		# The invoice balance is in the house currency; an e-Transfer is made in
		# the currency the receiving account uses, so show the customer that.
		my $icur = &pay_interac_currency();
		my $base_cur = &pay_currency();
		my $irate = ($icur eq $base_cur) ? 1 : &exchange_rate($base_cur, $icur);
		my $iamount = (defined $irate && $irate > 0) ? ($balance * $irate) : $balance;
		$interac = {
			email => &pay_setting('interac_email', ''),
			name => &pay_setting('interac_name', ''),
			reference => &pay_invoice_ref($data),
			instructions => &pay_setting('interac_instructions', ''),
			autodeposit => (&pay_setting('interac_autodeposit', 'off') eq 'on' ? 1 : 0),
			amount => $iamount,
			currency => $icur,
		};
	}
	return undef unless scalar @methods || $interac;
	return {
		amount => $balance,
		currency => &pay_currency(),
		methods => \@methods,
		interac => $interac,
	};
}

# Minor units: most currencies have cents, but a few do not. Checkout APIs
# want an integer, and paying 100x too much is worse than a wrong-looking row.
sub pay_minor {
	my ($amount, $currency) = @_;
	my %zero = map { $_ => 1 } qw(BIF CLP DJF GNF JPY KMF KRW MGA PYG RWF UGX VND VUV XAF XOF XPF);
	return int($amount + 0.5) if $zero{uc($currency || '')};
	return int(($amount * 100) + 0.5);
}

sub pay_major {
	my ($minor, $currency) = @_;
	my %zero = map { $_ => 1 } qw(BIF CLP DJF GNF JPY KMF KRW MGA PYG RWF UGX VND VUV XAF XOF XPF);
	return 0 + ($minor || 0) if $zero{uc($currency || '')};
	return ($minor || 0) / 100;
}

# ---- Stripe ---------------------------------------------------------------
sub pay_stripe_start {
	my ($args) = @_;
	my $secret = &pay_secret_read('stripe_secret');
	return { ok => 0, error => 'Stripe is not set up' } unless length $secret;
	my $currency = lc($args->{'currency'} || &pay_currency());
	my $form = {
		mode => 'payment',
		'payment_method_types[0]' => 'card',
		'line_items[0][quantity]' => 1,
		'line_items[0][price_data][currency]' => $currency,
		'line_items[0][price_data][unit_amount]' => &pay_minor($args->{'amount'}, $currency),
		'line_items[0][price_data][product_data][name]' => $args->{'item'},
		'client_reference_id' => $args->{'uuid'},
		'success_url' => $args->{'return_url'},
		'cancel_url' => $args->{'cancel_url'},
		'metadata[invoice_uuid]' => $args->{'uuid'},
		'metadata[cx]' => ($args->{'cx'} || ''),
		'metadata[app]' => ($args->{'app'} || ''),
	};
	$form->{'line_items[0][price_data][product_data][description]'} = $args->{'description'} if length($args->{'description'} || '');
	$form->{'customer_email'} = $args->{'email'} if length($args->{'email'} || '');
	my $res = eval { &pay_ua()->post('https://api.stripe.com/v1/checkout/sessions' => { Authorization => 'Bearer ' . $secret } => form => $form)->result };
	my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
	if (!$res || !$res->is_success || !$json->{'url'}) {
		my $why = ref $json->{'error'} eq 'HASH' ? ($json->{'error'}->{'message'} || '') : '';
		$why = 'the provider did not answer' unless length $why;
		return { ok => 0, error => 'Stripe: ' . $why };
	}
	&pay_session_save('stripe', $args->{'uuid'}, {
		amount => $args->{'amount'}, currency => $args->{'currency'},
		session_id => $json->{'id'}, url => $json->{'url'},
	});
	return { ok => 1, url => $json->{'url'}, ref => $json->{'id'} };
}

sub pay_stripe_session_read {
	my ($id) = @_;
	return undef unless defined $id && $id =~ /^cs_[A-Za-z0-9_]+$/;
	my $secret = &pay_secret_read('stripe_secret');
	return undef unless length $secret;
	my $res = eval { &pay_ua()->get('https://api.stripe.com/v1/checkout/sessions/' . $id => { Authorization => 'Bearer ' . $secret })->result };
	return undef unless $res && $res->is_success;
	return eval { decode_json($res->body) };
}

sub pay_stripe_signature_ok {
	my ($body, $header) = @_;
	my $secret = &pay_secret_read('stripe_webhook_secret');
	return 0 unless length $secret && defined $body && defined $header;
	my ($t) = $header =~ /(?:^|,)\s*t=(\d+)/;
	my @v1 = $header =~ /(?:^|,)\s*v1=([0-9a-f]{64})/g;
	return 0 unless defined $t && scalar @v1;
	return 0 if abs(time() - $t) > 300;
	require Digest::SHA;
	my $expected = Digest::SHA::hmac_sha256_hex($t . '.' . $body, $secret);
	return scalar(grep { &secure_compare($_, $expected) } @v1) ? 1 : 0;
}

sub pay_stripe_webhook {
	my ($event) = @_;
	return { ok => 0, error => 'no event' } unless ref $event eq 'HASH';
	my $type = $event->{'type'} || '';
	return { ok => 1, ignored => $type } unless $type eq 'checkout.session.completed' || $type eq 'checkout.session.async_payment_succeeded';
	my $s = ref $event->{'data'} eq 'HASH' ? ($event->{'data'}->{'object'} || {}) : {};
	return { ok => 1, ignored => 'not paid' } unless ($s->{'payment_status'} || '') eq 'paid';
	my $meta = ref $s->{'metadata'} eq 'HASH' ? $s->{'metadata'} : {};
	return &pay_record_payment({
		uuid => ($meta->{'invoice_uuid'} || ''),
		cx => ($meta->{'cx'} || ''),
		provider => 'stripe',
		ref => ($s->{'id'} || ''),
		amount => &pay_major(($s->{'amount_total'} || 0), uc($s->{'currency'} || '')),
		currency => uc($s->{'currency'} || ''),
		note => 'Stripe (webhook)',
	});
}

# ---- Square ---------------------------------------------------------------
sub pay_square_base {
	return &pay_setting('square_mode', 'production') eq 'sandbox' ? 'https://connect.squareupsandbox.com' : 'https://connect.squareup.com';
}

sub pay_square_start {
	my ($args) = @_;
	my $token = &pay_secret_read('square_access_token');
	my $loc = &pay_setting('square_location_id', '');
	return { ok => 0, error => 'Square is not set up' } unless length $token && length $loc;
	my $body = {
		idempotency_key => $args->{'uuid'} . '-' . &pay_minor($args->{'amount'}, $args->{'currency'}) . '-' . time(),
		order => {
			location_id => $loc,
			reference_id => $args->{'uuid'},
			line_items => [{
				name => $args->{'item'},
				quantity => '1',
				base_price_money => {
					amount => &pay_minor($args->{'amount'}, $args->{'currency'}),
					currency => uc($args->{'currency'} || &pay_currency()),
				},
			}],
			metadata => {
				invoice_uuid => $args->{'uuid'},
				cx => ($args->{'cx'} || ''),
				app => ($args->{'app'} || ''),
			},
		},
		checkout_options => { redirect_url => $args->{'return_url'} },
	};
	$body->{'pre_populated_data'} = { buyer_email => $args->{'email'} } if length($args->{'email'} || '');
	my $res = eval { &pay_ua()->post(&pay_square_base() . '/v2/online-checkout/payment-links' => {
		Authorization => 'Bearer ' . $token,
		'Content-Type' => 'application/json',
	} => json => $body)->result };
	my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
	my $link = ref $json->{'payment_link'} eq 'HASH' ? $json->{'payment_link'} : {};
	if (!$res || !$res->is_success || !$link->{'url'}) {
		my $why = ref $json->{'errors'} eq 'ARRAY' && @{ $json->{'errors'} } ? ($json->{'errors'}->[0]->{'detail'} || $json->{'errors'}->[0]->{'code'} || '') : '';
		$why = 'the provider did not answer' unless length $why;
		return { ok => 0, error => 'Square: ' . $why };
	}
	&pay_session_save('square', $args->{'uuid'}, {
		amount => $args->{'amount'}, currency => $args->{'currency'},
		order_id => ($link->{'order_id'} || ''), link_id => ($link->{'id'} || ''), url => $link->{'url'},
	});
	return { ok => 1, url => $link->{'url'}, ref => ($link->{'order_id'} || $link->{'id'}) };
}

sub pay_square_order_read {
	my ($id) = @_;
	return undef unless defined $id && length $id;
	my $token = &pay_secret_read('square_access_token');
	return undef unless length $token;
	my $res = eval { &pay_ua()->get(&pay_square_base() . '/v2/orders/' . url_escape($id) => { Authorization => 'Bearer ' . $token })->result };
	return undef unless $res && $res->is_success;
	my $json = eval { decode_json($res->body) } || {};
	return ref $json->{'order'} eq 'HASH' ? $json->{'order'} : undef;
}

sub pay_square_signature_ok {
	my ($body, $signature, $url) = @_;
	my $key = &pay_secret_read('square_webhook_key');
	return 0 unless length $key && defined $body && defined $signature;
	$url = &pay_setting('square_webhook_url', '') unless length($url || '');
	return 0 unless length($url || '');
	require Digest::SHA;
	my $expected = encode_base64(Digest::SHA::hmac_sha256($url . $body, $key), '');
	return &secure_compare($signature, $expected) ? 1 : 0;
}

sub pay_square_webhook {
	my ($event) = @_;
	return { ok => 0, error => 'no event' } unless ref $event eq 'HASH';
	my $type = $event->{'type'} || '';
	return { ok => 1, ignored => $type } unless $type eq 'payment.updated' || $type eq 'payment.created';
	my $obj = ref $event->{'data'} eq 'HASH' ? ($event->{'data'}->{'object'} || {}) : {};
	my $p = ref $obj->{'payment'} eq 'HASH' ? $obj->{'payment'} : $obj;
	return { ok => 1, ignored => 'not completed' } unless uc($p->{'status'} || '') eq 'COMPLETED';
	my $order_id = $p->{'order_id'} || '';
	my $order = $order_id ? &pay_square_order_read($order_id) : undef;
	my $meta = ($order && ref $order->{'metadata'} eq 'HASH') ? $order->{'metadata'} : {};
	my $uuid = $meta->{'invoice_uuid'} || ($order ? ($order->{'reference_id'} || '') : '');
	my $cx = $meta->{'cx'} || '';
	my $amount = ref $p->{'amount_money'} eq 'HASH' ? &pay_major(($p->{'amount_money'}->{'amount'} || 0), ($p->{'amount_money'}->{'currency'} || '')) : 0;
	my $currency = ref $p->{'amount_money'} eq 'HASH' ? ($p->{'amount_money'}->{'currency'} || '') : '';
	if (!$amount && $order && ref $order->{'total_money'} eq 'HASH') {
		$amount = &pay_major(($order->{'total_money'}->{'amount'} || 0), ($order->{'total_money'}->{'currency'} || ''));
		$currency = $order->{'total_money'}->{'currency'} || $currency;
	}
	return { ok => 0, error => 'the payment names no invoice' } unless length $uuid;
	return &pay_record_payment({
		uuid => $uuid, cx => $cx, provider => 'square',
		ref => ($p->{'id'} || $order_id), amount => $amount, currency => $currency,
		note => 'Square (webhook)',
	});
}

# ---- PayPal ---------------------------------------------------------------
sub pay_paypal_base {
	return &pay_setting('paypal_mode', 'live') eq 'sandbox' ? 'https://api-m.sandbox.paypal.com' : 'https://api-m.paypal.com';
}

sub pay_paypal_token {
	my $id = &pay_setting('paypal_client_id', '');
	my $secret = &pay_secret_read('paypal_secret');
	return (undef, 'PayPal is not set up') unless length $id && length $secret;
	my $res = eval { &pay_ua()->post(&pay_paypal_base() . '/v1/oauth2/token' => {
		Authorization => 'Basic ' . encode_base64($id . ':' . $secret, ''),
	} => form => { grant_type => 'client_credentials' })->result };
	my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
	return (undef, 'PayPal did not answer') unless $res && $res->is_success && $json->{'access_token'};
	return ($json->{'access_token'}, undef);
}

sub pay_paypal_start {
	my ($args) = @_;
	my ($token, $err) = &pay_paypal_token();
	return { ok => 0, error => $err || 'PayPal is not set up' } unless $token;
	my $brand = &pay_setting('paypal_brand', '') || &setting_grabber({ app => 'me', setting => 'store_name' }) || 'JawnOS';
	my $body = {
		intent => 'CAPTURE',
		purchase_units => [{
			reference_id => $args->{'uuid'},
			custom_id => $args->{'uuid'} . '|' . ($args->{'cx'} || ''),
			description => $args->{'item'},
			amount => {
				currency_code => uc($args->{'currency'} || &pay_currency()),
				value => sprintf('%.2f', $args->{'amount'} || 0),
			},
		}],
		application_context => {
			brand_name => $brand,
			user_action => 'PAY_NOW',
			return_url => $args->{'return_url'},
			cancel_url => $args->{'cancel_url'},
		},
	};
	my $res = eval { &pay_ua()->post(&pay_paypal_base() . '/v2/checkout/orders' => {
		Authorization => 'Bearer ' . $token, 'Content-Type' => 'application/json',
	} => json => $body)->result };
	my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
	my ($approve) = grep { ($_->{'rel'} || '') eq 'approve' } @{ ref $json->{'links'} eq 'ARRAY' ? $json->{'links'} : [] };
	if (!$res || !$res->is_success || !$approve || !$approve->{'href'}) {
		my $why = ref $json->{'details'} eq 'ARRAY' && @{ $json->{'details'} } ? ($json->{'details'}->[0]->{'description'} || $json->{'details'}->[0]->{'issue'} || '') : ($json->{'message'} || '');
		$why = 'the provider did not answer' unless length $why;
		return { ok => 0, error => 'PayPal: ' . $why };
	}
	&pay_session_save('paypal', $args->{'uuid'}, {
		amount => $args->{'amount'}, currency => $args->{'currency'},
		order_id => ($json->{'id'} || ''), url => $approve->{'href'},
	});
	return { ok => 1, url => $approve->{'href'}, ref => ($json->{'id'} || '') };
}

sub pay_paypal_order_read {
	my ($id) = @_;
	return undef unless defined $id && $id =~ /^[A-Za-z0-9-]{6,}$/;
	my ($token, $err) = &pay_paypal_token();
	return undef unless $token;
	my $res = eval { &pay_ua()->get(&pay_paypal_base() . '/v2/checkout/orders/' . url_escape($id) => { Authorization => 'Bearer ' . $token })->result };
	return undef unless $res && $res->is_success;
	return eval { decode_json($res->body) };
}

sub pay_paypal_capture {
	my ($id) = @_;
	return { ok => 0, error => 'no order' } unless defined $id && length $id;
	my ($token, $err) = &pay_paypal_token();
	return { ok => 0, error => $err || 'PayPal is not set up' } unless $token;
	my $res = eval { &pay_ua()->post(&pay_paypal_base() . '/v2/checkout/orders/' . url_escape($id) . '/capture' => {
		Authorization => 'Bearer ' . $token, 'Content-Type' => 'application/json',
	} => json => {})->result };
	my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
	return { ok => ($res && $res->is_success) ? 1 : 0, data => $json, error => ($res && $res->is_success) ? undef : ($json->{'message'} || 'PayPal did not capture the order') };
}

sub pay_paypal_capture_record {
	my ($order, $note) = @_;
	return { ok => 0, error => 'no order' } unless ref $order eq 'HASH';
	my $unit = ref $order->{'purchase_units'} eq 'ARRAY' ? ($order->{'purchase_units'}->[0] || {}) : {};
	my $capture = ref $unit->{'payments'} eq 'HASH' && ref $unit->{'payments'}->{'captures'} eq 'ARRAY' ? ($unit->{'payments'}->{'captures'}->[0] || {}) : {};
	return { ok => 0, error => 'PayPal has not captured this order yet' } unless uc($capture->{'status'} || '') eq 'COMPLETED';
	my $uuid = $unit->{'reference_id'} || '';
	my $cx = '';
	if (!length $uuid && length($unit->{'custom_id'} || '')) {
		($uuid, $cx) = split /\|/, $unit->{'custom_id'}, 2;
	}
	my $amount = ref $capture->{'amount'} eq 'HASH' ? $capture->{'amount'}->{'value'} : ($unit->{'amount'}->{'value'} || 0);
	my $currency = ref $capture->{'amount'} eq 'HASH' ? $capture->{'amount'}->{'currency_code'} : ($unit->{'amount'}->{'currency_code'} || '');
	return { ok => 0, error => 'the payment names no invoice' } unless length($uuid || '');
	return &pay_record_payment({
		uuid => $uuid, cx => $cx, provider => 'paypal',
		ref => ($capture->{'id'} || ''), amount => $amount, currency => $currency,
		note => ($note || 'PayPal'),
	});
}

sub pay_paypal_webhook_verify {
	my ($event, $h) = @_;
	my $id = &pay_secret_read('paypal_webhook_id');
	return 0 unless length $id;
	my ($token, $err) = &pay_paypal_token();
	return 0 unless $token;
	my $body = {
		auth_algo => $h->{'paypal-auth-algo'} || '',
		cert_url => $h->{'paypal-cert-url'} || '',
		transmission_id => $h->{'paypal-transmission-id'} || '',
		transmission_sig => $h->{'paypal-transmission-sig'} || '',
		transmission_time => $h->{'paypal-transmission-time'} || '',
		webhook_id => $id,
		webhook_event => $event,
	};
	my $res = eval { &pay_ua()->post(&pay_paypal_base() . '/v1/notifications/verify-webhook-signature' => {
		Authorization => 'Bearer ' . $token, 'Content-Type' => 'application/json',
	} => json => $body)->result };
	return 0 unless $res && $res->is_success;
	my $json = eval { decode_json($res->body) } || {};
	return ($json->{'verification_status'} || '') eq 'SUCCESS' ? 1 : 0;
}

sub pay_paypal_webhook {
	my ($event, $verified) = @_;
	return { ok => 0, error => 'the webhook signature did not verify' } unless $verified;
	return { ok => 0, error => 'no event' } unless ref $event eq 'HASH';
	my $type = $event->{'event_type'} || '';
	my $res = ref $event->{'resource'} eq 'HASH' ? $event->{'resource'} : {};
	if ($type eq 'CHECKOUT.ORDER.APPROVED') {
		my $id = $res->{'id'} || '';
		my $cap = &pay_paypal_capture($id);
		if (!$cap->{'ok'}) {
			# A retry can arrive after the first capture; read the order back and
			# record what is already there rather than refusing the webhook.
			my $issue = ref $cap->{'data'} eq 'HASH' && ref $cap->{'data'}->{'details'} eq 'ARRAY' && @{ $cap->{'data'}->{'details'} }
				? ($cap->{'data'}->{'details'}->[0]->{'issue'} || '') : '';
			my $order = $issue eq 'ORDER_ALREADY_CAPTURED' ? &pay_paypal_order_read($id) : undef;
			return { ok => 0, error => $cap->{'error'} } unless $order;
			return &pay_paypal_capture_record($order, 'PayPal (webhook)');
		}
		return &pay_paypal_capture_record($cap->{'data'}, 'PayPal (webhook)');
	}
	if ($type eq 'PAYMENT.CAPTURE.COMPLETED') {
		my $order_id = ref $res->{'supplementary_data'} eq 'HASH' && ref $res->{'supplementary_data'}->{'related_ids'} eq 'HASH'
			? ($res->{'supplementary_data'}->{'related_ids'}->{'order_id'} || '') : '';
		my $order = length $order_id ? &pay_paypal_order_read($order_id) : undef;
		if ($order) { return &pay_paypal_capture_record($order, 'PayPal (webhook)'); }
		my ($uuid, $cx) = split /\|/, ($res->{'custom_id'} || ''), 2;
		return &pay_record_payment({
			uuid => $uuid, cx => ($cx || ''), provider => 'paypal',
			ref => ($res->{'id'} || ''),
			amount => (ref $res->{'amount'} eq 'HASH' ? $res->{'amount'}->{'value'} : 0),
			currency => (ref $res->{'amount'} eq 'HASH' ? $res->{'amount'}->{'currency_code'} : ''),
			note => 'PayPal (webhook)',
		});
	}
	return { ok => 1, ignored => $type };
}

# ---- starting and finishing a checkout ------------------------------------
# One entry point both the public page and a return use, so the invoice lookup
# and the readiness check cannot drift apart.
sub pay_start {
	my ($provider, $c, $uuid, $cx) = @_;
	$provider = lc($provider || '');
	return { ok => 0, error => 'that payment method is not available' } unless grep { $_ eq $provider } qw/stripe square paypal/;
	return { ok => 0, error => 'online payment is turned off' } unless &pay_provider_ready($provider);
	my ($inv, $customer, $data, $balance) = &pay_invoice_lookup($uuid, $cx);
	return { ok => 0, error => 'the invoice could not be found' } unless $inv;
	return { ok => 0, error => 'this invoice is already paid' } if $balance <= 0.005;
	my $base = &pay_public_base($c);
	my $ref = &pay_invoice_ref($data);
	# One opaque "cid" carries the invoice and customer through the provider's
	# redirect. Some providers append their own query to the return URL; the
	# invoice uuid is still recoverable from this value even then.
	my $cid = url_escape($uuid . '|' . ($cx || ''));
	my $return_url = $base . '/pay/' . $provider . '/return?cid=' . $cid;
	$return_url .= '&session_id={CHECKOUT_SESSION_ID}' if $provider eq 'stripe';
	my $cancel_url = $base . '/public_view/invoice/' . url_escape($uuid) . '/' . url_escape($cx || '');
	my $email = '';
	if ($customer && $customer->{'app'}) {
		my $es = &setting_grabber({ app => $customer->{'app'}, setting => 'email' });
		$email = $es || '';
	}
	my $store = &setting_grabber({ app => 'me', setting => 'store_name' }) || 'JawnOS';
	my $args = {
		uuid => $uuid, cx => $cx, app => $inv->{'app'},
		amount => $balance, currency => &pay_currency(),
		item => 'Invoice ' . ($ref || $uuid),
		description => 'Payment to ' . &format_name($store) . ' for invoice ' . ($ref || $uuid),
		email => $email, return_url => $return_url, cancel_url => $cancel_url,
	};
	if ($provider eq 'stripe') { return &pay_stripe_start($args); }
	if ($provider eq 'square') { return &pay_square_start($args); }
	if ($provider eq 'paypal') { return &pay_paypal_start($args); }
	return { ok => 0, error => 'that payment method is not available' };
}

# The provider sends the customer back here. Nothing the browser says is
# trusted: the provider's own record is read and that is what is recorded.
sub pay_return_handle {
	my ($provider, $c) = @_;
	$provider = lc($provider || '');
	my $base = &pay_public_base($c);
	my $cid = $c->param('cid') || '';
	my ($cid_uuid, $cid_cx) = split /\|/, $cid, 2;
	$cid_uuid =~ s/[?&].*$// if defined $cid_uuid;
	$cid_cx =~ s/[?&].*$// if defined $cid_cx;
	my $back = sub {
		my ($uuid, $cx) = @_;
		return length($uuid || '') ? $base . '/public_view/invoice/' . url_escape($uuid) . '/' . url_escape($cx || '') : '';
	};
	if ($provider eq 'stripe') {
		my $id = $c->param('session_id') || '';
		if (!length $id && length($cid_uuid || '')) {
			my $saved = &pay_session_find('stripe', $cid_uuid);
			$id = $saved->{'session_id'} if $saved;
		}
		my $session = &pay_stripe_session_read($id);
		return { ok => 0, pending => 1, message => 'Stripe has not confirmed this payment yet. Refresh this page in a moment; the invoice will update when the confirmation arrives.' } unless $session;
		my $meta = ref $session->{'metadata'} eq 'HASH' ? $session->{'metadata'} : {};
		my $uuid = $meta->{'invoice_uuid'} || $cid_uuid || '';
		my $cx = $meta->{'cx'} || $cid_cx || '';
		if (($session->{'payment_status'} || '') ne 'paid') {
			return { ok => 0, pending => 1, uuid => $uuid, cx => $cx, invoice_url => $back->($uuid, $cx), message => 'Stripe is still processing this payment. Refresh this page in a moment; the invoice will update when it is confirmed.' };
		}
		my $out = &pay_record_payment({
			uuid => $uuid, cx => $cx, provider => 'stripe', ref => ($session->{'id'} || $id),
			amount => &pay_major(($session->{'amount_total'} || 0), uc($session->{'currency'} || '')), currency => uc($session->{'currency'} || ''),
			note => 'Stripe checkout',
		});
		$out->{'invoice_url'} = $back->($uuid, $cx);
		return $out;
	}
	if ($provider eq 'square') {
		my $order_id = $c->param('orderId') || $c->param('order_id') || '';
		my $uuid = $cid_uuid || $c->param('uuid') || '';
		my $cx = $cid_cx || $c->param('cx') || '';
		my $saved = &pay_session_find('square', $uuid);
		$order_id = $saved->{'order_id'} if !length $order_id && $saved;
		my $order = length $order_id ? &pay_square_order_read($order_id) : undef;
		return { ok => 0, pending => 1, uuid => $uuid, cx => $cx, invoice_url => $back->($uuid, $cx), message => 'Square has not confirmed this payment yet. Refresh this page in a moment; the invoice will update when the confirmation arrives.' } unless $order;
		my $meta = ref $order->{'metadata'} eq 'HASH' ? $order->{'metadata'} : {};
		$uuid = $meta->{'invoice_uuid'} || $order->{'reference_id'} || $uuid;
		$cx = $meta->{'cx'} || $cx;
		my $tender = ref $order->{'tenders'} eq 'ARRAY' ? ($order->{'tenders'}->[0] || {}) : {};
		if (uc($order->{'state'} || '') ne 'COMPLETED' || !$tender->{'payment_id'}) {
			return { ok => 0, pending => 1, uuid => $uuid, cx => $cx, invoice_url => $back->($uuid, $cx), message => 'Square is still processing this payment. Refresh this page in a moment; the invoice will update when it is confirmed.' };
		}
		my $money = ref $tender->{'amount_money'} eq 'HASH' ? $tender->{'amount_money'} : (ref $order->{'total_money'} eq 'HASH' ? $order->{'total_money'} : {});
		my $out = &pay_record_payment({
			uuid => $uuid, cx => $cx, provider => 'square', ref => $tender->{'payment_id'},
			amount => &pay_major(($money->{'amount'} || 0), ($money->{'currency'} || '')), currency => ($money->{'currency'} || ''),
			note => 'Square checkout',
		});
		$out->{'invoice_url'} = $back->($uuid, $cx);
		return $out;
	}
	if ($provider eq 'paypal') {
		my $order_id = $c->param('token') || '';
		my $uuid = $cid_uuid || $c->param('uuid') || '';
		my $cx = $cid_cx || $c->param('cx') || '';
		if (!length $order_id && length($uuid || '')) {
			my $saved = &pay_session_find('paypal', $uuid);
			$order_id = $saved->{'order_id'} if $saved;
		}
		my $order = length $order_id ? &pay_paypal_order_read($order_id) : undef;
		return { ok => 0, pending => 1, uuid => $uuid, cx => $cx, invoice_url => $back->($uuid, $cx), message => 'PayPal has not confirmed this payment yet. Refresh this page in a moment; the invoice will update when the confirmation arrives.' } unless $order;
		my $unit = ref $order->{'purchase_units'} eq 'ARRAY' ? ($order->{'purchase_units'}->[0] || {}) : {};
		$uuid = $unit->{'reference_id'} || $uuid;
		if (uc($order->{'status'} || '') eq 'APPROVED') {
			my $cap = &pay_paypal_capture($order_id);
			if ($cap->{'ok'}) { $order = $cap->{'data'}; }
		}
		if (uc($order->{'status'} || '') ne 'COMPLETED') {
			return { ok => 0, pending => 1, uuid => $uuid, cx => $cx, invoice_url => $back->($uuid, $cx), message => 'PayPal is still processing this payment. Refresh this page in a moment; the invoice will update when it is confirmed.' };
		}
		my $out = &pay_paypal_capture_record($order, 'PayPal checkout');
		$out->{'invoice_url'} = $back->($uuid, $cx);
		return $out;
	}
	return { ok => 0, message => 'That payment method is not available.' };
}

# A small, honest check from the panel: the key works and the provider answers.
sub pay_test_provider {
	my ($provider) = @_;
	$provider = lc($provider || '');
	if ($provider eq 'stripe') {
		my $secret = &pay_secret_read('stripe_secret');
		return { ok => 0, message => 'No secret key is set.' } unless length $secret;
		my $res = eval { &pay_ua()->get('https://api.stripe.com/v1/balance' => { Authorization => 'Bearer ' . $secret })->result };
		my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
		return { ok => ($res && $res->is_success) ? 1 : 0, message => ($res && $res->is_success) ? 'Stripe answered. The key works.' : ('Stripe: ' . ($json->{'error'}->{'message'} || 'no answer')) };
	}
	if ($provider eq 'square') {
		my $token = &pay_secret_read('square_access_token');
		return { ok => 0, message => 'No access token is set.' } unless length $token;
		my $res = eval { &pay_ua()->get(&pay_square_base() . '/v2/locations' => { Authorization => 'Bearer ' . $token })->result };
		my $json = ($res && $res->body) ? (eval { decode_json($res->body) } || {}) : {};
		if ($res && $res->is_success) {
			my $locations = ref $json->{'locations'} eq 'ARRAY' ? scalar @{ $json->{'locations'} } : 0;
			return { ok => 1, message => 'Square answered with ' . $locations . ' location' . ($locations == 1 ? '' : 's') . '.' };
		}
		my $why = ref $json->{'errors'} eq 'ARRAY' && @{ $json->{'errors'} } ? ($json->{'errors'}->[0]->{'detail'} || '') : 'no answer';
		return { ok => 0, message => 'Square: ' . $why };
	}
	if ($provider eq 'paypal') {
		my ($token, $err) = &pay_paypal_token();
		return { ok => $token ? 1 : 0, message => $token ? 'PayPal answered. The client id and secret work.' : ('PayPal: ' . ($err || 'no answer')) };
	}
	if ($provider eq 'interac') {
		my $email = &pay_setting('interac_email', '');
		return { ok => length $email ? 1 : 0, message => length $email ? 'Interac payments go to ' . $email . '.' : 'No Interac email is set.' };
	}
	return { ok => 0, message => 'Unknown payment method.' };
}

# ---- Interac e-Transfer -----------------------------------------------------
# There is no consumer API for an e-Transfer. The notification letter is the
# source of truth, so JawnOS reads the ones already arriving in the mailbox, or
# accepts the same facts from a bank/aggregator that can forward them. A letter
# is staged for a person unless the house has said auto-record, and even then
# only when one invoice is an unmistakable match.
sub pay_interac_token {
	my $t = &pay_secret_read('interac_hook_token');
	return $t if length $t && $t =~ /^[A-Za-z0-9]{20,}$/;
	$t = &random_string_creator(40);
	my $sealed = eval { &note_encrypter(&suds_grabber(), $t) };
	return '' unless defined $sealed && length $sealed;
	&setting_setter({
		app => 'pay', setting => 'interac_hook_token',
		value => $sealed, device => 'all',
	});
	return $t;
}

sub pay_interac_currency {
	my $c = uc(&pay_setting('interac_currency', 'CAD'));
	$c = 'CAD' unless $c =~ /^[A-Z]{3}$/;
	return $c;
}

sub pay_interac_looks_like {
	my ($email, $subject, $body) = @_;
	my $from = lc($email || '');
	return 1 if $from =~ /\@(?:[a-z0-9-]+\.)*interac\.ca\b/;
	my $text = lc(($subject || '') . ' ' . ($body || ''));
	return 1 if $text =~ /interac\s*e-?transfer/;
	return 1 if $text =~ /transfert\s*(?:electronique|électronique)/;
	return 0;
}

# Pull out the few facts an e-Transfer letter carries. Anything it does not
# recognise stays empty rather than guessed, so a person can still match it.
sub pay_interac_parse {
	my ($subject, $body) = @_;
	my $text = ($subject || '') . "\n" . ($body || '');
	$text =~ s/<[^>]+>/ /g;
	$text =~ s/&nbsp;/ /gi;
	$text =~ s/&amp;/&/gi;
	$text =~ s/&[a-z]+;/ /gi;
	$text =~ s/\s+/ /g;
	my $amount = '';
	if ($text =~ /(?:sent you|vous a envoyé)\s+\$?\s*([0-9][0-9.,]*[.,][0-9]{2})/i) { $amount = $1; }
	elsif ($text =~ /([0-9][0-9.,]*[.,][0-9]{2})\s*\$/) { $amount = $1; }
	elsif ($text =~ /\$([0-9][0-9,]*\.[0-9]{2})/) { $amount = $1; }
	if (length $amount) {
		if ($amount =~ /,/ && $amount =~ /\./) { $amount =~ s/,//g; }
		elsif ($amount =~ /,/) { $amount =~ s/,/./g; }
		$amount =~ s/[^0-9.]//g;
	}
	my $sender = '';
	if ($subject =~ /INTERAC\s*e-?Transfert?\s*:\s*(.+?)\s+(?:(?:has\s+)?sent you|vous a envoyé)/i) { $sender = $1; }
	elsif ($text =~ /([A-Z][A-Za-z0-9 .'-]{1,70})\s+(?:(?:has\s+)?sent you|vous a envoyé)\s+\$?[0-9]/) { $sender = $1; }
	$sender =~ s/^\s+|\s+$//g;
	my $reference = '';
	$reference = $1 if $text =~ /(?:Reference|Numéro de référence)\s*(?:Number|No\.?)?\s*:?\s*([A-Z0-9]{6,})/i;
	my $memo = '';
	$memo = $1 if $text =~ /(?:Message|Memo)\s*:?\s*(.{0,200}?)(?:\s+Reference\s|\s+Numéro de référence\s|\s+To deposit\s|\s+Pour déposer\s|\s+Autodeposit\s|\s+Dépôt automatique\s|\s+You can deposit\s|$)/i;
	$memo =~ s/^\s+|\s+$//g;
	my $deposited = ($text =~ /automatically deposited|has been deposited|deposited to your account|was deposited|automatic deposit|déposé automatiquement|a été déposé|déposé dans votre compte|dépôt automatique|dépôt direct/i) ? 1 : 0;
	my $pending = ($text =~ /security question|answer the question|to deposit your money|deposit your money|claim your money|question de sécurité|répondez à la question|pour déposer votre argent/i) ? 1 : 0;
	return {
		amount => 0 + ($amount || 0),
		sender => $sender,
		reference => $reference,
		memo => $memo,
		deposited => $deposited,
		pending => $pending,
		text => substr($text, 0, 2000),
	};
}

# Open invoices that could be the one this e-transfer is for. The score is
# deliberately simple: an invoice reference in the message is strongest, the
# exact balance next, then the sender's own address and name.
sub pay_interac_candidates {
	my ($parsed) = @_;
	$parsed ||= {};
	my $currency = &pay_interac_currency();
	my $base = &pay_currency();
	my $rate = ($currency eq $base) ? 1 : &exchange_rate($currency, $base);
	my $value = defined $rate && $rate > 0 ? ($parsed->{'amount'} || 0) * $rate : ($parsed->{'amount'} || 0);
	my $rows = &db_query("select * from appointments where type = 'invoice' order by timestamp desc limit 500")->hashes;
	my $hay = lc(join(' ', ($parsed->{'memo'} || ''), ($parsed->{'reference'} || ''), ($parsed->{'sender'} || '')));
	my @out;
	foreach my $inv ( @{$rows} ) {
		my ($data, $balance) = &pay_invoice_balance($inv);
		next if $balance <= 0.005;
		my $ref = &pay_invoice_ref($data);
		my $email = &setting_grabber({ app => $inv->{'app'}, setting => 'email' }) || '';
		my $score = 0;
		$score += 100 if length($ref || '') && index($hay, lc($ref)) >= 0;
		$score += 30 if defined $value && $value > 0 && abs($balance - $value) <= 0.01;
		$score += 20 if length($email || '') && lc($email) eq lc($parsed->{'email'} || '');
		my $name = &format_name($inv->{'app'});
		$score += 10 if length($parsed->{'sender'} || '') && (index(lc($name), lc($parsed->{'sender'})) >= 0 || index(lc($parsed->{'sender'}), lc($name)) >= 0);
		next unless $score > 0;
		push @out, {
			uuid => $inv->{'uuid'},
			id => ($data->{'id'} || $inv->{'uuid'}),
			balance => $balance,
			customer => $name,
			score => $score,
		};
	}
	@out = sort { $b->{'score'} <=> $a->{'score'} || $a->{'balance'} <=> $b->{'balance'} } @out;
	return (\@out, $value);
}

# Stage one notification. Auto-record happens only when the house asked for it,
# the money is actually deposited, and exactly one invoice names the reference.
sub pay_interac_stage {
	my ($parsed) = @_;
	$parsed ||= {};
	return { staged => 0, recorded => 0, error => 'no amount was read' } unless ($parsed->{'amount'} || 0) > 0;
	my ($candidates, $value) = &pay_interac_candidates($parsed);
	my $currency = &pay_interac_currency();
	my $key = 'interac:' . &sha256_hex(join('|',
		$parsed->{'mail_uuid'} || '', $parsed->{'reference'} || '',
		$parsed->{'amount'} || '', $parsed->{'sender'} || '', $parsed->{'memo'} || ''));
	$key = 'pay_interac:' . substr($key, 0, 56);
	my $existing = &db_select('cache', undef, { context => 'pay_interac', uuid => $key })->hashes->[0];
	return { staged => 0, recorded => 0, existing => 1 } if $existing;

	my $auto = (&pay_setting('interac_auto', 'off') eq 'on') ? 1 : 0;
	my $top = $candidates->[0];
	my $unique = (scalar @{$candidates} == 1) || ($top && (! $candidates->[1] || $top->{'score'} > $candidates->[1]->{'score'}));
	if ($auto && $parsed->{'deposited'} && $top && $unique && $top->{'score'} >= 100) {
		my $out = &pay_record_payment({
			uuid => $top->{'uuid'}, provider => 'interac',
			ref => ($parsed->{'reference'} || $parsed->{'mail_uuid'} || $key),
			amount => $parsed->{'amount'}, currency => $currency,
			note => trim_text(join(' ', 'Interac e-Transfer', ($parsed->{'sender'} ? 'from ' . $parsed->{'sender'} : ''), ($parsed->{'memo'} ? '- ' . $parsed->{'memo'} : ''))),
		});
		if ($out->{'ok'}) {
			&db_query('delete from cache where context = ? and uuid = ?', 'pay_interac', $key);
			return { staged => 0, recorded => 1, result => $out };
		}
	}

	my $now = &rightNow();
	&db_insert('cache', {
		uuid => $key,
		app => 'pay_interac',
		context => 'pay_interac',
		timestamp => $now,
		server_time => $now,
		warranty => $now + (30 * 86400000),
		data => encode_json({
			amount => ($parsed->{'amount'} || 0),
			value => $value,
			currency => $currency,
			sender => ($parsed->{'sender'} || ''),
			reference => ($parsed->{'reference'} || ''),
			memo => ($parsed->{'memo'} || ''),
			deposited => $parsed->{'deposited'} ? 1 : 0,
			pending => $parsed->{'pending'} ? 1 : 0,
			email => ($parsed->{'email'} || ''),
			mail_uuid => ($parsed->{'mail_uuid'} || ''),
			text => ($parsed->{'text'} || ''),
			candidates => $candidates,
			at => $now,
		}),
	});
	return { staged => 1, recorded => 0, key => $key, candidates => $candidates };
}

sub trim_text {
	my ($s) = @_;
	$s = '' unless defined $s;
	$s =~ s/\s+/ /g;
	$s =~ s/^\s+|\s+$//g;
	return $s;
}

sub pay_interac_scan {
	return { ok => 0, error => 'Interac e-Transfer is off' } unless &pay_on && &pay_provider_ready('interac');
	return { ok => 0, error => 'watching the inbox is off' } unless &pay_setting('interac_watch', 'off') eq 'on';
	my $suds = eval { &suds_grabber() };
	return { ok => 0, error => 'the vault is locked, so the notifications cannot be read' } unless $suds;
	my $rows = &db_query("select uuid, email, subject, body, timestamp from mailbox where status in ('inbox','archive') and email is not null and lower(email) like ? order by server_time desc limit 100", '%interac%')->hashes;
	my ($found, $staged, $recorded) = (0, 0, 0);
	foreach my $row ( @{$rows} ) {
		my $seen = &db_select('cache', undef, { context => 'pay_interac_seen', uuid => $row->{'uuid'} })->hashes->[0];
		next if $seen;
		my $subject = eval { &note_decrypter($suds, $row->{'subject'} || '') } || '';
		my $body = eval { &note_decrypter($suds, $row->{'body'} || '') } || '';
		next unless &pay_interac_looks_like($row->{'email'} || '', $subject, $body);
		$found++;
		my $parsed = &pay_interac_parse($subject, $body);
		$parsed->{'mail_uuid'} = $row->{'uuid'};
		$parsed->{'email'} = $row->{'email'} || '';
		my $out = eval { &pay_interac_stage($parsed) } || {};
		$staged++ if $out->{'staged'};
		$recorded++ if $out->{'recorded'};
		# Only mark the letter read when it produced something (a staged row, a
		# recorded payment, or a row that was already there). A letter whose body
		# could not be read is left for the next pass rather than lost.
		next unless $out->{'staged'} || $out->{'recorded'} || $out->{'existing'};
		my $now = &rightNow();
		&db_insert('cache', {
			uuid => $row->{'uuid'}, app => 'pay_interac_seen', context => 'pay_interac_seen',
			timestamp => $now, server_time => $now, warranty => $now + (30 * 86400000),
		});
	}
	&setting_setter({ app => 'pay', setting => 'interac_scanned_at', value => &rightNow(), device => 'all' });
	&db_query("delete from cache where context in ('pay_interac_seen') and cast(warranty as integer) > 0 and cast(warranty as integer) < ?", &rightNow());
	return { ok => 1, found => $found, staged => $staged, recorded => $recorded };
}

# What the panel lists: staged notifications with their best invoice matches,
# newest first. A candidate whose invoice has since been paid is dropped.
sub pay_interac_receipts {
	my $rows = &db_query("select * from cache where context = 'pay_interac' order by server_time desc limit 100")->hashes;
	my @out;
	my $now = &rightNow();
	foreach my $row ( @{$rows} ) {
		my $d = eval { decode_json($row->{'data'} || '') } || {};
		next if defined $row->{'warranty'} && $row->{'warranty'} =~ /^\d+$/ && $row->{'warranty'} < $now;
		my @cands;
		foreach my $c ( @{ ref $d->{'candidates'} eq 'ARRAY' ? $d->{'candidates'} : [] } ) {
			my $inv = &db_select('appointments', undef, { uuid => $c->{'uuid'} })->hashes->[0];
			next unless $inv;
			my ($data, $balance) = &pay_invoice_balance($inv);
			next if $balance <= 0.005;
			push @cands, {
				uuid => $inv->{'uuid'},
				id => ($data->{'id'} || $inv->{'uuid'}),
				customer => &format_name($inv->{'app'}),
				balance => $balance,
				score => ($c->{'score'} || 0),
			};
		}
		@cands = sort { $b->{'score'} <=> $a->{'score'} || $a->{'balance'} <=> $b->{'balance'} } @cands;
		push @out, {
			id => $row->{'uuid'},
			at => ($d->{'at'} || $row->{'server_time'} || 0),
			amount => ($d->{'amount'} || 0),
			value => ($d->{'value'} || 0),
			currency => ($d->{'currency'} || 'CAD'),
			sender => ($d->{'sender'} || ''),
			reference => ($d->{'reference'} || ''),
			memo => ($d->{'memo'} || ''),
			deposited => ($d->{'deposited'} ? 1 : 0),
			pending => ($d->{'pending'} ? 1 : 0),
			email => ($d->{'email'} || ''),
			candidates => \@cands,
		};
	}
	return \@out;
}

sub pay_interac_record {
	my ($id, $uuid, $actor) = @_;
	return { ok => 0, error => 'no notification was named' } unless defined $id && length $id;
	my $row = &db_select('cache', undef, { context => 'pay_interac', uuid => $id })->hashes->[0];
	return { ok => 0, error => 'that notification is no longer waiting' } unless $row;
	my $d = eval { decode_json($row->{'data'} || '') } || {};
	if (!length($uuid || '')) {
		my $top = ref $d->{'candidates'} eq 'ARRAY' ? $d->{'candidates'}->[0] : undef;
		$uuid = $top ? $top->{'uuid'} : '';
	}
	return { ok => 0, error => 'choose the invoice this e-transfer settles' } unless length($uuid || '');
	my $out = &pay_record_payment({
		uuid => $uuid, provider => 'interac',
		ref => ($d->{'reference'} || $d->{'mail_uuid'} || $id),
		amount => ($d->{'amount'} || 0), currency => ($d->{'currency'} || 'CAD'),
		note => trim_text(join(' ', 'Interac e-Transfer', ($d->{'sender'} ? 'from ' . $d->{'sender'} : ''), ($d->{'memo'} ? '- ' . $d->{'memo'} : ''), ($actor ? 'recorded by ' . $actor : ''))),
	});
	if ($out->{'ok'}) {
		&db_query('delete from cache where context = ? and uuid = ?', 'pay_interac', $id);
	}
	return $out;
}

sub pay_interac_ignore {
	my ($id) = @_;
	return { ok => 0, error => 'no notification was named' } unless defined $id && length $id;
	&db_query('delete from cache where context = ? and uuid = ?', 'pay_interac', $id);
	return { ok => 1 };
}

# A bank or aggregator that can see e-Transfer notifications posts the same
# facts here. The task token is the gate, exactly like the LoRaWAN uplink.
sub pay_interac_hook {
	my ($body, $token, $c) = @_;
	$body = {} unless ref $body eq 'HASH';
	my $want = &pay_interac_token();
	return { ok => 0, error => 'bad token' } unless length($want || '')
		&& length($token || '') && &secure_compare($token, $want);
	return { ok => 0, error => 'Interac e-Transfer is off' } unless &pay_on && &pay_provider_ready('interac');
	my $parsed = {
		amount => 0 + (($body->{'amount'} || '') =~ /([0-9]+(?:\.[0-9]+)?)/ ? $1 : 0),
		sender => trim_text($body->{'sender'} || ''),
		reference => trim_text($body->{'reference'} || ''),
		memo => trim_text($body->{'memo'} || $body->{'message'} || ''),
		deposited => ($body->{'deposited'} ? 1 : 0),
		pending => ($body->{'pending'} ? 1 : 0),
		email => trim_text($body->{'email'} || ''),
		text => trim_text($body->{'text'} || ''),
	};
	return { ok => 0, error => 'the notification has no amount' } unless $parsed->{'amount'} > 0;
	if (length($body->{'invoice'} || '')) {
		$parsed->{'memo'} = trim_text($parsed->{'memo'} . ' ' . $body->{'invoice'});
	}
	my $out = &pay_interac_stage($parsed);
	return { ok => 1, %{$out} };
}

# ---------------------------------------------------------------------------
# The Clock app: alarms, timers, and the little that has to live server-side.
#
# Alarms and timers are rows in the `settings` table under app 'clock' so they
# survive a restart and ride the house's usual per-device sync. They are small
# JSON arrays, capped at ten each. Every read-modify-write takes one flock so a
# web worker saving an alarm cannot lose the alarm the firing loop just marked,
# and the firing loop itself runs from Alarm.pl.
# ---------------------------------------------------------------------------

my @clock_sound_files = qw/chime.mp3 crystal.mp3 ding.mp3 pulse.mp3 rattle.mp3 ring.mp3 sonar.mp3/;
# Long-form alarm tracks, kept under public/sounds/alarms/ and served to the
# operating system's player. The labels are the titles the recordings came with.
my %clock_long_alarm_files = (
	'bros-and-monks-2.mp3' => 'Bros and Monks 2',
	'bros-and-monks.mp3' => 'Bros and Monks',
	'dolphin-chorus-singers-reuniting-tour.mp3' => 'Dolphin Chorus Singers Reuniting Tour',
	'find-the-ship-learn-from-it.mp3' => 'Find the Ship, Learn From It',
	'going-to-work-in-the-battery-factory.mp3' => 'Going to work in the battery factory',
	'it-feels-so-right.mp3' => 'It Feels so Right',
	'mans-gotta-bellow.mp3' => 'Man\'s Gotta Bellow!',
	'music-to-gel-your-hair-to.mp3' => 'Music to gel your hair to',
	'music-to-grow-a-mullet-to.mp3' => 'Music to grow a mullet to',
	'our-heads-will-stay-up.mp3' => 'Our Heads Will Stay Up',
	'the-hero-always-gets-the-squirrel.mp3' => 'The Hero Always Gets the Squirrel',
	'we-celebrate-the-lives-of-those-with-gum-disease.mp3' => 'We Celebrate the Lives of Those with Gum Disease',
	'were-all-professionals-here.mp3' => 'We\'re all Professionals Here',
);
our ($clock_apps_memo, $clock_apps_memo_at, $clock_apps_memo_images);

sub clock_device() {
	return &device_setter();
}

# Alarms are the house's, not one machine's: they live in a single settings row
# every machine reads, and each alarm names the machines that should ring it.
# Timers stay on the machine that started them (they are a countdown in a hand).
sub clock_alarm_store_device() {
	return 'house';
}

# The machines an alarm can be shared with: this machine ("Me") first, then
# every peer the mesh knows. The value is the machine's signatorial, because
# that is the identity each machine compares against its own.
sub clock_machines() {
	my $self = &signatorial_designer() || '';
	my @out;
	if (length $self) {
		push @out, { value => $self, label => &lang('me'), device => &clock_device(), me => 1 };
	}
	my %seen = ($self => 1);
	my $rows = eval { &db_query('select hostname, fqdn, signatorial, device from remote_machines order by hostname')->hashes } || [];
	foreach my $r (@{ $rows || [] }) {
		my $sig = $r->{'signatorial'} || '';
		next unless length $sig;
		next if $seen{$sig}++;
		# Android answers `hostname` with 'localhost', so a phone and a tablet
		# both look like the same machine. The fqdn still says which is which.
		my $label = &device_hostname_better($r->{'hostname'}, '', $r->{'fqdn'});
		$label =~ s/^\s+|\s+$//g;
		$label = &format_name($label) if length $label;
		$label = $sig unless length $label;
		push @out, { value => $sig, label => $label, device => ($r->{'device'} || ''), me => 0 };
	}
	return \@out;
}

# Does this alarm ring on this machine? An empty list is an alarm from before
# sharing: every machine that held the row rang it, so keep that reading.
sub clock_alarm_targets_me {
	my $alarm = shift;
	my $machines = $alarm->{'machines'};
	return 1 unless ref $machines eq 'ARRAY' && scalar @{$machines};
	my $self = &signatorial_designer() || '';
	return 0 unless length $self;
	return scalar grep { defined $_ && $_ eq $self } @{$machines};
}

sub clock_sounds() {
	return [ @clock_sound_files ];
}

# The alarm picker's library: the short chimes first, then the long recordings.
sub clock_alarm_sounds() {
	my @out;
	foreach my $s (@clock_sound_files) {
		my $label = $s;
		$label =~ s/\.mp3$//;
		$label = ucfirst $label;
		push @out, { value => 'notifications/' . $s, label => $label };
	}
	foreach my $s (sort { lc($clock_long_alarm_files{$a}) cmp lc($clock_long_alarm_files{$b}) } keys %clock_long_alarm_files) {
		push @out, { value => 'alarms/' . $s, label => $clock_long_alarm_files{$s} };
	}
	return \@out;
}

sub clock_sound_is_long {
	my $sound = shift;
	return 0 unless defined $sound && length $sound;
	return $sound =~ m{^alarms/} ? 1 : 0;
}

# A stored alarm may be a chime's bare name from before the library grew, a
# notifications/ path, or a long alarms/ path. Everything else is refused.
sub clock_valid_alarm_sound {
	my $sound = shift;
	return '' unless defined $sound && length $sound;
	$sound =~ s{^\./}{};
	$sound =~ s{^/}{};
	if ($sound =~ m{^(.*/)?([^/]+\.mp3)$}) {
		my $dir = $1 || '';
		my $base = $2;
		return 'alarms/' . $base if $dir eq 'alarms/' && exists $clock_long_alarm_files{$base};
		if (($dir eq 'notifications/' || $dir eq '') && grep { $_ eq $base } @clock_sound_files) {
			return 'notifications/' . $base;
		}
	}
	return '';
}

sub clock_valid_timer_sound {
	my $sound = shift;
	return 'notifications/chime.mp3' unless defined $sound && length $sound;
	$sound =~ s{^\./}{};
	$sound =~ s{^/}{};
	$sound =~ s{^notifications/}{};
	return 'notifications/' . $sound if grep { $_ eq $sound } @clock_sound_files;
	return 'notifications/chime.mp3';
}

sub clock_valid_sound {
	my $sound = shift;
	return '' unless defined $sound && length $sound;
	return (grep { $_ eq $sound } @clock_sound_files) ? $sound : '';
}

sub clock_sound_file {
	my $sound = shift;
	return './public/sounds/notifications/ring.mp3' unless defined $sound && length $sound;
	return './public/sounds/' . $sound;
}

sub clock_alarm_pidfile {
	my $uuid = shift || 'x';
	$uuid =~ s/[^A-Za-z0-9_\-]//g;
	my $dir = &home('~/.president');
	$dir = '/tmp' unless -d $dir;
	return $dir . '/clock_alarm_' . $uuid . '.pid';
}

# A long-form track is one process; Dismiss kills it through the pid its shell
# wrote when it started. A short chime finishes on its own and has no pid file.
sub clock_alarm_stop_sound {
	my $uuid = shift;
	return 0 unless defined $uuid && length $uuid;
	my $file = &clock_alarm_pidfile($uuid);
	return 0 unless -e $file;
	my $pid = eval { read_file($file) };
	unlink $file;
	return 0 unless defined $pid;
	$pid =~ s/\D//g;
	return 0 unless length $pid;
	# A stale pid file after a reboot must not kill whatever inherited the number.
	# The player's command line still names play and the sounds directory.
	if (-e '/proc/' . $pid . '/cmdline') {
		my $cmdline = eval { read_file('/proc/' . $pid . '/cmdline') } // '';
		return 0 unless $cmdline =~ /play/ && $cmdline =~ m{public/sounds};
	}
	else {
		return 0;
	}
	eval { kill 'TERM', $pid; };
	eval { kill 'KILL', $pid; };
	return 1;
}

# A ringtone preview is the alarm's own sound, played on this machine for a
# few seconds while the person chooses. It is one process at a time, so
# auditioning the next sound ends the last one.
sub clock_preview_pidfile() {
	my $dir = &home('~/.president');
	eval { File::Path::make_path($dir); } unless -d $dir;
	$dir = '/tmp' unless -d $dir;
	return $dir . '/clock_preview.pid';
}

sub clock_preview_stop {
	my $file = &clock_preview_pidfile();
	if (&device_setter() eq 'mobile') {
		&clock_device_broadcast('com.termux.app.JAWN_CLOCK_PREVIEW', stop => 1);
	}
	return 0 unless -e $file;
	my $pid = eval { read_file($file) };
	unlink $file;
	return 0 unless defined $pid;
	$pid =~ s/\D//g;
	return 0 unless length $pid;
	return 0 unless -e '/proc/' . $pid;
	# The preview's timeout command line names the player and the sounds
	# directory; a recycled pid after a reboot does not.
	my $cmdline = eval { read_file('/proc/' . $pid . '/cmdline') } // '';
	return 0 unless $cmdline =~ /play/ && $cmdline =~ m{public/sounds};
	eval { kill 'TERM', $pid; };
	eval { kill 'KILL', $pid; };
	return 1;
}

sub clock_preview_play {
	my ($sound, $volume) = @_;
	$sound = &clock_valid_alarm_sound($sound) || 'notifications/ring.mp3';
	$volume = 70 unless defined $volume && "$volume" =~ /^\d+$/;
	$volume = 5 if $volume < 5;
	$volume = 100 if $volume > 100;
	&clock_preview_stop();
	if (&device_setter() eq 'mobile') {
		# The app plays it on the alarm channel, as it plays the ring itself.
		&clock_device_broadcast('com.termux.app.JAWN_CLOCK_PREVIEW',
			uuid => 'preview',
			file => 'public/sounds/' . $sound,
			volume => $volume,
			ramp => 0,
			loop => 0,
			guard => 10000,
		);
		return 1;
	}
	my $file = &clock_sound_file($sound);
	my $level = sprintf('%.2f', $volume / 100);
	# timeout is the stop that a forgotten preview cannot outlive; the pid file
	# is what a second press, or another sound, uses to end it early.
	my $command = 'timeout 10 play -q -v ' . $level . ' ' . &quote($file) . ' fade t 1';
	my $pidfile = &clock_preview_pidfile();
	eval {
		&subprocessor(sub {
			system('sh', '-c', $command . ' & echo $! > ' . &quote($pidfile));
		}, { name => 'clock preview' });
	};
	return 1;
}

# The phone app is the only device that can wake itself from Doze and put an
# alarm in front of a locked screen. jawn hands it both the next alarm and the
# moment one rings over these short broadcasts; the app's receivers do the rest.
sub clock_device_broadcast {
	my ($action, %extra) = @_;
	return 0 unless &device_setter() eq 'mobile';
	my $command = 'am broadcast -a ' . $action;
	if (defined $extra{'at'} && "$extra{'at'}" =~ /^\d+$/ && $extra{'at'} > 0) {
		$command .= ' --el at ' . int($extra{'at'});
	}
	foreach my $key ( qw/uuid label app file play nfc_action reason/ ) {
		my $value = $extra{$key};
		next unless defined $value && length $value;
		$command .= ' --es ' . $key . ' ' . &quote($value);
	}
	foreach my $key ( qw/volume ramp loop guard snooze nfc stop/ ) {
		my $value = $extra{$key};
		next unless defined $value && "$value" =~ /^-?\d+$/;
		$command .= ' --ei ' . $key . ' ' . int($value);
	}
	eval {
		&subprocessor(sub { `$command`; }, { name => 'clock device broadcast' });
	};
	return 1;
}

# Write the next alarm for the app, and only broadcast when it really moved.
# The file is what survives a reboot; the broadcast is what arms it now.
sub clock_write_device_alarm {
	my ($alarms, $now) = @_;
	$now = &rightNow() unless defined $now;
	my ($next, $next_alarm);
	foreach my $alarm (@{ $alarms || [] }) {
		# A ringing alarm has already woken the phone; the next one is what the
		# app should arm now. Only an alarm this machine carries is armed here.
		next unless &clock_alarm_targets_me($alarm);
		next if $alarm->{'ringing'};
		my $candidate;
		if ($alarm->{'snooze_until'} && $alarm->{'snooze_until'} > $now) {
			$candidate = $alarm->{'snooze_until'};
		}
		elsif ($alarm->{'enabled'}) {
			my $from = $now;
			$from = $alarm->{'skip_fire'} if $alarm->{'skip_fire'} && $alarm->{'skip_fire'} > $now;
			$candidate = &clock_alarm_next_ms($alarm, $from);
		}
		next unless $candidate;
		if (!$next || $candidate < $next) {
			$next = $candidate;
			$next_alarm = $alarm;
		}
	}
	my $file = &home('~/.president/clock_alarm.json');
	my $payload;
	if ($next && $next_alarm) {
		my $sound = &clock_valid_alarm_sound($next_alarm->{'sound'}) || 'notifications/ring.mp3';
		$payload = {
			at => $next,
			uuid => ($next_alarm->{'uuid'} || ''),
			label => ($next_alarm->{'label'} || ''),
			app => ($next_alarm->{'app'} || ''),
			# The phone plays this itself on the alarm channel; the kind of
			# sound and its ramp ride along so a reboot or an exact wake has
			# them without another broadcast.
			file => 'public/sounds/' . $sound,
			volume => int($next_alarm->{'volume'} || 70),
			ramp => int($next_alarm->{'ramp'} || 0),
			# Every alarm sound repeats now: a long recording loops at the alarm's
			# volume, a chime loops on the alarm channel. Dismiss/Snooze, or the
			# five-minute guard, is what ends it.
			loop => 1,
			snooze => int($next_alarm->{'snooze'} || 5),
			play => ($next_alarm->{'play'} || ''),
			nfc => (($next_alarm->{'nfc'} || 0) && &clock_app_has_nfc_start($next_alarm->{'app'})) ? 1 : 0,
			nfc_action => ($next_alarm->{'nfc_action'} || 'snooze'),
			guard => &clock_alarm_ring_length($next_alarm),
		};
	}
	my $json = $payload ? encode_json($payload) : '';
	my $old = -e $file ? (eval { read_file($file) } // '') : '';
	return 0 if $old eq $json;
	if (length $json) {
		eval { write_file($file, $json); };
	}
	else {
		unlink $file;
	}
	&clock_device_broadcast('com.termux.app.JAWN_CLOCK_SYNC', %{ $payload || {} });
	return 1;
}

sub clock_device_ring {
	my ($alarm, $fire_at) = @_;
	return 0 unless $alarm;
	my $sound = &clock_valid_alarm_sound($alarm->{'sound'}) || 'notifications/ring.mp3';
	# The phone plays this itself, on the alarm channel: a chime repeats until
	# Dismiss, and a long track plays once at the alarm's own volume.
	&clock_device_broadcast('com.termux.app.JAWN_CLOCK_RING',
		uuid => ($alarm->{'uuid'} || ''),
		label => ($alarm->{'label'} || ''),
		app => ($alarm->{'app'} || ''),
		at => ($fire_at || &rightNow()),
		file => 'public/sounds/' . $sound,
		volume => int($alarm->{'volume'} || 70),
		ramp => int($alarm->{'ramp'} || 0),
		loop => 1,
		snooze => int($alarm->{'snooze'} || 5),
		play => ($alarm->{'play'} || ''),
		nfc => (($alarm->{'nfc'} || 0) && &clock_app_has_nfc_start($alarm->{'app'})) ? 1 : 0,
		nfc_action => ($alarm->{'nfc_action'} || 'snooze'),
		guard => &clock_alarm_ring_length($alarm),
	);
	return 1;
}

# A timer's chime is the same promise as an alarm's; it goes through the same
# alarm channel on a phone rather than the notification stream.
sub clock_device_timer {
	my $timer = shift;
	return 0 unless $timer;
	my $sound = &clock_valid_timer_sound($timer->{'sound'});
	&clock_device_broadcast('com.termux.app.JAWN_CLOCK_TIMER',
		uuid => ($timer->{'uuid'} || ''),
		label => ($timer->{'label'} || ''),
		app => ($timer->{'app'} || ''),
		at => ($timer->{'ends_at'} || &rightNow()),
		file => 'public/sounds/' . $sound,
		volume => 70,
		ramp => 0,
		loop => 0,
		guard => 60000,
	);
	return 1;
}

sub clock_device_dismissed {
	my $uuid = shift;
	&clock_device_broadcast('com.termux.app.JAWN_CLOCK_DISMISSED', uuid => ($uuid || ''));
	return 1;
}

sub clock_lock_path() {
	my $dir = &home('~/.president');
	unless (-d $dir) {
		eval { File::Path::make_path($dir); };
	}
	$dir = '/tmp' unless -d $dir;
	return $dir . '/.clock_lock';
}

sub clock_lock_take() {
	my $path = &clock_lock_path();
	my $fh;
	open($fh, '>>', $path) or return undef;
	flock($fh, LOCK_EX) or do { close($fh); return undef; };
	return $fh;
}

sub clock_lock_drop {
	my $fh = shift;
	return unless $fh;
	flock($fh, LOCK_UN);
	close($fh);
}

sub clock_normalize_alarm {
	my $in = shift;
	$in = {} unless ref $in eq 'HASH';
	my @raw_days = ref $in->{'days'} eq 'ARRAY' ? @{ $in->{'days'} } : split /,/, ($in->{'days'} // '');
	my (@days, %seen);
	foreach my $d (@raw_days) {
		next unless defined $d && "$d" =~ /^\d+$/;
		$d = int($d);
		next if $d < 0 || $d > 6 || $seen{$d}++;
		push @days, $d;
	}
	@days = sort { $a <=> $b } @days;
	my $hour = (defined $in->{'hour'} && "$in->{'hour'}" =~ /^\d+$/) ? int($in->{'hour'}) : 7;
	my $minute = (defined $in->{'minute'} && "$in->{'minute'}" =~ /^\d+$/) ? int($in->{'minute'}) : 0;
	$hour = 23 if $hour > 23;
	$minute = 59 if $minute > 59;
	my $volume = (defined $in->{'volume'} && "$in->{'volume'}" =~ /^\d+$/) ? int($in->{'volume'}) : 70;
	$volume = 5 if $volume < 5;
	$volume = 100 if $volume > 100;
	my $ramp = (defined $in->{'ramp'} && "$in->{'ramp'}" =~ /^\d+$/) ? int($in->{'ramp'}) : 60;
	$ramp = 0 if $ramp < 0;
	$ramp = 600 if $ramp > 600;
	my $label = defined $in->{'label'} ? "$in->{'label'}" : 'Alarm';
	$label =~ s/^\s+//;
	$label =~ s/\s+$//;
	# The name sits beside a wide time field; twenty characters is all the row
	# can show, and nobody needs a sentence here.
	$label = substr($label, 0, 20);
	$label = 'Alarm' unless length $label;
	my $sound = &clock_valid_alarm_sound($in->{'sound'}) || 'notifications/ring.mp3';
	# How long Snooze waits. Each alarm carries its own length so a morning alarm
	# and a nap alarm can differ; five minutes is the old fixed behaviour.
	my $snooze = (defined $in->{'snooze'} && "$in->{'snooze'}" =~ /^\d+$/) ? int($in->{'snooze'}) : 5;
	$snooze = 1 if $snooze < 1;
	$snooze = 60 if $snooze > 60;
	# Play mode is the first step towards a wake-up game. Only math exists now;
	# an unknown value reads as none so an old client cannot arm a puzzle the
	# alarm screen does not know how to draw.
	my $play = (($in->{'play'} // '') eq 'math') ? 'math' : '';
	# NFC requires a tag assigned to the linked app. The action is what the tag
	# does when it is scanned; snooze is the old default and dismiss is the
	# Tasker-style "get out of bed" choice.
	my $nfc = ($in->{'nfc'} && $in->{'nfc'} ne '0' && $in->{'nfc'} ne 'off') ? 1 : 0;
	my $nfc_action = (($in->{'nfc_action'} // '') eq 'dismiss') ? 'dismiss' : 'snooze';
	my $enabled = defined $in->{'enabled'} ? (($in->{'enabled'} && $in->{'enabled'} ne '0' && $in->{'enabled'} ne 'off') ? 1 : 0) : 1;
	my $self = &signatorial_designer() || '';
	my @raw_machines = ref $in->{'machines'} eq 'ARRAY' ? @{ $in->{'machines'} } : split /,/, ($in->{'machines'} // '');
	my (@machines, %seen_machine);
	foreach my $m (@raw_machines) {
		next unless defined $m;
		$m =~ s/^\s+|\s+$//g;
		next unless length $m && $m =~ /^[A-Za-z0-9_\-]{1,64}$/;
		$m = $self if $m eq 'me' && length $self;
		next if $seen_machine{$m}++;
		push @machines, $m;
	}
	return {
		uuid => ($in->{'uuid'} // ''),
		hour => $hour,
		minute => $minute,
		days => \@days,
		enabled => $enabled,
		label => $label,
		app => ($in->{'app'} // ''),
		sound => $sound,
		volume => $volume,
		ramp => $ramp,
		snooze => $snooze,
		play => $play,
		nfc => $nfc,
		nfc_action => $nfc_action,
		machines => \@machines,
		# An alarm written from a future appointment points back at it, so the next
		# appointment replaces the same Clock row instead of adding another one.
		appt_uuid => ($in->{'appt_uuid'} // ''),
		source => ($in->{'source'} // ''),
		updated => int($in->{'updated'} || 0),
		last_fire => int($in->{'last_fire'} || 0),
		snooze_until => int($in->{'snooze_until'} || 0),
		skip_fire => int($in->{'skip_fire'} || 0),
		stop_at => int($in->{'stop_at'} || 0),
		ringing => ($in->{'ringing'} ? 1 : 0),
		ring_started => int($in->{'ring_started'} || 0),
		ring_last => int($in->{'ring_last'} || 0),
		created => int($in->{'created'} || 0),
	};
}

sub clock_normalize_timer {
	my $t = shift;
	$t = {} unless ref $t eq 'HASH';
	my $seconds = (defined $t->{'seconds'} && "$t->{'seconds'}" =~ /^\d+$/) ? int($t->{'seconds'}) : 300;
	$seconds = 1 if $seconds < 1;
	$seconds = 359999 if $seconds > 359999;
	my $label = defined $t->{'label'} ? "$t->{'label'}" : 'Timer';
	$label =~ s/^\s+//;
	$label =~ s/\s+$//;
	$label = substr($label, 0, 120);
	$label = 'Timer' unless length $label;
	my $state = $t->{'state'} // 'running';
	$state = 'running' unless grep { $_ eq $state } qw/running done cancelled/;
	return {
		uuid => ($t->{'uuid'} // ''),
		label => $label,
		seconds => $seconds,
		started_at => int($t->{'started_at'} || 0),
		ends_at => int($t->{'ends_at'} || 0),
		ended_at => int($t->{'ended_at'} || 0),
		state => $state,
		app => ($t->{'app'} // ''),
		appt_uuid => ($t->{'appt_uuid'} // ''),
		sound => &clock_valid_timer_sound($t->{'sound'}),
		created => int($t->{'created'} || 0),
	};
}

# The house alarm list. Before sharing, each machine kept its own row under its
# device type; a new install would see only its own. The first read moves every
# such row into the single house row, and those alarms are addressed to the
# machine doing the moving ("Me").
sub clock_alarms_migrate {
	my $store = &clock_alarm_store_device();
	my $rows = eval { &db_query('select value, device, server_time from settings where app = ? and setting = ? and device != ? order by cast(server_time as integer) asc', 'clock', 'alarms', $store)->hashes } || [];
	my $self = &signatorial_designer() || '';
	my (@out, %seen);
	foreach my $r (@{ $rows || [] }) {
		my $list = eval { decode_json($r->{'value'} || '') } || [];
		next unless ref $list eq 'ARRAY';
		foreach my $a (@{ $list }) {
			next unless ref $a eq 'HASH';
			my $alarm = &clock_normalize_alarm($a);
			next unless length($alarm->{'uuid'} || '');
			next if $seen{$alarm->{'uuid'}}++;
			$alarm->{'machines'} = [ $self ] if (!scalar @{ $alarm->{'machines'} || [] }) && length $self;
			push @out, $alarm;
		}
	}
	my $json = encode_json(\@out);
	eval { &setting_setter({ app => 'clock', setting => 'alarms', value => $json, device => $store }) };
	return $json;
}

sub clock_alarms_read() {
	my $raw = eval { &setting_grabber({ app => 'clock', setting => 'alarms', device => &clock_alarm_store_device() }) };
	unless (defined $raw && length $raw) {
		$raw = eval { &clock_alarms_migrate() };
	}
	my $list = (defined $raw && length $raw) ? eval { decode_json($raw) } : [];
	$list = [] unless ref $list eq 'ARRAY';
	return [ map { &clock_normalize_alarm($_) } @{$list} ];
}

sub clock_timers_read() {
	my $raw = eval { &setting_grabber({ app => 'clock', setting => 'timers', device => &clock_device() }) };
	my $list = (defined $raw && length $raw) ? eval { decode_json($raw) } : [];
	$list = [] unless ref $list eq 'ARRAY';
	return [ map { &clock_normalize_timer($_) } @{$list} ];
}

sub clock_alarms_write {
	my $alarms = shift;
	my $json = encode_json($alarms || []);
	&setting_setter({ app => 'clock', setting => 'alarms', value => $json, device => &clock_alarm_store_device() });
	return $alarms;
}

sub clock_timers_write {
	my $timers = shift;
	my $json = encode_json($timers || []);
	&setting_setter({ app => 'clock', setting => 'timers', value => $json, device => &clock_device() });
	return $timers;
}

# The next moment an alarm is due, strictly after $from. A day list of none is a
# one-shot: the next such time, whatever day it lands on. The caller decides what
# to do with a moment that has just gone by (the firing loop allows two minutes).
sub clock_alarm_next_ms {
	my ($alarm, $from) = @_;
	my $hour = int($alarm->{'hour'} || 0);
	my $minute = int($alarm->{'minute'} || 0);
	my @days = @{ $alarm->{'days'} || [] };
	$from = &rightNow() unless defined $from;
	my @lt = localtime(int($from / 1000));
	my ($mday, $mon, $year) = @lt[3, 4, 5];
	for my $offset (0 .. 8) {
		# POSIX::mktime normalises a day past the end of the month (Oct 31 + 1
		# is Nov 1). Time::Local::timelocal croaks on day 32, which made the
		# whole Clock state 500 for the last week of every month.
		my $candidate = POSIX::mktime(0, $minute, $hour, $mday + $offset, $mon, $year) * 1000;
		next if $candidate <= $from;
		if (!scalar @days) { return $candidate; }
		my @d = localtime(int($candidate / 1000));
		return $candidate if grep { $_ == $d[6] } @days;
	}
	return undef;
}

sub clock_next_wake {
	my ($alarms, $timers, $now, $rings) = @_;
	$now = &rightNow() unless defined $now;
	my $next;
	foreach my $a (@{ $alarms || [] }) {
		next unless &clock_alarm_targets_me($a);
		my $candidate;
		if ($a->{'ringing'}) {
			# A chime repeats every fifteen seconds; a long track plays once and
			# only needs a wake at the guard to clear the ring state. The machine's
			# own ring record says when it last sounded, since the shared row is
			# not rewritten on every repetition.
			my $ring = ref $rings eq 'HASH' ? $rings->{ $a->{'uuid'} } : undef;
			my $started = (ref $ring eq 'HASH' && $ring->{'started'}) ? $ring->{'started'} : ($a->{'ring_started'} || $now);
			my $last = (ref $ring eq 'HASH' && $ring->{'last'}) ? $ring->{'last'} : ($a->{'ring_last'} || $now);
			my $end = $started + &clock_alarm_ring_length($a);
			if (&clock_sound_is_long($a->{'sound'})) {
				$candidate = $end;
			}
			else {
				$candidate = $last + 15000;
				$candidate = $end if $end < $candidate;
			}
			$candidate = $now + 1000 if $candidate <= $now;
			$next = $candidate if $candidate && (!$next || $candidate < $next);
			next;
		}
		if ($a->{'snooze_until'} && $a->{'snooze_until'} > $now) {
			$candidate = $a->{'snooze_until'};
		}
		elsif ($a->{'enabled'}) {
			my $from = $now;
			$from = $a->{'skip_fire'} if $a->{'skip_fire'} && $a->{'skip_fire'} > $now;
			$candidate = &clock_alarm_next_ms($a, $from);
		}
		$next = $candidate if $candidate && (!$next || $candidate < $next);
	}
	foreach my $t (@{ $timers || [] }) {
		next unless ($t->{'state'} || '') eq 'running';
		my $candidate = $t->{'ends_at'};
		$next = $candidate if $candidate && (!$next || $candidate < $next);
	}
	return $next;
}

# Nudge the alarm worker so a save, a start or a cancel is reflected at once
# rather than at the appointment it was already sleeping toward.
sub clock_poke {
	my $timestamp = shift;
	$timestamp = &rightNow() unless defined $timestamp;
	eval { &appt_alarm_setter({ uuid => 'clock', timestamp => $timestamp }) };
	return 1;
}

sub clock_apps {
	my $now = &rightNow();
	my $memo = ($clock_apps_memo && $clock_apps_memo_at && ($now - $clock_apps_memo_at) < 60000) ? $clock_apps_memo : undef;
	my (@out, %seen);
	foreach my $name (qw/me misc music_folder_toggle teletype __president __DEBRIEFING__/) { $seen{$name} = 1; }
	if ($memo) {
		@out = @{ $memo };
		foreach my $row (@out) { $seen{$row->{'value'}} = 1; }
	}
	else {
		# A hidden appointment must not be offered for linking. Visibility is a
		# setting per app ("visible" = unchecked is hidden) and this machine's own
		# row wins over the person's.
		my $device = &clock_device();
		my %visible;
		my $vis_rows = eval { &db_query("select app, device, value from settings where setting = 'visible' and device in (?, 'me')", $device)->hashes } || [];
		foreach my $v (@{ $vis_rows || [] }) {
			my $a = $v->{'app'};
			next unless defined $a && length $a;
			if (($v->{'device'} || '') eq $device) { $visible{$a} = $v->{'value'}; }
			elsif (!exists $visible{$a}) { $visible{$a} = $v->{'value'}; }
		}
		# One query for the album art the icon maker would otherwise ask for
		# app by app.
		my %main_image;
		my $img_rows = eval { &db_query("select app, device, value from settings where setting = 'main_image' and device in (?, 'me')", $device)->hashes } || [];
		foreach my $v (@{ $img_rows || [] }) {
			my $a = $v->{'app'};
			next unless defined $a && length $a && length($v->{'value'} || '');
			if (($v->{'device'} || '') eq $device) { $main_image{$a} = $v->{'value'}; }
			elsif (!exists $main_image{$a}) { $main_image{$a} = $v->{'value'}; }
		}
		# The most recently used appointments make a useful picker without
		# shipping the whole history: a house can name thousands of things and
		# only the last hundred and fifty are likely to be linked to a clock.
		my $rows = eval {
			return &db_query('select app, max(timestamp) as last from appointments where app is not null and app != ? group by app order by last desc limit 150', '')->hashes;
		} || [];
		foreach my $r (@{ $rows || [] }) {
			my $a = $r->{'app'};
			next unless defined $a && length $a;
			next if $a =~ /^__/;
			next if &app_hidden_now($a);
			next if $seen{$a}++;
			push @out, { value => $a, label => &format_name($a) };
		}
		@out = sort { lc($a->{'label'}) cmp lc($b->{'label'}) } @out;
		$clock_apps_memo = [ @out ];
		$clock_apps_memo_at = $now;
		$clock_apps_memo_images = { %main_image };
	}
	my $images = $clock_apps_memo_images || {};
	# a link already on an alarm or timer stays offered even before that app has
	# written an appointment of its own
	foreach my $row (@{ &clock_alarms_read() }, @{ &clock_timers_read() }) {
		my $a = $row->{'app'};
		next unless defined $a && length $a;
		next if $seen{$a}++;
		push @out, { value => $a, label => &format_name($a) };
	}
	@out = sort { lc($a->{'label'}) cmp lc($b->{'label'}) } @out;
	# The picker is a list of rows, not a datalist: each one carries the icon the
	# app wears elsewhere in the house, so a person recognises it at a glance.
	my $n = 0;
	foreach my $row (@out) {
		$n++;
		next if defined $row->{'icon'} && length $row->{'icon'};
		$row->{'icon'} = &main_icon_maker({
			app => $row->{'value'},
			timestamp => $now + $n,
			size => 'little',
			onclick => ' ',
			hint => $row->{'label'},
			settings => { main_image => ($images->{$row->{'value'}} || '') },
		});
	}
	return \@out;
}

# The moment an alarm will next run, for the row's countdown. A snooze is the
# next run; a skipped occurrence is not, so the search starts past it.
sub clock_alarm_next_at {
	my ($alarm, $now) = @_;
	$now = &rightNow() unless defined $now;
	return $alarm->{'snooze_until'} if $alarm->{'snooze_until'} && $alarm->{'snooze_until'} > $now;
	return 0 unless $alarm->{'enabled'};
	my $from = $now;
	$from = $alarm->{'skip_fire'} if $alarm->{'skip_fire'} && $alarm->{'skip_fire'} > $now;
	return &clock_alarm_next_ms($alarm, $from) || 0;
}

# The phone's "Skip today" button cannot call the manager, so it writes this
# little file; the alarm worker picks it up and applies the same skip the
# browser button does.
sub clock_skip_file() {
	my $dir = &home('~/.president');
	eval { File::Path::make_path($dir); } unless -d $dir;
	$dir = '/tmp' unless -d $dir;
	return $dir . '/clock_skip.json';
}

sub clock_skip_apply {
	my $file = &clock_skip_file();
	return 0 unless -e $file;
	my $raw = eval { read_file($file) } // '';
	unlink $file;
	my $data = eval { decode_json($raw) };
	return 0 unless ref $data eq 'HASH';
	my $uuid = $data->{'uuid'} || '';
	return 0 unless length $uuid;
	my $now = &rightNow();
	my $lock = &clock_lock_take();
	my $alarms = &clock_alarms_read();
	my ($alarm) = grep { ($_->{'uuid'} || '') eq $uuid } @{ $alarms };
	if (!$alarm) {
		&clock_lock_drop($lock);
		return 0;
	}
	my $at = int($data->{'at'} || 0);
	$at = &clock_alarm_next_ms($alarm, $now) if $at <= 0;
	$alarm->{'skip_fire'} = $at;
	$alarm->{'snooze_until'} = 0;
	$alarm->{'ringing'} = 0;
	$alarm->{'ring_started'} = 0;
	$alarm->{'ring_last'} = 0;
	&clock_alarms_write($alarms);
	&clock_lock_drop($lock);
	&clock_alarm_stop_sound($uuid);
	&clock_write_device_alarm($alarms, $now);
	&clock_poke($now);
	return 1;
}

# Every NFC tag row for an app, across devices. A tag is written from the phone
# that owns the reader, so its settings row may sit under that machine; the
# alarm has to find it whichever machine is editing the Clock.
sub clock_app_nfc_tags {
	my ($app) = @_;
	return [] unless defined $app && length $app;
	my $rows = eval { &db_query("select device, value from settings where app = ? and setting = 'nfc'", $app)->hashes } || [];
	my @tags;
	foreach my $r (@{ $rows || [] }) {
		my $list = eval { decode_json($r->{'value'} || '') } || [];
		next unless ref $list eq 'ARRAY';
		foreach my $t (@{$list}) {
			next unless ref $t eq 'HASH' && length($t->{'uuid'} || '');
			$t->{'device'} = $r->{'device'};
			push @tags, $t;
		}
	}
	return \@tags;
}

# The controls that start an app. A tag assigned for any of these can answer the
# linked alarm; a tag that only records or commands does not count as the
# waking-up tag.
sub clock_nfc_control_starts {
	my ($control) = @_;
	return 0 unless defined $control && length $control;
	return $control =~ /^(?:start|record|usual)$/ ? 1 : 0;
}

sub clock_app_has_nfc_start {
	my ($app) = @_;
	my $tags = &clock_app_nfc_tags($app);
	return scalar grep { &clock_nfc_control_starts($_->{'control'}) } @{ $tags || [] };
}

# app => 1 for every app with a start tag; the alarm editor uses this to offer
# the "Use NFC to snooze" box only where a tag really exists.
sub clock_nfc_start_apps {
	my $rows = eval { &db_query("select app, value from settings where setting = 'nfc'")->hashes } || [];
	my %out;
	foreach my $r (@{ $rows || [] }) {
		my $app = $r->{'app'} || '';
		next unless length $app;
		my $list = eval { decode_json($r->{'value'} || '') } || [];
		next unless ref $list eq 'ARRAY';
		foreach my $t (@{$list}) {
			next unless ref $t eq 'HASH';
			if (&clock_nfc_control_starts($t->{'control'})) { $out{$app} = 1; last; }
		}
	}
	return \%out;
}

sub clock_state() {
	my $now = &rightNow();
	my $me = &signatorial_designer() || '';
	my $alarms = &clock_alarms_read();
	my $acks = &clock_alarm_acks_read();
	my $nfc_apps = &clock_nfc_start_apps();
	foreach my $alarm (@{ $alarms }) {
		$alarm->{'next_at'} = &clock_alarm_next_at($alarm, $now);
		# A stale NFC flag on an alarm whose app no longer has a start tag must
		# not leave the phone asking for a tag that cannot answer.
		$alarm->{'nfc_ready'} = ($alarm->{'nfc'} && $nfc_apps->{$alarm->{'app'}}) ? 1 : 0;
		my $delivered = {};
		if (ref $acks->{ $alarm->{'uuid'} } eq 'HASH') {
			# Keep only confirmations of the row as it stands now: an ack from a
			# previous edit is not a confirmation that the new edit arrived.
			my $updated = int($alarm->{'updated'} || 0);
			foreach my $sig ( keys %{ $acks->{ $alarm->{'uuid'} } } ) {
				my $at = int($acks->{ $alarm->{'uuid'} }->{$sig} || 0);
				next if !$at || ($updated && $at < $updated);
				$delivered->{$sig} = $at;
			}
		}
		# This machine holds the row it is showing, so its own pill is always
		# confirmed; the check marks are for the machines the push reached.
		$delivered->{$me} = $now if length $me && &clock_alarm_targets_me($alarm);
		$alarm->{'delivered'} = $delivered;
	}
	return {
		now => $now,
		alarms => $alarms,
		timers => &clock_timers_read(),
		apps => &clock_apps(),
		sounds => &clock_sounds(),
		alarm_sounds => &clock_alarm_sounds(),
		machines => &clock_machines(),
		nfc_apps => $nfc_apps,
		me => $me,
		max => 10,
	};
}

sub clock_send_console {
	my $script = shift;
	return unless defined $script && length $script;
	eval { &Websocket::send('tab', { console => $script, timestamp => &rightNow() }); };
	return 1;
}

# How loud the OS alarm is at a moment in its ring: a little above silence at
# the start, then the alarm's own volume by the end of its ramp. The browser
# draws the ring card, but the sound belongs to the machine.
sub clock_alarm_volume_at {
	my ($alarm, $elapsed) = @_;
	my $target = (($alarm->{'volume'} || 70) / 100);
	my $ramp = ($alarm->{'ramp'} || 0) * 1000;
	my $progress = 1;
	if ($ramp > 0) {
		$progress = $elapsed / $ramp;
		$progress = 1 if $progress > 1;
		$progress = 0 if $progress < 0;
		$progress = 0.15 + (0.85 * $progress);
	}
	my $level = $target * $progress;
	$level = 0.02 if $level < 0.02;
	return sprintf('%.2f', $level);
}

# A long-form track loops until Dismiss, Snooze or the five-minute guard. The
# old reading played a recording once and left the person asleep after it ended;
# `repeat` makes the operating-system player carry the alarm the same way a
# phone's alarm channel does. The pid file still lets Dismiss stop it.
sub clock_alarm_ring_length {
	my $alarm = shift;
	return 300000;
}

# The command the OS player runs for this alarm. A long track is played once,
# at the alarm's volume, with the ramp as its fade-in, and its pid is written so
# Dismiss can stop it. A chime is played at the moment's ramped volume.
sub clock_alarm_play_command {
	my ($alarm, $elapsed) = @_;
	$elapsed ||= 0;
	my $sound = &clock_valid_alarm_sound($alarm->{'sound'}) || 'notifications/ring.mp3';
	my $file = &clock_sound_file($sound);
	if (&clock_sound_is_long($sound)) {
		my $target = sprintf('%.2f', ($alarm->{'volume'} || 70) / 100);
		my $ramp = int($alarm->{'ramp'} || 0);
		$ramp = 1 if $ramp < 1;
		my $play = 'play -q -v ' . $target . ' ' . &quote($file) . ' fade t ' . $ramp . ' repeat 1000';
		return $play . ' & echo $! > ' . &clock_alarm_pidfile($alarm->{'uuid'});
	}
	my $level = &clock_alarm_volume_at($alarm, $elapsed);
	return 'play -q -v ' . $level . ' ' . &quote($file) . ' fade t 1';
}

# Play one repetition of a short chime through the operating system. The
# notification at the first ring carries the first sound; later rings use this
# one directly, so the volume climbs across the ramp and no notification row is
# written each time. A long-form track is never repeated this way.
sub clock_alarm_sound {
	my ($alarm, $elapsed) = @_;
	$elapsed ||= 0;
	my $sound = &clock_valid_alarm_sound($alarm->{'sound'}) || 'notifications/ring.mp3';
	return '' if &clock_sound_is_long($sound);
	# On a phone the app owns the sound: it loops the chime on the alarm channel
	# and stops it on Dismiss. A Perl player here would sound on the media
	# stream beside it.
	return '' if &device_setter() eq 'mobile';
	my $command = &clock_alarm_play_command($alarm, $elapsed);
	eval {
		&subprocessor(sub { &run_command('clock', $command); }, { name => 'clock alarm sound' });
	};
	return $command;
}

sub clock_alarm_cmd {
	my ($alarm, $fire_at, $now) = @_;
	my $payload = {
		uuid => $alarm->{'uuid'},
		label => $alarm->{'label'},
		hour => $alarm->{'hour'},
		minute => $alarm->{'minute'},
		sound => $alarm->{'sound'},
		volume => $alarm->{'volume'},
		ramp => $alarm->{'ramp'},
		snooze => int($alarm->{'snooze'} || 5),
		play => ($alarm->{'play'} || ''),
		nfc => (($alarm->{'nfc'} || 0) && &clock_app_has_nfc_start($alarm->{'app'})) ? 1 : 0,
		nfc_action => ($alarm->{'nfc_action'} || 'snooze'),
		app => $alarm->{'app'},
		fired_at => $fire_at,
	};
	my $json = encode_json($payload);
	$json =~ s/\x{2028}/\\u2028/g;
	$json =~ s/\x{2029}/\\u2029/g;
	&clock_send_console('jawnosClockAlarmRing(' . $json . ');');
	return $payload;
}

sub clock_alarm_ring {
	my ($alarm, $fire_at, $now) = @_;
	$now = &rightNow() unless defined $now;
	# The ring begins here and is repeated by the firing loop until Dismiss or
	# Snooze clears it (or the five-minute guard runs out).
	$alarm->{'ringing'} = 1;
	$alarm->{'ring_started'} = $now;
	$alarm->{'ring_last'} = $now;
	&clock_alarm_cmd($alarm, $fire_at, $now);
	&clock_device_ring($alarm, $fire_at);

	my $label = $alarm->{'label'} || 'Alarm';
	my $app = $alarm->{'app'} || '';
	my $message = $app ? $label . ' - ' . &format_name($app) : $label;
	my $sound_path = &clock_valid_alarm_sound($alarm->{'sound'}) || 'notifications/ring.mp3';
	my $sound = $sound_path;
	$sound =~ s{.*/}{};
	# On a phone the app sounds the alarm on the alarm channel; the Perl player
	# would talk over it on the media stream.
	my $mobile = (&device_setter() eq 'mobile') ? 1 : 0;
	my $play = $mobile ? '' : &clock_alarm_play_command($alarm, 0);

	# The alarm turns its linked appointment on. A session already running is the
	# same activity and is left alone, so a late tick cannot open a second one.
	# The uuid is derived from the alarm and the fire, so two machines that both
	# ring the same alarm write the one start row instead of two.
	if ($app && !&open_session_uuid($app)) {
		my $start_uuid = 'clockalarm' . ($alarm->{'uuid'} || '') . int(($fire_at || $now) / 60000);
		eval {
			&Manager::appointment_writer(undef, {
				app => $app,
				type => 'start',
				uuid => $start_uuid,
				timestamp => $now,
				server_time => $now,
			});
		};
	}

	eval {
		my %note = (
			app => 'clock',
			role => 'all',
			type => 'clock',
			title => $label,
			message => $message,
			image => '/icons/alarm.svg',
			words => ' ',
		);
		if ($mobile) { $note{'silent'} = 1; }
		else { $note{'sound'} = $sound; $note{'synth'} = $play; }
		&Manager::notification_sender(\%note, undef);
	};
	return 1;
}

sub clock_timer_finish {
	my ($timer, $now) = @_;
	$now = &rightNow() unless defined $now;
	my $label = $timer->{'label'} || 'Timer';
	my $app = $timer->{'app'} || '';
	# The countdown's own end is when the activity ended, even when the alarm
	# worker was asleep and reads it a little late; the server_time stays now so
	# every machine takes the row in the usual order.
	my $ended = $timer->{'ends_at'} || $now;

	if ($app && $timer->{'appt_uuid'}) {
		eval {
			&Manager::appointment_writer(undef, {
				app => $app,
				type => 'stop',
				uuid => $timer->{'appt_uuid'},
				timestamp => $ended,
				server_time => $now,
			});
		};
	}

	my $payload = {
		uuid => $timer->{'uuid'},
		label => $label,
		app => $app,
		seconds => $timer->{'seconds'},
		ended_at => $timer->{'ends_at'},
	};
	my $json = encode_json($payload);
	$json =~ s/\x{2028}/\\u2028/g;
	$json =~ s/\x{2029}/\\u2029/g;
	&clock_send_console('jawnosClockTimerDone(' . $json . ');');

	my $sound_path = &clock_valid_timer_sound($timer->{'sound'});
	my $sound = $sound_path;
	$sound =~ s{.*/}{};
	my $file = &clock_sound_file($sound_path);
	my $play = 'play -q -v 0.7 ' . &quote($file);
	# A phone sounds the timer on the alarm channel through the app.
	my $mobile = (&device_setter() eq 'mobile') ? 1 : 0;
	&clock_device_timer($timer) if $mobile;
	eval {
		my %note = (
			app => 'clock',
			role => 'all',
			type => 'clock',
			title => &lang('timer'),
			message => $label . ($app ? ' - ' . &format_name($app) : '') . ' finished',
			image => '/icons/timer.svg',
			words => ' ',
		);
		if ($mobile) { $note{'silent'} = 1; }
		else { $note{'sound'} = $sound; $note{'synth'} = $play; }
		&Manager::notification_sender(\%note, undef);
	};
	return 1;
}

# One pass of the clock's own clock. Called by Alarm.pl; returns the next moment
# it should be woken for, or undef when there is nothing waiting.
# --------------------------------------------------------------------------
# Per-machine ring state
#
# The alarm list is shared, but the sound is local. Each machine remembers the
# fire it has already handled and when its own ring began, so a peer syncing
# the row mid-ring cannot make it ring twice. A dismiss or snooze is carried on
# the shared row (`stop_at`, `snooze_until`) and, for speed, relayed to the
# machines the alarm names.
sub clock_ring_file() {
	my $dir = &home('~/.president');
	eval { File::Path::make_path($dir); } unless -d $dir;
	$dir = '/tmp' unless -d $dir;
	return $dir . '/clock_rings.json';
}

sub clock_rings_read() {
	my $file = &clock_ring_file();
	return {} unless -e $file;
	my $raw = eval { &read_file($file) } // '';
	my $rings = eval { decode_json($raw) };
	return ref $rings eq 'HASH' ? $rings : {};
}

sub clock_rings_write {
	my $rings = shift || {};
	eval { write_file(&clock_ring_file(), encode_json($rings)) };
	return $rings;
}

# Hand a dismiss/snooze/stop_all to the machines that carry the alarm. The
# shared settings row reaches them as well; this is what makes the stop
# immediate rather than whenever the next sync runs. Quiet about a peer that is
# away - the row will still catch it up.
sub clock_relay {
	my ($action, $uuid, $machines, %extra) = @_;
	my $self = &signatorial_designer() || '';
	my @want = grep { defined $_ && length $_ && $_ ne $self } @{ $machines || [] };
	return 0 unless scalar @want;
	# Resolve each target through the peer lister, not the raw roster row: a
	# phone advertises its own 127.0.0.1 as the manager, which is unreachable
	# from the machine pressing Dismiss. The lister swaps it for the LAN address.
	my @peers;
	foreach my $sig (@want) {
		my $rm = &clock_alarm_peer_row($sig);
		push @peers, [ $sig, $rm ] if $rm && $rm->{'manager'};
	}
	return 0 unless scalar @peers;
	my %form = ( action => $action, relayed => 'yes', signatorial => ($self || ''), uuid => ($uuid || '') );
	foreach my $key ( keys %extra ) {
		next unless defined $extra{$key};
		$form{$key} = $extra{$key};
	}
	eval {
		&subprocessor(sub {
			foreach my $peer (@peers) {
				my ($sig, $rm) = @{$peer};
				eval {
					# remote_useragent_maker returns the peer row with a 'ua' and
					# the tunnel-aware 'manager' url, not a bare agent.
					my $hop = &Manager::remote_useragent_maker({ rm => $rm, signatorial => $sig });
					if ($hop && $hop->{'ua'} && $hop->{'manager'}) {
						$hop->{'ua'}->insecure(1)->post($hop->{'manager'} . '/manager/clock/alarm' => form => \%form)->result;
					}
				};
			}
		}, { name => 'clock relay' });
	};
	return 1;
}

# ---- confirmed, immediate alarm sharing -------------------------------------
# The shared settings row carries an alarm to the other machines eventually, on
# the normal sync pass. These helpers push a single edit now, wait for the peer
# to answer, and record who confirmed. A peer that does not answer directly is
# offered the edit through another reachable machine, one hop only.
sub clock_alarm_ack_file() {
	my $dir = &home('~/.president');
	eval { File::Path::make_path($dir); } unless -d $dir;
	$dir = '/tmp' unless -d $dir;
	return $dir . '/clock_acks.json';
}

sub clock_alarm_acks_read() {
	my $file = &clock_alarm_ack_file();
	return {} unless -e $file;
	my $raw = eval { &read_file($file) } // '';
	my $acks = eval { decode_json($raw) };
	return ref $acks eq 'HASH' ? $acks : {};
}

sub clock_alarm_acks_write {
	my $acks = shift || {};
	eval { write_file(&clock_alarm_ack_file(), encode_json($acks)) };
	return $acks;
}

sub clock_alarm_mark_ack {
	my ($uuid, $sig, $now) = @_;
	return 0 unless defined $uuid && length $uuid && defined $sig && length $sig;
	$now = &rightNow() unless defined $now;
	my $acks = &clock_alarm_acks_read();
	$acks->{$uuid} = {} unless ref $acks->{$uuid} eq 'HASH';
	$acks->{$uuid}->{$sig} = int($now);
	# keep the little file from growing; a ring older than a week is history
	foreach my $u ( keys %{$acks} ) {
		next unless ref $acks->{$u} eq 'HASH';
		my $newest = 0;
		foreach my $s ( keys %{ $acks->{$u} } ) {
			$newest = $acks->{$u}->{$s} if ($acks->{$u}->{$s} || 0) > $newest;
		}
		delete $acks->{$u} if !$newest || ($now - $newest) > 604800000;
	}
	&clock_alarm_acks_write($acks);
	return 1;
}

# The roster rows a push can reach, by signatorial. A same-LAN row may carry no
# manager URL; the lister builds one when the push finds it missing.
sub clock_alarm_peers() {
	my $rows = eval { &db_query('select hostname, signatorial, manager, ip, port, device, network from remote_machines')->hashes } || [];
	my %by_sig;
	foreach my $rm (@{ $rows || [] }) {
		my $sig = $rm->{'signatorial'} || '';
		next unless length $sig;
		$by_sig{$sig} = $rm;
	}
	return \%by_sig;
}

# One target's row, resolved the way the rest of the peer rail resolves a peer.
# A machine advertises the manager it answers on, which on an Android handset is
# its own 127.0.0.1: using that verbatim made every alarm push to the phone fail
# with "Connection refused" and no confirmation was ever recorded. The lister
# swaps a loopback or dead tailnet manager for the LAN address the peer
# advertised, so a phone on the house network is reached directly.
sub clock_alarm_peer_row {
	my ($sig) = @_;
	return undef unless defined $sig && length $sig;
	my $row = eval {
		&remote_machine_lister({ signatorial => $sig, limit => 1, mirrors => 'none', self => 'no' });
	};
	if (ref $row eq 'HASH' && ($row->{'signatorial'} || '') eq $sig && ($row->{'manager'} || '') =~ m{^https?://}) {
		return $row;
	}
	my $fallback = eval {
		&db_query('select hostname, signatorial, manager, ip, port, device, network from remote_machines where signatorial = ?', $sig)->hash;
	};
	return ref $fallback eq 'HASH' ? $fallback : undef;
}

# Push one alarm edit. Returns { delivered => [...], failed => [...] }. The
# ack file is written here, so the next /manager/clock/state already shows the ✓.
sub clock_alarm_push {
	my ($alarm, $op, $machines, $now, $allow_forward) = @_;
	$alarm = {} unless ref $alarm eq 'HASH';
	my $uuid = $alarm->{'uuid'} || '';
	my $result = { delivered => [], failed => [] };
	return $result unless length $uuid;
	$op = ($op || '') eq 'delete' ? 'delete' : 'upsert';
	$now = &rightNow() unless defined $now;
	# An acknowledgement belongs to one edit, so stamp it with the row's own
	# `updated` value. A ✓ from an earlier edit must not outlive the change.
	my $stamp = int($alarm->{'updated'} || $now);
	$allow_forward = 1 unless defined $allow_forward;
	my $self = &signatorial_designer() || '';
	my %want;
	foreach my $sig ( @{ $machines || [] } ) {
		next unless defined $sig && length $sig && $sig ne $self;
		$want{$sig} = 1;
	}
	return $result unless scalar keys %want;
	my $rows = &clock_alarm_peers();
	my %form = (
		action => 'remote_apply',
		relayed => 'yes',
		signatorial => ($self || ''),
		op => $op,
		uuid => $uuid,
		server_time => $now,
	);
	if ($op eq 'upsert') { $form{'alarm'} = encode_json($alarm); }
	else { $form{'updated'} = int($alarm->{'updated'} || $now); }

	my @failed;
	foreach my $sig ( sort keys %want ) {
		# Always resolve through the lister: a stored manager can be the peer's
		# own loopback (Android) or a tailnet name whose node is away.
		my $rm = &clock_alarm_peer_row($sig);
		if (!$rm || !$rm->{'manager'}) { push @failed, $sig; next; }
		my $ok = 0;
		my $err = '';
		eval {
			# The maker hands back the peer row (with 'ua' and the
			# tunnel-aware 'manager' url); using it as an agent meant every
			# immediate push died and no confirmation was ever possible.
			my $hop = &Manager::remote_useragent_maker({ rm => $rm, signatorial => $sig });
			die "no agent\n" unless $hop && $hop->{'ua'} && $hop->{'manager'};
			my $ua = $hop->{'ua'}->insecure(1);
			$ua->inactivity_timeout(4)->request_timeout(4);
			my $res = $ua->post($hop->{'manager'} . '/manager/clock/alarm' => form => \%form)->result;
			die "no answer\n" unless $res && $res->is_success;
			my $body = eval { decode_json($res->body) } || {};
			$ok = 1 if $body->{'ok'};
			if ($body->{'ok'} && ref $body->{'forwarded'} eq 'ARRAY') {
				foreach my $fs ( @{ $body->{'forwarded'} } ) {
					next unless defined $fs && length $fs;
					&clock_alarm_mark_ack($uuid, $fs, $stamp);
				}
			}
		};
		$err = $@;
		if ($ok) {
			push @{ $result->{'delivered'} }, $sig;
			&clock_alarm_mark_ack($uuid, $sig, $stamp);
		}
		else {
			warn 'clock alarm push ' . $sig . ' failed: ' . ($err =~ s/\s+/ /gr) . "\n" if $err;
			push @failed, $sig unless grep { $_ eq $sig } @failed;
		}
	}

	# A machine that did not answer directly may still be reachable from another
	# peer. Ask a reachable third machine to hand the same edit on, and trust its
	# own delivered list. One hop only, so two disconnected machines cannot loop.
	if ($allow_forward && scalar @failed) {
		my %failed = map { $_ => 1 } @failed;
		# Candidates are the peers that are not targets and did not fail. Ask the
		# server first: when two machines cannot see each other (different
		# networks, a phone whose LAN address a peer cannot route), the server is
		# the one place both can reach, so it forwards the edit for us.
		my @relays = grep { !$failed{$_} && !$want{$_} && $_ ne $self } keys %{ $rows };
		@relays = sort {
			my $ad = (($rows->{$a} || {})->{'device'} || '') eq 'server' ? 0 : 1;
			my $bd = (($rows->{$b} || {})->{'device'} || '') eq 'server' ? 0 : 1;
			$ad <=> $bd || $a cmp $b;
		} @relays;
		my $tries = 0;
		my @still = @failed;
		foreach my $relay_sig (@relays) {
			last if !scalar @still || $tries >= 3;
			$tries++;
			my $rm = &clock_alarm_peer_row($relay_sig);
			next unless $rm && $rm->{'manager'};
			eval {
				my $hop = &Manager::remote_useragent_maker({ rm => $rm, signatorial => $relay_sig });
				die "no agent\n" unless $hop && $hop->{'ua'} && $hop->{'manager'};
				my $ua = $hop->{'ua'}->insecure(1);
				$ua->inactivity_timeout(5)->request_timeout(5);
				my %fwd = %form;
				$fwd{'forward_to'} = join(',', @still);
				my $res = $ua->post($hop->{'manager'} . '/manager/clock/alarm' => form => \%fwd)->result;
				die "no answer\n" unless $res && $res->is_success;
				my $body = eval { decode_json($res->body) } || {};
				die "not ok\n" unless $body->{'ok'} && ref $body->{'forwarded'} eq 'ARRAY';
				my %done = map { $_ => 1 } @{ $body->{'forwarded'} };
				foreach my $fs ( keys %done ) {
					&clock_alarm_mark_ack($uuid, $fs, $stamp);
					push @{ $result->{'delivered'} }, $fs;
				}
				@still = grep { !$done{$_} } @still;
			};
		}
		@failed = @still;
	}
	$result->{'failed'} = [ @failed ];
	return $result;
}

# Apply an edit that arrived from a peer. A per-alarm `updated` stamp decides
# between two copies; the shared row still converges later either way.
sub clock_apply_remote_alarm {
	my ($alarm, $op, $now) = @_;
	return 0 unless ref $alarm eq 'HASH' && length($alarm->{'uuid'} || '');
	my $uuid = $alarm->{'uuid'};
	$op = ($op || '') eq 'delete' ? 'delete' : 'upsert';
	$now = &rightNow() unless defined $now;
	my $incoming = int($alarm->{'updated'} || $now);
	my $lock = &clock_lock_take();
	my $alarms = &clock_alarms_read();
	my ($idx) = grep { ($alarms->[$_] || {})->{'uuid'} eq $uuid } 0 .. $#$alarms;
	my $changed = 0;
	my $kept;
	if ($op eq 'delete') {
		if (defined $idx && int($alarms->[$idx]->{'updated'} || 0) <= $incoming) {
			splice(@{$alarms}, $idx, 1);
			$changed = 1;
		}
	}
	else {
		my $next = &clock_normalize_alarm($alarm);
		$next->{'updated'} = $incoming;
		if (defined $idx) {
			if (int($alarms->[$idx]->{'updated'} || 0) <= $incoming) {
				$alarms->[$idx] = $next;
				$changed = 1;
			}
			$kept = $alarms->[$idx];
		}
		else {
			push @{$alarms}, $next;
			$kept = $next;
			$changed = 1;
		}
	}
	if ($changed) {
		&clock_alarms_write($alarms);
		# a stop that arrived on the peer rail must end this machine's sound now
		if ($op eq 'delete' || !$kept || !$kept->{'ringing'}) {
			my $rings = &clock_rings_read();
			if (ref $rings->{$uuid} eq 'HASH' && $rings->{$uuid}->{'ringing'}) {
				$rings->{$uuid}->{'ringing'} = 0;
				$rings->{$uuid}->{'stopped'} = $now;
				&clock_rings_write($rings);
			}
		}
	}
	&clock_lock_drop($lock);
	if ($changed) {
		&clock_alarm_stop_sound($uuid) if ($op eq 'delete' || !$kept || !$kept->{'ringing'});
		&clock_device_dismissed($uuid) if ($op eq 'delete' || !$kept || !$kept->{'ringing'});
		&clock_write_device_alarm($alarms, $now);
		&clock_poke($now);
		&clock_send_console('jawnosClockRefresh();');
	}
	return $changed;
}

# The phone's notification buttons and the lock-screen gestures cannot call the
# manager, so they leave a small request here; the alarm worker applies it within
# a couple of seconds. The file holds one request and is removed as it is read.
sub clock_control_file() {
	my $dir = &home('~/.president');
	eval { File::Path::make_path($dir); } unless -d $dir;
	$dir = '/tmp' unless -d $dir;
	return $dir . '/clock_control.json';
}

sub clock_control_apply {
	my $file = &clock_control_file();
	return 0 unless -e $file;
	my $raw = eval { read_file($file) } // '';
	unlink $file;
	my $data = eval { decode_json($raw) };
	return 0 unless ref $data eq 'HASH';
	my $action = lc($data->{'action'} || '');
	return 0 unless $action =~ /^(?:dismiss|snooze|stop_all)$/;
	my $uuid = $data->{'uuid'} || '';
	my $now = &rightNow();
	my $lock = &clock_lock_take();
	my $alarms = &clock_alarms_read();
	my $relay_machines = [];
	my $changed = 0;
	if ($action eq 'stop_all') {
		foreach my $a ( @{$alarms} ) {
			$a->{'snooze_until'} = 0;
			$a->{'ringing'} = 0;
			$a->{'ring_started'} = 0;
			$a->{'ring_last'} = 0;
			$a->{'stop_at'} = $now;
			$a->{'updated'} = $now;
			$changed = 1;
		}
		$relay_machines = [ map { $_->{'value'} } @{ &clock_machines() } ];
	}
	elsif (length $uuid) {
		my ($alarm) = grep { ($_->{'uuid'} || '') eq $uuid } @{$alarms};
		if ($alarm) {
			# An alarm can hand its snooze/dismiss to the NFC tag assigned to the
			# linked app. The phone writes the tag's uuid with the request; a tag
			# that is not assigned, or is assigned to another control, leaves the
			# alarm ringing. The ring payload only asks for NFC when a start tag
			# exists, so a deleted tag cannot strand the alarm.
			my $nfc_required = ($alarm->{'nfc'} || 0) && &clock_app_has_nfc_start($alarm->{'app'});
			if ($nfc_required) {
				my $tag_uuid = $data->{'nfc_uuid'} || '';
				my ($tag) = grep {
					($_->{'uuid'} || '') eq $tag_uuid && &clock_nfc_control_starts($_->{'control'})
				} @{ &clock_app_nfc_tags($alarm->{'app'}) };
				unless ($tag) {
					&clock_lock_drop($lock);
					&clock_device_broadcast('com.termux.app.JAWN_CLOCK_REJECT', uuid => $uuid);
					return 0;
				}
			}
			$relay_machines = $alarm->{'machines'} || [];
			$alarm->{'snooze_until'} = 0;
			$alarm->{'ringing'} = 0;
			$alarm->{'ring_started'} = 0;
			$alarm->{'ring_last'} = 0;
			$alarm->{'stop_at'} = $now;
			if ($action eq 'snooze') {
				my $minutes = $data->{'minutes'};
				$minutes = $alarm->{'snooze'} unless defined $minutes && "$minutes" =~ /^\d+$/;
				$minutes = 5 unless defined $minutes && "$minutes" =~ /^\d+$/;
				$minutes = 1 if $minutes < 1;
				$minutes = 60 if $minutes > 60;
				$alarm->{'snooze_until'} = $now + ($minutes * 60000);
				$data->{'minutes'} = $minutes;
			}
			$alarm->{'updated'} = $now;
			$changed = 1;
		}
	}
	&clock_alarms_write($alarms) if $changed;
	&clock_lock_drop($lock);
	return 0 unless $changed;
	if ($action eq 'stop_all') { foreach my $a (@{$alarms}) { &clock_alarm_stop_sound($a->{'uuid'}); } }
	else { &clock_alarm_stop_sound($uuid); }
	&clock_write_device_alarm($alarms, $now);
	&clock_send_console('jawnosClockAlarmStop();');
	&clock_device_dismissed($action eq 'stop_all' ? '' : $uuid);
	&clock_relay($action eq 'snooze' ? 'snooze' : 'dismiss', ($action eq 'stop_all' ? '' : $uuid), $relay_machines,
		($action eq 'snooze' ? (minutes => $data->{'minutes'} || 5) : ()));
	my @push = grep { $action eq 'stop_all' || ($_->{'uuid'} || '') eq $uuid } @{$alarms};
	if (scalar @push) {
		&subprocessor(sub {
			foreach my $a (@push) { eval { &clock_alarm_push($a, 'upsert', $relay_machines, $now); }; }
		}, { name => 'clock control push' });
	}
	&clock_poke($now);
	return 1;
}

# A future appointment in an app whose notification panel has Alarm on becomes
# one Clock alarm, linked back to that appointment. Re-saving the appointment
# moves the same Clock row; the next future one replaces it, so an app never
# collects a pile of stale alarms.
sub clock_appointment_sync {
	my ($appt) = @_;
	my $row = ref $appt eq 'HASH' ? $appt : {};
	my $app = $row->{'app'} || (defined $appt && !ref $appt ? "$appt" : '');
	$app =~ s/^\s+|\s+$//g if defined $app;
	return 0 unless defined $app && length $app;
	my $want = eval { &setting_grabber({ app => $app, setting => 'alarm' }) };
	$want = (defined $want && $want =~ /^(?:on|yes|1|checked)$/i) ? 1 : 0;
	my $now = &rightNow();
	my $lock = &clock_lock_take();
	my $alarms = &clock_alarms_read();
	my ($auto) = grep { ($_->{'source'} || '') eq 'appointment' && ($_->{'app'} || '') eq $app } @{$alarms};
	my $next;
	if ($want) {
		$next = eval { &db_query('select uuid, timestamp from appointments where app = ? and timestamp > ? order by timestamp asc limit 1', $app, $now)->hash };
	}
	if (!$want || !$next || !($next->{'timestamp'} || 0)) {
		if ($auto && ($auto->{'enabled'} || $auto->{'appt_uuid'})) {
			$auto->{'enabled'} = 0;
			$auto->{'appt_uuid'} = '';
			$auto->{'ringing'} = 0;
			$auto->{'ring_started'} = 0;
			$auto->{'ring_last'} = 0;
			$auto->{'updated'} = $now;
			&clock_alarms_write($alarms);
			&clock_lock_drop($lock);
			&clock_write_device_alarm($alarms, $now);
			my $disabled = $auto;
			&subprocessor(sub { eval { &clock_alarm_push($disabled, 'upsert', $disabled->{'machines'}, $now); }; }, { name => 'clock appointment push' });
			&clock_poke($now);
			return 1;
		}
		&clock_lock_drop($lock);
		return 0;
	}
	my @lt = localtime(int($next->{'timestamp'} / 1000));
	my ($hour, $minute) = ($lt[2], $lt[3]);
	my $label = &format_name($app) || $app;
	$label = substr($label, 0, 20);
	$label = 'Alarm' unless length $label;
	if ($auto) {
		# nothing moved: leave the row (and its confirmation stamps) alone
		if (int($auto->{'hour'}) == $hour && int($auto->{'minute'}) == $minute
			&& ($auto->{'appt_uuid'} || '') eq ($next->{'uuid'} || '') && $auto->{'enabled'}) {
			&clock_lock_drop($lock);
			return 0;
		}
	}
	else {
		if (scalar @{$alarms} >= 10) { &clock_lock_drop($lock); return 0; }
		$auto = &clock_normalize_alarm({
			uuid => &random_string_creator(24),
			snooze => 5,
			volume => 70,
			ramp => 60,
			sound => 'notifications/ring.mp3',
			machines => [ &signatorial_designer() || '' ],
			created => $now,
		});
		push @{$alarms}, $auto;
	}
	$auto->{'hour'} = $hour;
	$auto->{'minute'} = $minute;
	$auto->{'days'} = [];
	$auto->{'enabled'} = 1;
	$auto->{'label'} = $label;
	$auto->{'app'} = $app;
	$auto->{'appt_uuid'} = $next->{'uuid'} || '';
	$auto->{'source'} = 'appointment';
	$auto->{'snooze_until'} = 0;
	$auto->{'ringing'} = 0;
	$auto->{'ring_started'} = 0;
	$auto->{'ring_last'} = 0;
	$auto->{'updated'} = $now;
	$auto->{'machines'} = [ &signatorial_designer() || '' ] unless scalar @{ $auto->{'machines'} || [] };
	&clock_alarms_write($alarms);
	&clock_lock_drop($lock);
	&clock_write_device_alarm($alarms, $now);
	&subprocessor(sub { eval { &clock_alarm_push($auto, 'upsert', $auto->{'machines'}, $now); }; }, { name => 'clock appointment push' });
	&clock_poke($now);
	return 1;
}

sub clock_tick() {
	my $now = &rightNow();
	my $lock = &clock_lock_take();
	my ($next, $changed) = (undef, 0);
	my @actions;
	eval {
		my $alarms = &clock_alarms_read();
		my $timers = &clock_timers_read();
		my $rings = &clock_rings_read();
		my $alarms_changed = 0;
		my $timers_changed = 0;
		my $rings_changed = 0;

		foreach my $alarm (@{ $alarms }) {
			my $uuid = $alarm->{'uuid'} || '';
			next unless length $uuid;
			my $targeted = &clock_alarm_targets_me($alarm);
			my $ring = ref $rings->{$uuid} eq 'HASH' ? $rings->{$uuid} : undef;

			# Already sounding on this machine: repeat a chime, and stop when the
			# ring guard runs out or a dismiss/snooze reached the shared row.
			if ($ring && $ring->{'ringing'}) {
				my $elapsed = $now - ($ring->{'started'} || $now);
				my $long = &clock_sound_is_long($alarm->{'sound'});
				my $stop_at = $alarm->{'stop_at'} || 0;
				my $stopped = !$targeted || !$alarm->{'ringing'} || ($stop_at != ($ring->{'base'} || 0));
				if ($stopped || $elapsed >= &clock_alarm_ring_length($alarm)) {
					push @actions, [ 'stop_sound', $uuid ] if $long;
					$ring->{'ringing'} = 0;
					$ring->{'stopped'} = $now;
					$rings_changed = 1;
					$changed = 1;
					# Only the machine whose guard has run out clears the shared
					# flag, so a peer that started a moment later is not cut short.
					if ($alarm->{'ringing'} && $elapsed >= &clock_alarm_ring_length($alarm)) {
						$alarm->{'ringing'} = 0;
						$alarm->{'ring_started'} = 0;
						$alarm->{'ring_last'} = 0;
						$alarms_changed = 1;
						push @actions, [ 'device_dismiss', $uuid ];
					}
				}
				elsif (!$long && (!$ring->{'last'} || ($now - $ring->{'last'}) >= 15000)) {
					push @actions, [ 'sound', $alarm, $elapsed ];
					$ring->{'last'} = $now;
					$rings_changed = 1;
				}
				next;
			}

			next unless $targeted;
			next unless $alarm->{'enabled'} || $alarm->{'snooze_until'};
			# A snooze waiting in the future means the regular time is not due.
			next if $alarm->{'snooze_until'} && $alarm->{'snooze_until'} > $now;
			my $fire_at;
			if ($alarm->{'snooze_until'} && $alarm->{'snooze_until'} <= $now && $now - $alarm->{'snooze_until'} <= 120000) {
				$fire_at = $alarm->{'snooze_until'};
			}
			elsif ($alarm->{'enabled'}) {
				my $candidate = &clock_alarm_next_ms($alarm, $now - 120000);
				$fire_at = $candidate if $candidate && $candidate <= $now;
			}
			next unless $fire_at;
			# A skipped occurrence stays in the schedule but does not sound.
			next if $alarm->{'skip_fire'} && $fire_at <= $alarm->{'skip_fire'};
			# A fire that was dismissed (or snoozed) elsewhere before this machine
			# got there does not ring late.
			next if $alarm->{'stop_at'} && $fire_at <= $alarm->{'stop_at'};
			# The local record is the guard, not the shared last_fire: every
			# targeted machine rings the same fire once.
			next if $ring && ($ring->{'fire'} || 0) >= $fire_at;
			$rings->{$uuid} = {
				fire => $fire_at,
				started => $now,
				last => $now,
				base => ($alarm->{'stop_at'} || 0),
				ringing => 1,
			};
			$rings_changed = 1;
			$alarm->{'last_fire'} = int($fire_at / 60000);
			$alarm->{'snooze_until'} = 0;
			$alarm->{'enabled'} = 0 unless scalar @{ $alarm->{'days'} || [] };
			$alarm->{'ringing'} = 1;
			$alarm->{'ring_started'} = $now;
			$alarm->{'ring_last'} = $now;
			$alarms_changed = 1;
			$changed = 1;
			push @actions, [ 'ring', $alarm, $fire_at, $now ];
		}

		# Forget ring records a few days old so the little file cannot grow.
		foreach my $u ( keys %{$rings} ) {
			my $r = $rings->{$u};
			next unless ref $r eq 'HASH';
			my $when = $r->{'started'} || $r->{'fire'} || 0;
			next unless $when && ($now - $when) > 259200000;
			delete $rings->{$u};
			$rings_changed = 1;
		}

		foreach my $timer (@{ $timers }) {
			next unless ($timer->{'state'} || '') eq 'running';
			next unless $timer->{'ends_at'} && $timer->{'ends_at'} <= $now + 500;
			$timer->{'state'} = 'done';
			$timer->{'ended_at'} = $timer->{'ends_at'};
			$timers_changed = 1;
			$changed = 1;
			push @actions, [ 'timer', $timer, $now ];
		}

		&clock_alarms_write($alarms) if $alarms_changed;
		&clock_timers_write($timers) if $timers_changed;
		&clock_rings_write($rings) if $rings_changed;
		push @actions, [ 'device_sync', $alarms, $now ];
		$next = &clock_next_wake($alarms, $timers, $now, $rings);
	};
	warn 'clock tick: ' . $@ if $@;
	&clock_lock_drop($lock);

	# The ring, the repeated OS sound and the appointment stop all fork their
	# own players; they run after the lock is released so a two-second chime
	# cannot hold a save out of the alarm list.
	foreach my $action (@actions) {
		my $kind = $action->[0];
		if ($kind eq 'ring') {
			eval { &clock_alarm_ring($action->[1], $action->[2], $action->[3]); };
		}
		elsif ($kind eq 'sound') {
			eval { &clock_alarm_sound($action->[1], $action->[2]); };
		}
		elsif ($kind eq 'stop_sound') {
			eval { &clock_alarm_stop_sound($action->[1]); };
		}
		elsif ($kind eq 'device_dismiss') {
			eval { &clock_device_dismissed($action->[1]); };
		}
		elsif ($kind eq 'device_sync') {
			eval { &clock_write_device_alarm($action->[1], $action->[2]); };
		}
		elsif ($kind eq 'timer') {
			eval { &clock_timer_finish($action->[1], $action->[2]); };
		}
		warn 'clock action: ' . $@ if $@;
	}
	&clock_send_console('jawnosClockRefresh();') if $changed;
	return $next;
}

1;
